var e=JSON.parse(`[{"wordId":15627,"answer":"ordeals","form":"복수형","example":"The survivors described two separate ordeals during the long expedition.","exampleTranslation":"생존자들은 그 긴 원정 동안 겪은 별개의 고난 두 가지를 설명했다.","sense":"고난"},{"wordId":15628,"answer":"ore","form":"원형","example":"The mining company extracted iron ore from the mountain for decades.","exampleTranslation":"그 광산 회사는 수십 년 동안 그 산에서 철광석을 채굴했다.","sense":"광석"},{"wordId":15629,"answer":"oscars","form":"복수형","example":"The film received two oscars at the ceremony held last spring.","exampleTranslation":"그 영화는 지난봄 열린 시상식에서 아카데미상 두 개를 받았다.","sense":"아카데미상"},{"wordId":15630,"answer":"oscillating","form":"-ing형","example":"The oscillating fan kept the whole bedroom cool all through the summer.","exampleTranslation":"그 회전하는 선풍기는 여름 내내 침실 전체를 시원하게 유지해 주었다.","sense":"진동하다"},{"wordId":15630,"answer":"is oscillating","form":"현재진행","example":"Her mood is oscillating between hope and worry again this whole week.","exampleTranslation":"이번 주 내내 그녀의 기분은 또다시 희망과 걱정 사이에서 진동하고 있다.","sense":"진동하다"},{"wordId":15631,"answer":"ostensible","form":"원형","example":"Her ostensible role was project advisor, though she rarely attended any actual meetings.","exampleTranslation":"그녀의 표면상의 역할은 프로젝트 자문역이었지만 실제 회의에는 거의 참석하지 않았다.","sense":"표면상의"},{"wordId":15631,"answer":"ostensibly","form":"부사형","example":"He was ostensibly attending the conference, though he spent most of it sightseeing.","exampleTranslation":"그는 표면상으로는 학회에 참석하는 것이었지만 대부분의 시간을 관광하며 보냈다.","sense":"표면상의"},{"wordId":15632,"answer":"ousted","form":"과거형","example":"The board ousted the leader after the financial scandal broke last spring.","exampleTranslation":"지난봄 재정 스캔들이 터진 뒤 이사회는 대표를 몰아냈다.","sense":"몰아내다"},{"wordId":15632,"answer":"has ousted","form":"현재완료","example":"This new coalition has ousted the ruling party from three regions since spring.","exampleTranslation":"봄 이후로 이 새 연합은 세 지역에서 집권당을 몰아내 왔다.","sense":"몰아내다"},{"wordId":15633,"answer":"outings","form":"복수형","example":"The class organized two outings to local museums during the semester.","exampleTranslation":"그 학급은 학기 동안 지역 박물관으로 나들이 두 번을 계획했다.","sense":"나들이"},{"wordId":15634,"answer":"outlaws","form":"복수형","example":"The sheriff finally captured two outlaws who had robbed the local bank.","exampleTranslation":"보안관은 지역 은행을 턴 무법자 두 명을 마침내 붙잡았다.","sense":"무법자","alts":["rogues"]},{"wordId":15635,"answer":"outskirts","form":"원형","example":"They bought a quiet farmhouse on the outskirts of the busy city.","exampleTranslation":"그들은 번잡한 도시 변두리에 있는 조용한 농가를 샀다.","sense":"변두리"},{"wordId":15636,"answer":"outweighed","form":"과거형","example":"The benefits clearly outweighed the risks when the board voted last year.","exampleTranslation":"작년 이사회가 투표했을 때 이익은 분명히 위험을 능가했다.","sense":"능가하다"},{"wordId":15636,"answer":"have outweighed","form":"현재완료","example":"The costs have outweighed the savings since the machine broke down twice.","exampleTranslation":"그 기계가 두 번 고장 난 이후로 비용은 계속 절감액을 능가해 왔다.","sense":"능가하다","alts":["has trumped"]},{"wordId":15637,"answer":"overcrowded","form":"과거분사","example":"The overcrowded classroom made it hard for the teacher to help every student.","exampleTranslation":"그 과밀한 교실 때문에 선생님이 모든 학생을 돕기가 어려웠다.","sense":"과밀하게 하다"},{"wordId":15637,"answer":"will overcrowd","form":"미래","example":"New arrivals will overcrowd the shelter unless more space opens up soon.","exampleTranslation":"곧 더 많은 공간이 생기지 않으면 새로 온 사람들이 그 보호소를 과밀하게 만들 것이다.","sense":"과밀하게 하다"},{"wordId":15638,"answer":"overhauls","form":"복수형","example":"The airline scheduled two overhauls for each aircraft every five years.","exampleTranslation":"그 항공사는 오 년마다 각 항공기에 전면 점검 두 번을 예정했다.","sense":"전면점검"},{"wordId":15639,"answer":"overhears","form":"3인칭 단수형","example":"She often overhears interesting conversations while riding the crowded subway.","exampleTranslation":"그녀는 붐비는 지하철을 탈 때 종종 흥미로운 대화를 우연히 듣는다.","sense":"우연히 듣다"},{"wordId":15639,"answer":"am overhearing","form":"현재진행","example":"I am overhearing two coworkers discussing the merger in the break room right now.","exampleTranslation":"지금 나는 휴게실에서 동료 두 명이 합병에 대해 이야기하는 것을 우연히 듣고 있다.","sense":"우연히 듣다"},{"wordId":15640,"answer":"overtook","form":"과거형","example":"The runner overtook the leader just before the final turn last Saturday.","exampleTranslation":"지난 토요일 그 주자는 마지막 커브 직전에 선두를 추월했다.","sense":"추월하다"},{"wordId":15640,"answer":"has overtaken","form":"현재완료","example":"This budget category has overtaken all others since the new project began.","exampleTranslation":"그 새 프로젝트가 시작된 이후로 이 예산 항목은 다른 모든 항목을 추월해 왔다.","sense":"추월하다"},{"wordId":15641,"answer":"overweight","form":"원형","example":"The veterinarian warned that the cat had become slightly overweight over the winter.","exampleTranslation":"수의사는 그 고양이가 겨울 동안 약간 과체중이 되었다고 경고했다.","sense":"과체중인"},{"wordId":15641,"answer":"overweight","form":"원형","example":"Doctors recommend more exercise for patients who are overweight and want to lower blood pressure.","exampleTranslation":"의사들은 과체중이면서 혈압을 낮추고 싶어 하는 환자들에게 더 많은 운동을 권장한다.","sense":"과체중인"},{"wordId":15642,"answer":"oxides","form":"복수형","example":"Chemists identified several oxides forming on the metal surface over time.","exampleTranslation":"화학자들은 시간이 지나면서 금속 표면에 생기는 산화물 여러 가지를 확인했다.","sense":"산화물"},{"wordId":15643,"answer":"oysters","form":"복수형","example":"The restaurant served a dozen fresh oysters as the evening's appetizer.","exampleTranslation":"그 식당은 저녁 전채로 신선한 굴 열두 개를 제공했다.","sense":"석화","alts":["burrows"]},{"wordId":15644,"answer":"pagans","form":"복수형","example":"The historian explained how ancient pagans celebrated the arrival of spring.","exampleTranslation":"그 역사학자는 고대 이교도들이 봄의 도래를 기념한 방식을 설명했다.","sense":"이교도"},{"wordId":15645,"answer":"palettes","form":"복수형","example":"The artist cleaned two palettes before starting a fresh painting session.","exampleTranslation":"그 화가는 새로운 그리기 시간을 시작하기 전 팔레트 두 개를 닦았다.","sense":"팔레트"},{"wordId":15646,"answer":"pamphlets","form":"복수형","example":"Volunteers distributed pamphlets about the upcoming election in three languages.","exampleTranslation":"자원봉사자들은 세 개 언어로 된 다가오는 선거 관련 소책자를 나눠 주었다.","sense":"소책자"},{"wordId":15648,"answer":"papal","form":"원형","example":"The pope makes several papal visits to different countries each year.","exampleTranslation":"교황은 매년 여러 나라로 교황 방문을 다닌다.","sense":"교황의"},{"wordId":15648,"answer":"papacy","form":"명사형","example":"Historians studied how the papacy gained enormous political power during the medieval period.","exampleTranslation":"역사학자들은 중세 시대에 교황청이 어떻게 막대한 정치적 힘을 얻었는지 연구했다.","sense":"교황의"},{"wordId":15649,"answer":"parachutes","form":"복수형","example":"The instructor checked two parachutes carefully before the training jump.","exampleTranslation":"강사는 훈련 낙하 전에 낙하산 두 개를 꼼꼼히 점검했다.","sense":"낙하산"},{"wordId":15650,"answer":"paramount","form":"원형","example":"Safety remains paramount whenever workers operate heavy machinery on the site.","exampleTranslation":"일꾼들이 현장에서 중장비를 다룰 때는 안전이 가장 중요하다.","sense":"가장중요한"},{"wordId":15650,"answer":"paramount","form":"원형","example":"The committee agreed that transparency is paramount during any public budget negotiation.","exampleTranslation":"위원회는 공공 예산 협상에서는 투명성이 가장 중요하다는 데 동의했다.","sense":"가장중요한"},{"wordId":15651,"answer":"parlors","form":"복수형","example":"The old mansion had two elegant parlors used only for special guests.","exampleTranslation":"그 오래된 저택에는 귀한 손님만을 위한 우아한 응접실 두 곳이 있었다.","sense":"응접실"},{"wordId":15652,"answer":"parodies","form":"복수형","example":"The comedy troupe performed two parodies of popular superhero movies.","exampleTranslation":"그 코미디 극단은 인기 슈퍼히어로 영화의 패러디 두 편을 공연했다.","sense":"패러디"},{"wordId":15653,"answer":"parrots","form":"복수형","example":"The pet shop kept several parrots that could mimic simple phrases.","exampleTranslation":"그 애완동물 가게는 간단한 문구를 따라 할 수 있는 앵무새 여러 마리를 키웠다.","sense":"앵무새"},{"wordId":15654,"answer":"parsley","form":"원형","example":"The chef sprinkled fresh parsley over the soup right before serving.","exampleTranslation":"요리사는 내놓기 직전 수프 위에 신선한 파슬리를 뿌렸다.","sense":"파슬리"},{"wordId":15655,"answer":"partiality","form":"원형","example":"The referee was suspended after showing clear partiality toward one team.","exampleTranslation":"그 심판은 한 팀을 향한 뚜렷한 편파성을 보인 뒤 정직당했다.","sense":"편파성"},{"wordId":15656,"answer":"partitions","form":"복수형","example":"The office installed two partitions to create separate meeting spaces.","exampleTranslation":"그 사무실은 별도의 회의 공간을 만들려고 칸막이 두 개를 설치했다.","sense":"칸막이"},{"wordId":15657,"answer":"pastors","form":"복수형","example":"Two pastors led the joint service between the neighboring churches.","exampleTranslation":"목사 두 명이 이웃 교회들 간의 합동 예배를 이끌었다.","sense":"목사","alts":["reverends"]},{"wordId":15658,"answer":"pathology","form":"원형","example":"She spent three years training in pathology before joining the hospital.","exampleTranslation":"그녀는 그 병원에 합류하기 전 삼 년 동안 병리학 훈련을 받았다.","sense":"병리학"},{"wordId":15659,"answer":"patios","form":"복수형","example":"The new homes all feature spacious patios overlooking the shared garden.","exampleTranslation":"그 새 주택들은 모두 공용 정원이 내려다보이는 널찍한 테라스를 갖추고 있다.","sense":"야외테라스"},{"wordId":15660,"answer":"patronage","form":"원형","example":"The small theater survived for decades thanks to loyal community patronage.","exampleTranslation":"그 작은 극장은 지역 사회의 변함없는 후원 덕분에 수십 년을 버텼다.","sense":"후원"},{"wordId":15661,"answer":"pavilions","form":"복수형","example":"The exhibition featured two pavilions dedicated to renewable energy technology.","exampleTranslation":"그 박람회는 재생 에너지 기술을 다루는 전시관 두 곳을 마련했다.","sense":"파빌리온"},{"wordId":15662,"answer":"paws","form":"복수형","example":"The puppy lifted both paws and rested them on her lap.","exampleTranslation":"그 강아지는 앞발 두 개를 들어 그녀의 무릎 위에 올려놓았다.","sense":"앞발","alts":["feet"]},{"wordId":15663,"answer":"payroll","form":"원형","example":"The startup struggled to cover payroll during its first difficult year.","exampleTranslation":"그 스타트업은 힘겨웠던 첫해 동안 급여 지급을 감당하느라 애를 먹었다.","sense":"급여지급"},{"wordId":15664,"answer":"peanuts","form":"복수형","example":"The vendor sold roasted peanuts outside the stadium before every game.","exampleTranslation":"그 노점상은 매 경기 전 경기장 밖에서 볶은 땅콩을 팔았다.","sense":"땅콩"},{"wordId":15665,"answer":"pears","form":"복수형","example":"She packed two pears and a sandwich for the long hike.","exampleTranslation":"그녀는 긴 등산을 위해 배 두 개와 샌드위치를 챙겼다.","sense":"배(과일)","alts":["bellies","boats"]},{"wordId":15666,"answer":"pebbles","form":"복수형","example":"Children collected smooth pebbles along the quiet lake shore.","exampleTranslation":"아이들은 조용한 호숫가를 따라 매끈한 조약돌을 모았다.","sense":"조약돌"},{"wordId":15667,"answer":"pedagogy","form":"원형","example":"Her doctoral research focused on pedagogy in under-resourced rural schools.","exampleTranslation":"그녀의 박사 연구는 자원이 부족한 농촌 학교의 교육학에 초점을 맞췄다.","sense":"교육학"},{"wordId":15668,"answer":"pegs","form":"복수형","example":"The campers hammered several pegs into the ground to secure the tent.","exampleTranslation":"야영객들은 텐트를 고정하려고 땅에 못 여러 개를 박았다.","sense":"못"},{"wordId":15669,"answer":"perennial","form":"원형","example":"Traffic congestion remains a perennial complaint among residents living near the downtown bridge.","exampleTranslation":"시내 다리 근처에 사는 주민들 사이에서 교통 체증은 계속 반복되는 불만거리다.","sense":"반복되는"},{"wordId":15669,"answer":"perennially","form":"부사형","example":"The coastal town is perennially crowded with tourists escaping the summer heat.","exampleTranslation":"그 해안 마을은 여름 더위를 피해 온 관광객들로 늘 붐빈다.","sense":"다년생의"},{"wordId":15670,"answer":"perimeters","form":"복수형","example":"Guards checked the perimeters of both warehouses every night.","exampleTranslation":"경비원들은 매일 밤 두 창고의 둘레를 점검했다.","sense":"둘레"},{"wordId":15671,"answer":"perishes","form":"3인칭 단수형","example":"Fresh produce like this usually perishes within just a few days.","exampleTranslation":"이런 신선 식품은 보통 불과 며칠 안에 상해 못 쓰게 된다.","sense":"죽다"},{"wordId":15671,"answer":"is perishing","form":"현재진행","example":"Wildlife is perishing across the region during this year's severe drought.","exampleTranslation":"올해의 심한 가뭄 동안 그 지역 전역에서 야생동물이 죽어 가고 있다.","sense":"죽다","alts":["is dying"]},{"wordId":15672,"answer":"perks","form":"복수형","example":"The new job offers perks such as flexible hours and free meals.","exampleTranslation":"그 새 일자리는 유연한 근무 시간과 무료 식사 같은 특권을 제공한다.","sense":"혜택","alts":["privileges"]},{"wordId":15673,"answer":"perpetrated","form":"과거분사","example":"The fraud perpetrated by a former employee cost the company millions.","exampleTranslation":"전직 직원이 저지른 그 사기는 회사에 수백만 달러의 손실을 입혔다.","sense":"저지르다"},{"wordId":15673,"answer":"will perpetrate","form":"미래","example":"Investigators believe this same network will perpetrate similar scams again soon.","exampleTranslation":"수사관들은 이 같은 조직이 곧 다시 비슷한 사기를 저지를 것이라고 믿는다.","sense":"저지르다"},{"wordId":15674,"answer":"perpetual","form":"원형","example":"The office building runs on a perpetual power supply thanks to its rooftop solar panels.","exampleTranslation":"그 사무용 건물은 옥상 태양광 패널 덕분에 영구적인 전력 공급을 받는다.","sense":"영구적인"},{"wordId":15674,"answer":"perpetually","form":"부사형","example":"Her grandfather was perpetually cheerful, even during the hospital's longest winter.","exampleTranslation":"그녀의 할아버지는 병원에서 가장 길었던 겨울에도 늘 명랑하셨다.","sense":"한결같은","alts":["permanently"]},{"wordId":15675,"answer":"perpetuates","form":"3인칭 단수형","example":"This old policy still perpetuates inequality across the whole district.","exampleTranslation":"이 낡은 정책은 여전히 그 지역 전체의 불평등을 영속시킨다.","sense":"영속시키다"},{"wordId":15675,"answer":"is perpetuating","form":"현재진행","example":"This textbook is perpetuating several outdated stereotypes even in its newest edition.","exampleTranslation":"이 교과서는 최신판에서조차 여러 낡은 고정관념을 영속시키고 있다.","sense":"영속시키다"},{"wordId":15676,"answer":"more pervasive","form":"비교급","example":"Social media seems to be more pervasive among teenagers than it was a decade ago.","exampleTranslation":"소셜미디어는 십 년 전보다 십대들 사이에서 더 만연한 것 같다.","sense":"만연한"},{"wordId":15676,"answer":"pervasively","form":"부사형","example":"Corruption spread pervasively throughout the local government before the new reforms began.","exampleTranslation":"새 개혁이 시작되기 전 지방 정부 전체에 부패가 널리 퍼져 있었다.","sense":"만연한"},{"wordId":15677,"answer":"most perverse","form":"최상급","example":"Of all the characters in the play, the villain seemed the most perverse.","exampleTranslation":"그 연극의 모든 등장인물 중에서 그 악당이 가장 비뚤어져 보였다.","sense":"비뚤어진"},{"wordId":15677,"answer":"perversion","form":"명사형","example":"The novel explores a strange perversion of justice within the corrupt legal system.","exampleTranslation":"그 소설은 부패한 사법 체계 속 정의의 기이한 왜곡을 다룬다.","sense":"비뚤어진"},{"wordId":15678,"answer":"petals","form":"복수형","example":"Soft pink petals covered the ground beneath the old cherry tree.","exampleTranslation":"그 오래된 벚나무 아래 땅은 부드러운 분홍 꽃잎으로 뒤덮였다.","sense":"꽃잎"},{"wordId":15679,"answer":"physiological","form":"원형","example":"The coach explained the physiological changes that occur during long-distance running.","exampleTranslation":"코치는 장거리 달리기 중 일어나는 생리학적 변화를 설명했다.","sense":"생리학적인"},{"wordId":15679,"answer":"physiology","form":"명사형","example":"Understanding human physiology helped the trainer design a safer workout program.","exampleTranslation":"인체의 생리를 이해한 덕분에 트레이너는 더 안전한 운동 프로그램을 설계할 수 있었다.","sense":"생리학적인"},{"wordId":15680,"answer":"pickets","form":"복수형","example":"Workers set up pickets outside the factory gate early in the morning.","exampleTranslation":"노동자들은 이른 아침 공장 정문 밖에 피켓 시위 줄을 세웠다.","sense":"피켓시위"},{"wordId":15681,"answer":"pickles","form":"복수형","example":"The deli added extra pickles to every sandwich without being asked.","exampleTranslation":"그 델리는 부탁하지 않아도 모든 샌드위치에 피클을 더 넣어 주었다.","sense":"피클"},{"wordId":15682,"answer":"pigments","form":"복수형","example":"Artists often mix several natural pigments to create unique paint colors.","exampleTranslation":"화가들은 독특한 물감 색을 만들기 위해 여러 천연 색소를 섞곤 한다.","sense":"색소"},{"wordId":15683,"answer":"pikes","form":"복수형","example":"Several soldiers carried long pikes into the fierce battle that morning.","exampleTranslation":"그날 아침 여러 병사가 치열한 전투에 긴 창을 들고 나섰다.","sense":"장창","alts":["lances","spears"]},{"wordId":15684,"answer":"pinpointed","form":"과거형","example":"The mechanic pinpointed the strange noise within just a few minutes yesterday.","exampleTranslation":"어제 그 정비사는 불과 몇 분 만에 이상한 소음의 원인을 정확히 찾아냈다.","sense":"찾아내다"},{"wordId":15684,"answer":"has pinpointed","form":"현재완료","example":"This new scanner has pinpointed several hidden leaks since the plumbers started using it.","exampleTranslation":"배관공들이 사용하기 시작한 이후로 이 새 스캐너는 여러 숨겨진 누수를 정확히 찾아내 왔다.","sense":"찾아내다"},{"wordId":15685,"answer":"planks","form":"복수형","example":"Workers replaced several broken planks on the old wooden deck yesterday.","exampleTranslation":"일꾼들은 어제 낡은 나무 데크의 부서진 판자 여러 장을 교체했다.","sense":"판자"},{"wordId":15686,"answer":"plaques","form":"복수형","example":"Bronze plaques on the wall mark where several famous poets were born.","exampleTranslation":"벽에 걸린 청동 명판들은 여러 유명 시인이 태어난 곳을 나타낸다.","sense":"명판"},{"wordId":15687,"answer":"plateaus","form":"복수형","example":"The explorers crossed several high plateaus during their long journey north.","exampleTranslation":"탐험가들은 북쪽으로 향하는 긴 여정 동안 여러 높은 고원을 가로질렀다.","sense":"고원"},{"wordId":15688,"answer":"plight","form":"원형","example":"The volunteers worked hard to improve the plight of stray animals in the city.","exampleTranslation":"자원봉사자들은 도시의 유기동물이 처한 곤경을 개선하려고 애썼다.","sense":"곤경"},{"wordId":15689,"answer":"plums","form":"복수형","example":"She picked several ripe plums from the tree in her backyard.","exampleTranslation":"그녀는 뒤뜰 나무에서 잘 익은 자두를 여러 개 땄다.","sense":"자두"},{"wordId":15690,"answer":"plumes","form":"복수형","example":"Multiple plumes of thick smoke rose from the factory chimneys last night.","exampleTranslation":"지난밤 공장 굴뚝에서 짙은 연기 기둥이 여러 개 피어올랐다.","sense":"연기기둥"},{"wordId":15691,"answer":"plumpest","form":"최상급","example":"Of all the tomatoes in the basket, she chose the plumpest one for the salad.","exampleTranslation":"바구니 속 토마토 중에서 그녀는 샐러드에 넣을 가장 통통한 것을 골랐다.","sense":"통통한","alts":["stoutest"]},{"wordId":15691,"answer":"plumpness","form":"명사형","example":"The baker judged each berry's plumpness before adding it to the tart.","exampleTranslation":"제빵사는 타르트에 넣기 전 각 베리가 얼마나 통통한지 살폈다.","sense":"통통한"},{"wordId":15692,"answer":"pneumonia","form":"원형","example":"Doctors treated the elderly man for pneumonia after he developed a severe cough and fever.","exampleTranslation":"의사들은 그 노인이 심한 기침과 열이 난 뒤 폐렴 치료를 해 주었다.","sense":"폐렴"},{"wordId":15693,"answer":"poaching","form":"-ing형","example":"Poaching endangered elephants remains a serious crime in this national reserve.","exampleTranslation":"멸종 위기의 코끼리를 밀렵하는 것은 이 국립 보호구역에서 여전히 심각한 범죄다.","sense":"밀렵하다"},{"wordId":15693,"answer":"will poach","form":"미래","example":"This rival firm will poach several top engineers if it offers higher salaries.","exampleTranslation":"더 높은 연봉을 제시하면 이 경쟁사는 여러 우수한 엔지니어를 가로챌 것이다.","sense":"가로채다"},{"wordId":15694,"answer":"polo","form":"원형","example":"She bought a light blue polo for her younger brother's birthday last month.","exampleTranslation":"그녀는 남동생의 생일 선물로 지난달에 하늘색 폴로 셔츠를 샀다.","sense":"폴로셔츠"},{"wordId":15695,"answer":"polymers","form":"복수형","example":"Scientists study many different polymers used in modern food packaging today.","exampleTranslation":"과학자들은 오늘날 식품 포장에 쓰이는 다양한 중합체를 여러 개 연구한다.","sense":"중합체"},{"wordId":15696,"answer":"more portable","form":"비교급","example":"This new laptop model is more portable than the one she bought last year.","exampleTranslation":"이 새 노트북 모델은 그녀가 작년에 산 것보다 더 휴대하기 편하다.","sense":"휴대용"},{"wordId":15696,"answer":"portability","form":"명사형","example":"Engineers improved the device's portability by cutting its weight nearly in half.","exampleTranslation":"엔지니어들은 무게를 거의 절반으로 줄여 그 기기를 더 가지고 다니기 쉽게 만들었다.","sense":"휴대용의"},{"wordId":15697,"answer":"portals","form":"복수형","example":"Students submit their assignments through several different online portals each semester.","exampleTranslation":"학생들은 학기마다 여러 다른 온라인 포털을 통해 과제를 제출한다.","sense":"포털"},{"wordId":15698,"answer":"poultry","form":"원형","example":"The farm raises poultry alongside dairy cows on its large property outside town.","exampleTranslation":"그 농장은 마을 밖 넓은 부지에서 젖소와 함께 가금류를 기른다.","sense":"가금류"},{"wordId":15700,"answer":"more precarious","form":"비교급","example":"Her financial situation became more precarious after she suddenly lost her job.","exampleTranslation":"그녀는 갑자기 일자리를 잃은 뒤 재정 상황이 더 불안정해졌다.","sense":"불안정한"},{"wordId":15700,"answer":"precariously","form":"부사형","example":"The old ladder leaned precariously against the wall of the abandoned barn.","exampleTranslation":"그 낡은 사다리는 버려진 헛간 벽에 위태롭게 기대어 있었다.","sense":"불안정한"},{"wordId":15701,"answer":"precluding","form":"-ing형","example":"Precluding any further changes was the whole point of that strict clause.","exampleTranslation":"더 이상의 변경을 막는 것이 그 엄격한 조항의 전체 취지였다.","sense":"저지하다","alts":["Blocking"]},{"wordId":15701,"answer":"will preclude","form":"미래","example":"This clause will preclude any changes to the contract once both sides sign it.","exampleTranslation":"양측이 서명하면 이 조항은 계약의 어떤 변경도 막을 것이다.","sense":"불가능하게 하다","alts":["will foil","will obstruct"]},{"wordId":15702,"answer":"premieres","form":"복수형","example":"The director attended several film premieres across Europe during the festival season.","exampleTranslation":"그 감독은 영화제 기간 동안 유럽 여러 곳의 영화 초연에 참석했다.","sense":"초연"},{"wordId":15703,"answer":"presupposes","form":"3인칭 단수형","example":"This kind of argument usually presupposes that everyone shares the same values.","exampleTranslation":"이런 종류의 주장은 보통 모두가 같은 가치관을 공유한다고 전제한다.","sense":"전제하다"},{"wordId":15703,"answer":"is presupposing","form":"현재진행","example":"His whole argument is presupposing a level of trust that simply does not exist.","exampleTranslation":"그의 주장 전체는 실제로는 존재하지 않는 수준의 신뢰를 전제하고 있다.","sense":"전제하다"},{"wordId":15704,"answer":"previews","form":"복수형","example":"I watched several previews of the new series before deciding to subscribe.","exampleTranslation":"나는 구독을 결정하기 전에 새 시리즈의 예고편 여러 개를 미리 보았다.","sense":"미리보기"},{"wordId":15705,"answer":"procured","form":"과거분사","example":"Every ingredient in this dish was locally procured from nearby farms.","exampleTranslation":"이 요리의 모든 재료는 인근 농장에서 현지 조달되었다.","sense":"조달하다"},{"wordId":15705,"answer":"will procure","form":"미래","example":"This department will procure new laptops for the whole staff next quarter.","exampleTranslation":"다음 분기에 이 부서는 전체 직원을 위한 새 노트북을 조달할 것이다.","sense":"조달하다"},{"wordId":15706,"answer":"prodding","form":"-ing형","example":"Prodding her brother awake before the alarm went off became her daily habit.","exampleTranslation":"알람이 울리기 전에 남동생을 찔러 깨우는 것은 그녀의 일상 습관이 되었다.","sense":"찌르다"},{"wordId":15706,"answer":"was prodded","form":"수동태","example":"The sleepy student was prodded awake by his classmate right before the quiz.","exampleTranslation":"그 졸린 학생은 퀴즈 직전 친구에게 찔려 잠에서 깼다.","sense":"찌르다"},{"wordId":15707,"answer":"proliferates","form":"3인칭 단수형","example":"This kind of online scam usually proliferates fastest during the holiday season.","exampleTranslation":"이런 종류의 온라인 사기는 보통 명절 시즌에 가장 빠르게 급증한다.","sense":"급증하다"},{"wordId":15707,"answer":"are proliferating","form":"현재진행","example":"Delivery apps are proliferating across the city again this whole year.","exampleTranslation":"올해 내내 배달 앱들이 도시 전역에서 또다시 급증하고 있다.","sense":"급증하다"},{"wordId":15708,"answer":"prominent","form":"형용사형","example":"The young senator became prominent nationwide after his passionate speech on healthcare.","exampleTranslation":"그 젊은 상원의원은 의료 정책에 관한 열정적인 연설 후 전국적으로 유명해졌다.","sense":"두드러짐"},{"wordId":15709,"answer":"propaganda","form":"원형","example":"The regime spread propaganda through radio broadcasts to control public opinion during the crisis.","exampleTranslation":"그 정권은 위기 동안 여론을 통제하기 위해 라디오 방송으로 선전을 퍼뜨렸다.","sense":"선전"},{"wordId":15710,"answer":"propagating","form":"-ing형","example":"Propagating roses from a single cutting takes real patience and skill.","exampleTranslation":"꺾꽂이 하나로 장미를 번식시키는 데는 진짜 인내와 기술이 필요하다.","sense":"번식하다"},{"wordId":15710,"answer":"is propagated","form":"수동태","example":"False information is propagated quickly through social media these days.","exampleTranslation":"요즘 거짓 정보는 소셜 미디어를 통해 빠르게 퍼진다.","sense":"전파하다","alts":["is disseminated","was circulated"]},{"wordId":15711,"answer":"proponents","form":"복수형","example":"Several proponents of renewable energy spoke at the city council meeting.","exampleTranslation":"여러 재생에너지 지지자가 시의회 회의에서 발언했다.","sense":"옹호자","alts":["supporters"]},{"wordId":15712,"answer":"protagonists","form":"복수형","example":"The novel follows two protagonists whose lives become connected after a car accident.","exampleTranslation":"그 소설은 교통사고 이후 삶이 얽히게 되는 두 주인공을 따라간다.","sense":"주인공"},{"wordId":15713,"answer":"provisional","form":"원형","example":"The government introduced a provisional plan to house refugees until permanent shelters were built.","exampleTranslation":"정부는 영구 보호소가 지어질 때까지 난민을 수용할 임시 계획을 도입했다.","sense":"임시의"},{"wordId":15713,"answer":"provisionally","form":"부사형","example":"The new employee was provisionally hired while the company completed his background check.","exampleTranslation":"그 신입 사원은 회사가 신원 조회를 마칠 때까지 잠정적으로 채용되었다.","sense":"잠정적인","alts":["temporarily","tentatively"]},{"wordId":15714,"answer":"pruning","form":"-ing형","example":"Pruning the rose bushes every autumn keeps them healthy through the winter.","exampleTranslation":"매년 가을 장미 덤불을 가지치기하는 것은 겨울 내내 그것들을 건강하게 유지해 준다.","sense":"가지치기하다"},{"wordId":15714,"answer":"was pruned","form":"수동태","example":"The old oak tree was pruned carefully by a professional last autumn.","exampleTranslation":"지난가을 전문가가 조심스럽게 그 오래된 참나무를 가지치기했다.","sense":"가지치기하다"},{"wordId":15715,"answer":"most psychic","form":"최상급","example":"Among her sisters, everyone agreed that Maria seemed the most psychic person in the family.","exampleTranslation":"언니들 사이에서 다들 마리아가 가족 중 가장 초자연적인 사람이라고 입을 모았다.","sense":"초자연"},{"wordId":15715,"answer":"psychically","form":"부사형","example":"The twins claimed they felt psychically connected even when living in different countries.","exampleTranslation":"그 쌍둥이는 서로 다른 나라에 살아도 텔레파시로 통하는 느낌이 든다고 말했다.","sense":"초자연적인"},{"wordId":15716,"answer":"punctuated","form":"과거형","example":"She punctuated her email carefully before sending it to the client yesterday.","exampleTranslation":"어제 그녀는 고객에게 보내기 전에 이메일에 조심스럽게 구두점을 찍었다.","sense":"구두점찍다"},{"wordId":15716,"answer":"has punctuated","form":"현재완료","example":"Loud thunder has punctuated the quiet evening since the storm rolled in.","exampleTranslation":"그 폭풍이 밀려온 이후로 요란한 천둥이 계속 조용한 저녁을 끊어 놓았다.","sense":"구두점찍다"},{"wordId":15717,"answer":"punks","form":"복수형","example":"Several punks in leather jackets gathered outside the concert hall every weekend.","exampleTranslation":"가죽 재킷을 입은 불량배 몇 명이 주말마다 콘서트홀 밖에 모였다.","sense":"불량배"},{"wordId":15718,"answer":"puppets","form":"복수형","example":"The children laughed as several colorful puppets danced across the little stage.","exampleTranslation":"아이들은 알록달록한 꼭두각시 여러 개가 작은 무대 위에서 춤추는 것을 보고 웃었다.","sense":"꼭두각시"},{"wordId":15719,"answer":"purges","form":"3인칭 단수형","example":"This antivirus program usually purges threats automatically every single night.","exampleTranslation":"이 백신 프로그램은 보통 매일 밤 자동으로 위협 요소를 제거한다.","sense":"제거하다"},{"wordId":15719,"answer":"is purging","form":"현재진행","example":"The new manager is purging all outdated files from the shared drive right now.","exampleTranslation":"지금 새 관리자는 공유 드라이브에서 낡은 파일을 모두 제거하고 있다.","sense":"제거하다"},{"wordId":15720,"answer":"purified","form":"과거형","example":"The new filter purified the well water before the family drank it last year.","exampleTranslation":"작년 그 새 필터는 가족이 마시기 전에 우물물을 정화했다.","sense":"정화하다"},{"wordId":15720,"answer":"has purified","form":"현재완료","example":"This system has purified the factory's wastewater since it was installed last spring.","exampleTranslation":"지난봄 설치된 이후로 이 시스템은 공장의 폐수를 계속 정화해 왔다.","sense":"정화하다"},{"wordId":15721,"answer":"purported","form":"과거분사","example":"The purported author of the letter later denied writing it at all.","exampleTranslation":"그 편지의 작성자로 주장된 사람은 나중에 그것을 썼다는 것 자체를 부인했다.","sense":"주장하다"},{"wordId":15721,"answer":"will purport","form":"미래","example":"This new document will purport to prove ownership once it is filed next week.","exampleTranslation":"다음 주 제출되면 이 새 문서는 소유권을 증명한다고 주장할 것이다.","sense":"주장하다","alts":["will insist"]},{"wordId":15722,"answer":"pajamas","form":"원형","example":"The children put on their pajamas quickly and jumped straight into bed.","exampleTranslation":"아이들은 재빨리 파자마를 입고 곧장 침대로 뛰어들었다.","sense":"파자마"},{"wordId":15723,"answer":"quartets","form":"복수형","example":"The festival featured several string quartets performing classical pieces every evening.","exampleTranslation":"그 축제에서는 매일 저녁 여러 현악 사중주단이 클래식 곡을 연주했다.","sense":"사중주"},{"wordId":15724,"answer":"quilts","form":"복수형","example":"Her grandmother hand-stitched several beautiful quilts for each of her grandchildren.","exampleTranslation":"그녀의 할머니는 손주들 각자를 위해 아름다운 누비이불을 여러 채 손수 만들었다.","sense":"누비이불"},{"wordId":15725,"answer":"quivering","form":"-ing형","example":"Her quivering voice revealed just how nervous she really was during the speech.","exampleTranslation":"연설 동안 그녀의 떨리는 목소리는 그녀가 실제로 얼마나 긴장했는지를 드러냈다.","sense":"떨리다"},{"wordId":15725,"answer":"will quiver","form":"미래","example":"His voice will quiver with nerves again the moment he steps onto that stage.","exampleTranslation":"그가 그 무대에 오르는 순간 그의 목소리는 또다시 긴장으로 떨릴 것이다.","sense":"떨리다"},{"wordId":15726,"answer":"quizzes","form":"복수형","example":"The teacher gave several short quizzes to check if students understood the lesson.","exampleTranslation":"선생님은 학생들이 수업을 이해했는지 확인하려고 짧은 퀴즈를 여러 번 냈다.","sense":"퀴즈"},{"wordId":15727,"answer":"rackets","form":"복수형","example":"She bought two new tennis rackets before the summer tournament began.","exampleTranslation":"그녀는 여름 대회가 시작되기 전에 새 테니스 라켓 두 개를 샀다.","sense":"라켓"},{"wordId":15728,"answer":"radiant","form":"형용사형","example":"Everyone in the room noticed how radiant she looked on her wedding day.","exampleTranslation":"결혼식 날 그녀가 얼마나 환하게 빛나 보였는지 방 안 모두가 알아챘다.","sense":"광채"},{"wordId":15729,"answer":"radii","form":"복수형","example":"In geometry class, we measured the radii of three different circles on the board.","exampleTranslation":"기하 수업에서 우리는 칠판에 그려진 세 개의 다른 원의 반지름을 측정했다.","sense":"반지름"},{"wordId":15730,"answer":"rafts","form":"복수형","example":"They built two simple rafts out of logs to cross the wide river safely.","exampleTranslation":"그들은 넓은 강을 안전하게 건너기 위해 통나무로 뗏목 두 개를 만들었다.","sense":"뗏목"},{"wordId":15731,"answer":"most ragged","form":"최상급","example":"Among all the coats in the donation box, his was clearly the most ragged.","exampleTranslation":"기부함 속 코트 중에서 그의 것이 분명히 가장 낡아 해져 있었다.","sense":"낡아해진"},{"wordId":15731,"answer":"raggedness","form":"명사형","example":"The tailor noted the raggedness of the fabric before deciding to replace it entirely.","exampleTranslation":"재단사는 옷감이 얼마나 해졌는지 살펴본 뒤 완전히 교체하기로 했다.","sense":"낡아 해진"},{"wordId":15732,"answer":"rambled","form":"과거형","example":"They rambled through the countryside for hours during their vacation last summer.","exampleTranslation":"지난여름 휴가 동안 그들은 몇 시간 동안 시골길을 산책했다.","sense":"거닐다","alts":["strolled"]},{"wordId":15732,"answer":"has rambled","form":"현재완료","example":"He has rambled on about his new car every time we meet since he bought it.","exampleTranslation":"그가 새 차를 산 이후로 만날 때마다 그는 계속 두서없이 그 이야기를 늘어놓아 왔다.","sense":"두서없이 말하다"},{"wordId":15733,"answer":"rashes","form":"복수형","example":"Doctors noticed several skin rashes breaking out among the campers that week.","exampleTranslation":"의사들은 그 주 캠프 참가자들 사이에서 여러 피부 발진이 생긴 것을 발견했다.","sense":"발진"},{"wordId":15734,"answer":"raving","form":"-ing형","example":"The raving reviews convinced her to finally try that small restaurant downtown.","exampleTranslation":"극찬하는 후기들은 그녀가 마침내 시내의 그 작은 식당을 가 보도록 설득했다.","sense":"극찬하다"},{"wordId":15734,"answer":"is raving","form":"현재진행","example":"Everyone at the office is raving about the new coffee machine again this week.","exampleTranslation":"이번 주에도 사무실의 모든 사람이 또 새 커피 머신에 대해 열광하고 있다.","sense":"열광하다"},{"wordId":15735,"answer":"razors","form":"복수형","example":"He packed two spare razors in case one broke during the long trip.","exampleTranslation":"그는 여행 중 하나가 고장 날 경우를 대비해 여분의 면도기 두 개를 챙겼다.","sense":"면도기"},{"wordId":15736,"answer":"reaped","form":"과거형","example":"Farmers reaped a record harvest across the valley last autumn.","exampleTranslation":"지난가을 농부들은 계곡 전역에서 기록적인 수확을 거두었다.","sense":"수확하다"},{"wordId":15736,"answer":"have reaped","form":"현재완료","example":"Early investors have reaped huge profits since the company went public last year.","exampleTranslation":"작년 그 회사가 상장된 이후로 초기 투자자들은 막대한 이익을 계속 얻어 왔다.","sense":"수확하다","alts":["has derived","has earned"]},{"wordId":15737,"answer":"rebounding","form":"-ing형","example":"A rebounding economy gave the whole town new reason for hope.","exampleTranslation":"반등하는 경제는 온 마을에 희망을 가질 새로운 이유를 주었다.","sense":"반등하다"},{"wordId":15737,"answer":"will rebound","form":"미래","example":"Local businesses will rebound quickly once the road construction finally ends.","exampleTranslation":"도로 공사가 마침내 끝나면 지역 상점들은 빠르게 반등할 것이다.","sense":"반등하다"},{"wordId":15738,"answer":"receding","form":"-ing형","example":"His receding hairline bothered him more than he ever admitted to anyone.","exampleTranslation":"그의 물러나는 헤어라인은 그가 누구에게도 인정한 적 없을 만큼 그를 신경 쓰이게 했다.","sense":"물러나다"},{"wordId":15738,"answer":"are receding","form":"현재진행","example":"The floodwaters are receding slowly across the whole valley right now.","exampleTranslation":"지금 홍수는 계곡 전역에서 서서히 물러나고 있다.","sense":"물러나다"},{"wordId":15739,"answer":"most receptive","form":"최상급","example":"Among all the managers, she was considered the most receptive to new ideas.","exampleTranslation":"모든 관리자 중에서 그녀가 새로운 아이디어에 가장 수용적이라고 여겨졌다.","sense":"수용적"},{"wordId":15739,"answer":"receptiveness","form":"명사형","example":"The therapist praised his receptiveness to feedback during their weekly counseling sessions.","exampleTranslation":"치료사는 매주 상담 시간마다 그가 피드백을 잘 받아들이는 태도를 칭찬했다.","sense":"수용적인"},{"wordId":15740,"answer":"receptors","form":"복수형","example":"This new drug works by blocking several receptors located inside the human brain.","exampleTranslation":"이 신약은 사람 뇌 속에 있는 여러 수용체를 차단하는 방식으로 작용한다.","sense":"수용체"},{"wordId":15741,"answer":"recesses","form":"복수형","example":"Students look forward to their morning and afternoon recesses every single day.","exampleTranslation":"학생들은 매일 오전과 오후 휴식 시간을 손꼽아 기다린다.","sense":"휴식시간"},{"wordId":15742,"answer":"reciprocal","form":"원형","example":"A good friendship requires reciprocal effort from both people involved in it.","exampleTranslation":"좋은 우정에는 관련된 두 사람 모두의 상호적인 노력이 필요하다.","sense":"상호적"},{"wordId":15742,"answer":"reciprocally","form":"부사형","example":"The two nations agreed to reciprocally lower trade tariffs starting next spring.","exampleTranslation":"두 나라는 다음 봄부터 서로 무역 관세를 낮추기로 합의했다.","sense":"상호적인"},{"wordId":15743,"answer":"redeems","form":"3인칭 단수형","example":"She redeems her loyalty points for a free coffee almost every week.","exampleTranslation":"그녀는 거의 매주 무료 커피를 위해 적립 포인트를 사용한다.","sense":"교환하다","alts":["rewards"]},{"wordId":15743,"answer":"is redeeming","form":"현재진행","example":"This player is redeeming himself with strong performances throughout this whole season.","exampleTranslation":"이번 시즌 내내 이 선수는 뛰어난 활약으로 명예를 되찾고 있다.","sense":"되찾다"},{"wordId":15744,"answer":"redemptive","form":"형용사형","example":"Critics praised the film's redemptive message about forgiveness and second chances.","exampleTranslation":"비평가들은 용서와 새로운 기회를 그린 그 영화의 구원의 메시지를 높이 평가했다.","sense":"구원"},{"wordId":15745,"answer":"reeds","form":"복수형","example":"Tall reeds grew thickly along the edge of the quiet river bank.","exampleTranslation":"키 큰 갈대들이 조용한 강둑 가장자리를 따라 빽빽하게 자랐다.","sense":"갈대"},{"wordId":15746,"answer":"reflexes","form":"복수형","example":"The goalkeeper's quick reflexes saved the team from losing the tense match.","exampleTranslation":"그 골키퍼의 빠른 반사 신경이 팀이 긴박한 경기에서 지는 것을 막아 주었다.","sense":"반사"},{"wordId":15747,"answer":"refrains","form":"3인칭 단수형","example":"He always refrains from using his phone during any kind of performance.","exampleTranslation":"그는 어떤 공연 중에도 항상 휴대폰 사용을 삼간다.","sense":"삼가다"},{"wordId":15747,"answer":"are refraining","form":"현재진행","example":"Most of the staff are refraining from ordering takeout again this whole week.","exampleTranslation":"이번 주 내내 대부분의 직원은 또다시 포장 음식 주문을 삼가고 있다.","sense":"삼가다"},{"wordId":15748,"answer":"refurbished","form":"과거형","example":"The city refurbished the old library last year to attract more visitors.","exampleTranslation":"그 도시는 작년에 방문객을 더 끌기 위해 오래된 도서관을 새로 단장했다.","sense":"단장하다"},{"wordId":15748,"answer":"has refurbished","form":"현재완료","example":"The new manager has refurbished every guest room since taking charge in spring.","exampleTranslation":"그 신임 매니저는 봄에 부임한 이후로 모든 객실을 새로 단장했다.","sense":"단장하다"},{"wordId":15749,"answer":"regenerated","form":"과거분사","example":"Volunteers were amazed by the regenerated forest that covered the hillside within a decade.","exampleTranslation":"자원봉사자들은 십 년 만에 언덕을 뒤덮은 재생된 숲을 보고 놀랐다.","sense":"재생하다"},{"wordId":15749,"answer":"will regenerate","form":"미래","example":"Scientists believe damaged coral reefs will regenerate naturally if pollution stops soon.","exampleTranslation":"과학자들은 오염이 곧 멈추면 손상된 산호초가 자연스럽게 재생될 것이라고 믿는다.","sense":"재생하다"},{"wordId":15750,"answer":"registries","form":"복수형","example":"Several countries maintain separate national registries for organ donors and recipients.","exampleTranslation":"여러 나라는 장기 기증자와 수혜자를 위한 별도의 국가 등록부를 관리한다.","sense":"등록부"},{"wordId":15751,"answer":"reimburses","form":"3인칭 단수형","example":"This particular insurance plan usually reimburses employees within thirty days of a claim.","exampleTranslation":"이 특정 보험 상품은 대개 청구 후 삼십 일 이내에 직원에게 비용을 환급해 준다.","sense":"비용을 돌려주다"},{"wordId":15751,"answer":"is reimbursing","form":"현재진행","example":"The city is reimbursing residents for storm damage caused last month, officials said.","exampleTranslation":"그 시는 지난달 발생한 폭풍 피해에 대해 현재 주민들에게 비용을 환급해 주고 있다.","sense":"비용을 돌려주다"},{"wordId":15752,"answer":"reinstated","form":"과거형","example":"The airline reinstated the canceled flight route two months ago after passenger complaints.","exampleTranslation":"그 항공사는 승객 불만이 있은 뒤 두 달 전에 취소된 항로를 복원했다.","sense":"복원하다"},{"wordId":15752,"answer":"has reinstated","form":"현재완료","example":"The committee has reinstated the annual bake sale already, in time for this summer.","exampleTranslation":"위원회는 이번 여름에 맞춰 이미 연례 빵 판매 행사를 부활시켰다.","sense":"복원하다"},{"wordId":15753,"answer":"reiterated","form":"과거분사","example":"The rule, reiterated many times during training, was still ignored by several staff members.","exampleTranslation":"직원 교육에서 여러 번 강조된 그 규칙을 몇몇 직원은 여전히 무시했다.","sense":"강조하다"},{"wordId":15753,"answer":"will reiterate","form":"미래","example":"The spokesperson will reiterate the company's new safety policy at tomorrow's meeting.","exampleTranslation":"대변인은 내일 회의에서 회사의 새 안전 정책을 다시 한번 강조할 것이다.","sense":"되풀이하다","alts":["will emphasize"]},{"wordId":15754,"answer":"Relegating","form":"-ing형","example":"Relegating the veteran player to the bench upset many loyal fans of the team.","exampleTranslation":"베테랑 선수를 벤치로 강등시킨 것은 그 팀의 많은 충성 팬들을 화나게 했다.","sense":"강등시키다"},{"wordId":15754,"answer":"was relegated","form":"수동태","example":"The struggling club was relegated to the second division at the end of last season.","exampleTranslation":"그 부진한 클럽은 지난 시즌 끝에 이부 리그로 강등되었다.","sense":"강등시키다"},{"wordId":15755,"answer":"relics","form":"복수형","example":"The museum displayed several ancient relics recovered from a sunken ship.","exampleTranslation":"그 박물관은 침몰한 배에서 발견된 고대 유물 여러 점을 전시했다.","sense":"유물","alts":["artifacts"]},{"wordId":15756,"answer":"relinquished","form":"과거형","example":"The retiring CEO relinquished control of the company just last month.","exampleTranslation":"은퇴하는 그 최고경영자는 바로 지난달에 회사의 경영권을 넘겼다.","sense":"포기하다"},{"wordId":15756,"answer":"has relinquished","form":"현재완료","example":"The former champion has relinquished her title after announcing retirement this week.","exampleTranslation":"그 전 챔피언은 이번 주에 은퇴를 발표한 뒤 자신의 타이틀을 포기했다.","sense":"포기하다"},{"wordId":15757,"answer":"remnants","form":"복수형","example":"Only a few remnants of the original forest survived after the new development.","exampleTranslation":"새 개발이 이루어진 뒤 원래 숲의 잔재는 몇 군데만 남았다.","sense":"잔재"},{"wordId":15758,"answer":"Renouncing","form":"-ing형","example":"Renouncing his claim to the family business surprised everyone at the meeting.","exampleTranslation":"가업에 대한 권리를 포기한 것은 회의에 있던 모두를 놀라게 했다.","sense":"포기하다","alts":["forgoing"]},{"wordId":15758,"answer":"was renounced","form":"수동태","example":"The old treaty was renounced by both governments soon after the border dispute began.","exampleTranslation":"그 오래된 조약은 국경 분쟁이 시작된 직후 양국 정부에 의해 철회되었다.","sense":"철회하다"},{"wordId":15759,"answer":"repeals","form":"3인칭 단수형","example":"The new mayor rarely repeals a law without holding a public hearing first.","exampleTranslation":"그 새 시장은 먼저 공청회를 열지 않고는 좀처럼 법을 폐지하지 않는다.","sense":"폐지하다"},{"wordId":15759,"answer":"is repealing","form":"현재진행","example":"The state legislature is repealing the outdated tax rule right now.","exampleTranslation":"주 의회는 지금 그 낡은 세금 규정을 폐지하고 있다.","sense":"폐지하다"},{"wordId":15760,"answer":"repelled","form":"과거형","example":"The soldiers repelled the surprise attack just before dawn yesterday.","exampleTranslation":"그 병사들은 어제 새벽이 되기 직전에 기습 공격을 격퇴했다.","sense":"격퇴하다"},{"wordId":15760,"answer":"has repelled","form":"현재완료","example":"This new spray has repelled every mosquito in our backyard since we bought it.","exampleTranslation":"이 새 스프레이는 우리가 산 뒤로 뒷마당의 모든 모기를 쫓아냈다.","sense":"쫓아내다"},{"wordId":15761,"answer":"repertoire","form":"원형","example":"The orchestra expanded its repertoire by learning several modern pieces for the spring concert.","exampleTranslation":"그 오케스트라는 봄 연주회를 위해 여러 현대곡을 배우면서 레퍼토리를 넓혔다.","sense":"레퍼토리"},{"wordId":15762,"answer":"resilient","form":"형용사형","example":"Her coworkers admired how resilient she remained after losing her job suddenly.","exampleTranslation":"동료들은 갑자기 일자리를 잃은 뒤에도 그녀가 얼마나 꿋꿋한지에 감탄했다.","sense":"회복력"},{"wordId":15763,"answer":"resonant","form":"형용사형","example":"His deep, resonant voice filled the entire concert hall without any microphone.","exampleTranslation":"그의 깊고 울림 있는 목소리는 마이크 없이도 공연장 전체를 채웠다.","sense":"공명"},{"wordId":15764,"answer":"respirators","form":"복수형","example":"Workers must wear proper respirators when handling hazardous chemicals inside the lab.","exampleTranslation":"작업자들은 실험실에서 유해 화학물질을 다룰 때 적절한 호흡기를 착용해야 한다.","sense":"호흡기"},{"wordId":15765,"answer":"Retarding","form":"-ing형","example":"Retarding the fermentation process in cold storage keeps the dough fresh for days.","exampleTranslation":"차가운 저장고에서 발효 과정을 늦추면 반죽이 며칠 동안 신선하게 유지된다.","sense":"늦추다"},{"wordId":15765,"answer":"will retard","form":"미래","example":"Adding this chemical will retard rust formation on the metal surface for years.","exampleTranslation":"이 화학 물질을 추가하면 금속 표면의 녹 형성을 여러 해 동안 늦출 것이다.","sense":"지연시키다"},{"wordId":15766,"answer":"Retorting","form":"-ing형","example":"Retorting sharply to the reporter's question only made the senator look worse.","exampleTranslation":"그 기자의 질문에 날카롭게 반박한 것은 상원의원을 더 나쁘게 보이게 만들었을 뿐이다.","sense":"반박하다","alts":["contradicting"]},{"wordId":15766,"answer":"is retorting","form":"현재진행","example":"The defendant is retorting to every accusation without pausing for breath right now.","exampleTranslation":"그 피고인은 지금 숨 돌릴 틈도 없이 모든 혐의에 날카롭게 반박하고 있다.","sense":"반박하다"},{"wordId":15767,"answer":"revels","form":"3인칭 단수형","example":"Every winter, the whole village revels in the warm glow of the holiday festival.","exampleTranslation":"매년 겨울 마을 전체가 그 명절 축제의 따뜻한 분위기를 만끽하며 흥청거린다.","sense":"흥청거리다","alts":["relishes"]},{"wordId":15767,"answer":"is reveling","form":"현재진행","example":"The whole team is reveling in their unexpected victory right now.","exampleTranslation":"그 팀 전체는 지금 예상치 못한 승리를 만끽하고 있다.","sense":"즐기다"},{"wordId":15768,"answer":"reverends","form":"복수형","example":"Several reverends gathered at the cathedral for the annual memorial service.","exampleTranslation":"여러 목사가 연례 추모 예배를 위해 대성당에 모였다.","sense":"성직자","alts":["pastors"]},{"wordId":15769,"answer":"reverted","form":"과거분사","example":"The software, reverted to its previous version, finally worked without crashing.","exampleTranslation":"이전 버전으로 되돌려진 그 소프트웨어는 마침내 충돌 없이 작동했다.","sense":"되돌아가다"},{"wordId":15769,"answer":"will revert","form":"미래","example":"If the update fails, the system will revert to the old settings automatically tomorrow.","exampleTranslation":"업데이트가 실패하면 시스템은 내일 자동으로 예전 설정으로 되돌아갈 것이다.","sense":"되돌아가다"},{"wordId":15770,"answer":"rhymes","form":"복수형","example":"The song contains several clever rhymes that young children love to repeat.","exampleTranslation":"그 노래에는 어린아이들이 따라 하기 좋아하는 재치 있는 운율이 여러 개 담겨 있다.","sense":"운율"},{"wordId":15771,"answer":"riddles","form":"복수형","example":"Nobody in the group could solve the two riddles the guide gave them.","exampleTranslation":"그 일행 중 누구도 안내인이 낸 수수께끼 두 개를 풀지 못했다.","sense":"수수께끼"},{"wordId":15772,"answer":"robins","form":"복수형","example":"Two robins landed on the fence and sang for several minutes.","exampleTranslation":"울새 두 마리가 울타리에 앉아 몇 분 동안 노래했다.","sense":"울새"},{"wordId":15773,"answer":"rogues","form":"복수형","example":"Local legends describe several rogues who once hid gold coins in these hills.","exampleTranslation":"이 지역 전설은 예전에 금화를 이 언덕에 숨겼다는 무법자 여럿을 이야기한다.","sense":"악당","alts":["outlaws","villains"]},{"wordId":15774,"answer":"rouge","form":"원형","example":"The makeup artist applied a little rouge before the actress walked onto the stage.","exampleTranslation":"그 메이크업 아티스트는 배우가 무대에 오르기 전에 루즈를 살짝 발라 주었다.","sense":"루즈"},{"wordId":15775,"answer":"rouses","form":"3인칭 단수형","example":"The smell of fresh coffee usually rouses my father before the alarm even rings.","exampleTranslation":"신선한 커피 냄새는 대개 알람이 울리기도 전에 아버지를 깨운다.","sense":"깨우다"},{"wordId":15775,"answer":"is rousing","form":"현재진행","example":"The coach is rousing the tired players with a passionate speech right now.","exampleTranslation":"코치는 지금 열정적인 연설로 지친 선수들의 사기를 불러일으키고 있다.","sense":"불러일으키다"},{"wordId":15776,"answer":"rubble","form":"원형","example":"Rescue workers searched through the rubble for survivors after the building collapsed suddenly.","exampleTranslation":"구조대원들은 건물이 갑자기 무너진 뒤 잔해 속에서 생존자를 찾았다.","sense":"잔해"},{"wordId":15777,"answer":"rugby","form":"원형","example":"He played rugby for his university team and later coached young players in his town.","exampleTranslation":"그는 대학 팀에서 럭비를 했고 나중에는 고향에서 어린 선수들을 지도했다.","sense":"럭비"},{"wordId":15778,"answer":"more rugged","form":"비교급","example":"The northern trail was even more rugged than the guidebook had described.","exampleTranslation":"북쪽 산길은 안내서에 나온 것보다 훨씬 더 거칠고 험했다.","sense":"험준한","alts":["coarser","rougher"]},{"wordId":15778,"answer":"ruggedly","form":"부사형","example":"The actor was known for his ruggedly handsome looks in every western film.","exampleTranslation":"그 배우는 모든 서부극에서 남성적이고 거칠지만 매력적인 외모로 알려져 있었다.","sense":"거친","alts":["coarsely","roughly"]},{"wordId":15779,"answer":"rustles","form":"3인칭 단수형","example":"Every autumn afternoon, the wind usually rustles the dry leaves along this path.","exampleTranslation":"매년 가을 오후, 바람은 이 길가의 마른 낙엽을 바스락거리게 만든다.","sense":"바스락대다"},{"wordId":15779,"answer":"is rustling","form":"현재진행","example":"Something in the bushes is rustling right now, and the dog will not stop barking.","exampleTranslation":"지금 덤불 속에서 뭔가가 바스락거리고 있어서 개가 짖음을 멈추지 않는다.","sense":"바스락대다"},{"wordId":15780,"answer":"sacraments","form":"복수형","example":"The priest explained the meaning of several important sacraments to new church members.","exampleTranslation":"그 신부는 새 신자들에게 여러 중요한 성사의 의미를 설명해 주었다.","sense":"성사"},{"wordId":15781,"answer":"Sagging","form":"-ing형","example":"Sagging noticeably in the middle, the old wooden bridge worried every driver who crossed it.","exampleTranslation":"가운데가 눈에 띄게 처진 그 낡은 나무다리는 건너는 모든 운전자를 불안하게 했다.","sense":"처지다"},{"wordId":15781,"answer":"will sag","form":"미래","example":"Without extra support, this shelf will sag under the weight of all those textbooks.","exampleTranslation":"추가 지지대가 없으면 이 선반은 그 많은 교과서의 무게에 눌려 처질 것이다.","sense":"처지다"},{"wordId":15782,"answer":"sagas","form":"복수형","example":"The library owns several long sagas describing three generations of one family.","exampleTranslation":"그 도서관은 한 가문의 삼대를 그린 긴 대서사시를 여러 권 소장하고 있다.","sense":"대서사시"},{"wordId":15783,"answer":"sages","form":"복수형","example":"Throughout history, many sages have offered wisdom about living a simple life.","exampleTranslation":"역사를 통틀어 많은 현자가 소박한 삶에 관한 지혜를 전해 왔다.","sense":"현자"},{"wordId":15784,"answer":"more salient","form":"비교급","example":"The professor's warning about deadlines became more salient after several students missed one.","exampleTranslation":"여러 학생이 마감을 놓친 뒤 교수님의 경고가 더욱 두드러지게 다가왔다.","sense":"두드러진","alts":["more prominent"]},{"wordId":15784,"answer":"salience","form":"명사형","example":"Researchers measured the salience of each warning label printed on the cigarette packaging.","exampleTranslation":"연구자들은 담배 포장에 인쇄된 각 경고 문구가 얼마나 눈에 띄는지 측정했다.","sense":"두드러진","alts":["prominence"]},{"wordId":15785,"answer":"saloons","form":"복수형","example":"The cowboys visited several saloons in town before riding out at dawn.","exampleTranslation":"카우보이들은 새벽에 말을 타고 떠나기 전 마을의 여러 술집을 들렀다.","sense":"주점","alts":["bars","pubs"]},{"wordId":15786,"answer":"Salvaging","form":"-ing형","example":"Salvaging old furniture from the curb has become a popular weekend hobby lately.","exampleTranslation":"길가에 버려진 낡은 가구를 건지는 것은 요즘 인기 있는 주말 취미가 되었다.","sense":"건지다"},{"wordId":15786,"answer":"was salvaged","form":"수동태","example":"Most of the cargo was salvaged from the sunken ship within a week.","exampleTranslation":"그 화물 대부분은 일주일 안에 침몰한 배에서 구조되었다.","sense":"구하다"},{"wordId":15787,"answer":"satin","form":"원형","example":"The designer used soft satin to make the elegant curtains for the ballroom.","exampleTranslation":"그 디자이너는 무도회장의 우아한 커튼을 만들기 위해 부드러운 새틴을 사용했다.","sense":"새틴"},{"wordId":15788,"answer":"satires","form":"복수형","example":"The magazine publishes sharp satires of modern office culture every single month.","exampleTranslation":"그 잡지는 매달 현대 직장 문화를 날카롭게 풍자하는 글을 여러 편 싣는다.","sense":"풍자"},{"wordId":15789,"answer":"savoured","form":"과거분사","example":"The rare dessert, slowly savoured by everyone at the table, disappeared within minutes.","exampleTranslation":"느긋하게 모두가 음미한 그 귀한 디저트는 몇 분 만에 사라졌다.","sense":"음미하다"},{"wordId":15789,"answer":"will savour","form":"미래","example":"Guests will savour every bite of the chef's new tasting menu next weekend.","exampleTranslation":"손님들은 다음 주말 셰프의 새 시식 메뉴 한 입 한 입을 음미할 것이다.","sense":"음미하다"},{"wordId":15790,"answer":"scalps","form":"복수형","example":"Dermatologists examined the scalps of several patients complaining about constant dryness.","exampleTranslation":"피부과 의사들은 계속되는 건조함을 호소하는 여러 환자의 두피를 살펴보았다.","sense":"두피"},{"wordId":15791,"answer":"scant","form":"원형","example":"There was scant evidence connecting the suspect to the crime scene that night.","exampleTranslation":"그날 밤 용의자를 범죄 현장과 연결할 증거는 부족했다.","sense":"부족한"},{"wordId":15791,"answer":"scant","form":"원형","example":"Farmers worried about scant rainfall threatening the region's wheat harvest this season.","exampleTranslation":"농부들은 이번 시즌 그 지역 밀 수확을 위협하는 부족한 강수량을 걱정했다.","sense":"부족한"},{"wordId":15792,"answer":"scarlet","form":"원형","example":"She wore a scarlet dress that stood out brightly against the gray crowd.","exampleTranslation":"그녀는 칙칙한 회색 인파 속에서 눈에 띄는 진홍색 드레스를 입고 있었다.","sense":"새빨간"},{"wordId":15792,"answer":"scarlet","form":"원형","example":"The artist mixed several shades of scarlet to capture the sunset's warm glow.","exampleTranslation":"그 화가는 노을의 따뜻한 빛을 담아내려고 여러 진홍색 색조를 섞었다.","sense":"새빨간"},{"wordId":15793,"answer":"most schizophrenic","form":"최상급","example":"Of all the companies she reviewed, this one had the most schizophrenic pricing strategy.","exampleTranslation":"그녀가 검토한 회사들 중 이 회사의 가격 정책이 가장 오락가락했다.","sense":"양면적인"},{"wordId":15793,"answer":"schizophrenia","form":"명사형","example":"The documentary followed a young man living with schizophrenia and his path to recovery.","exampleTranslation":"그 다큐멘터리는 조현병을 안고 살아가는 한 청년과 그의 회복 과정을 담았다.","sense":"조현병의"},{"wordId":15794,"answer":"scissors","form":"원형","example":"Could you hand me the scissors so I can wrap this birthday present quickly?","exampleTranslation":"이 생일 선물을 빨리 포장하게 가위 좀 건네줄래?","sense":"가위"},{"wordId":15795,"answer":"scornful","form":"형용사형","example":"She gave him a scornful look before turning away without saying a word.","exampleTranslation":"그녀는 아무 말 없이 돌아서기 전 그에게 경멸 어린 눈길을 보냈다.","sense":"경멸"},{"wordId":15796,"answer":"scowled","form":"과거형","example":"My brother scowled at the referee after the unfair call yesterday afternoon.","exampleTranslation":"내 남동생은 어제 오후 불공정한 판정 뒤 심판을 향해 인상을 찡그렸다.","sense":"찡그리다"},{"wordId":15796,"answer":"has scowled","form":"현재완료","example":"The manager has scowled at every late arrival since the new policy started.","exampleTranslation":"그 매니저는 새 정책이 시작된 이후 지각하는 사람마다 인상을 찡그려 왔다.","sense":"찡그리다"},{"wordId":15797,"answer":"Screeching","form":"-ing형","example":"Screeching to a sudden stop, the taxi barely missed the pedestrian at the crosswalk.","exampleTranslation":"택시는 끼익 소리를 내며 갑자기 멈춰서 횡단보도의 보행자를 가까스로 피했다.","sense":"끼익거리다"},{"wordId":15797,"answer":"will screech","form":"미래","example":"If you brake too hard, the tires will screech loudly on this wet road.","exampleTranslation":"너무 세게 브레이크를 밟으면 이 젖은 도로에서 타이어가 시끄럽게 끼익거릴 것이다.","sense":"끼익거리다"},{"wordId":15798,"answer":"Scribbling","form":"-ing형","example":"Scribbling notes in the margins helped her remember every important detail later.","exampleTranslation":"여백에 메모를 휘갈겨 쓴 것은 나중에 중요한 세부 사항을 모두 기억하는 데 도움이 되었다.","sense":"휘갈겨쓰다"},{"wordId":15798,"answer":"was scribbled","form":"수동태","example":"The phone number was scribbled on a napkin and quickly lost in his pocket.","exampleTranslation":"그 전화번호는 냅킨에 휘갈겨 쓰여서 그의 주머니 속에서 금세 사라졌다.","sense":"휘갈겨쓰다"},{"wordId":15799,"answer":"scrolls","form":"3인칭 단수형","example":"My grandmother rarely scrolls through social media before her morning coffee.","exampleTranslation":"우리 할머니는 아침 커피를 마시기 전에는 좀처럼 소셜미디어를 스크롤하지 않으신다.","sense":"스크롤하다"},{"wordId":15799,"answer":"is scrolling","form":"현재진행","example":"He is scrolling through old photos on his phone right now instead of sleeping.","exampleTranslation":"그는 잠을 자는 대신 지금 휴대폰에서 오래된 사진들을 스크롤하고 있다.","sense":"스크롤하다"},{"wordId":15800,"answer":"secretive","form":"형용사형","example":"The manager stayed unusually secretive about the details of the upcoming merger.","exampleTranslation":"그 관리자는 다가오는 합병 세부사항에 대해 유난히 말을 아꼈다.","sense":"비밀"},{"wordId":15801,"answer":"secreted","form":"과거분사","example":"Hormones, secreted directly into the bloodstream, help control mood and energy levels.","exampleTranslation":"혈류로 직접 분비되는 호르몬은 기분과 에너지 수준을 조절하는 데 도움을 준다.","sense":"분비하다"},{"wordId":15801,"answer":"will secrete","form":"미래","example":"During stress, your body will secrete extra adrenaline within just a few seconds.","exampleTranslation":"스트레스를 받으면 신체는 단 몇 초 안에 추가 아드레날린을 분비할 것이다.","sense":"분비하다"},{"wordId":15802,"answer":"Seeping","form":"-ing형","example":"Seeping quietly through the cracked wall, the rainwater ruined the living room carpet.","exampleTranslation":"갈라진 벽 틈으로 조용히 스며든 빗물이 거실 카펫을 망가뜨렸다.","sense":"스며들다"},{"wordId":15802,"answer":"is seeping","form":"현재진행","example":"Water is seeping into the basement right now because of last night's heavy storm.","exampleTranslation":"지난밤 폭우 때문에 지금 지하실로 물이 스며들고 있다.","sense":"스며들다"},{"wordId":15803,"answer":"seizures","form":"복수형","example":"The paramedics monitored the patient closely after two seizures within an hour.","exampleTranslation":"구급대원들은 한 시간 안에 두 차례 발작이 있은 뒤 환자를 세심히 살폈다.","sense":"발작"},{"wordId":15804,"answer":"sensory","form":"원형","example":"Some children with sensory issues find loud noises especially overwhelming at school.","exampleTranslation":"감각 문제가 있는 일부 아이들은 학교에서 시끄러운 소리를 특히 견디기 힘들어한다.","sense":"감각의"},{"wordId":15804,"answer":"sensory","form":"원형","example":"The design team studied sensory branding to make the store feel more welcoming to customers.","exampleTranslation":"디자인 팀은 매장을 고객에게 더 친근하게 느껴지도록 감각 마케팅을 연구했다.","sense":"감각의"},{"wordId":15805,"answer":"most sensual","form":"최상급","example":"Of all the paintings in the gallery, critics called this one the most sensual.","exampleTranslation":"그 화랑의 모든 그림 중에서 평론가들은 이 작품을 가장 관능적이라고 평했다.","sense":"관능적"},{"wordId":15805,"answer":"sensuality","form":"명사형","example":"The film's soundtrack captures a quiet sensuality that lingers long after the credits roll.","exampleTranslation":"그 영화의 사운드트랙은 엔딩 크레디트가 끝난 뒤에도 오래 남는 은은한 관능미를 담고 있다.","sense":"관능적인"},{"wordId":15806,"answer":"more serene","form":"비교급","example":"The lake at dawn looked even more serene than it had the evening before.","exampleTranslation":"새벽녘 호수는 전날 저녁보다 훨씬 더 고요해 보였다.","sense":"고요한"},{"wordId":15806,"answer":"serenely","form":"부사형","example":"She sat serenely by the window, watching the rain fall on the quiet street.","exampleTranslation":"그녀는 창가에 차분히 앉아 조용한 거리에 내리는 비를 바라보았다.","sense":"고요한"},{"wordId":15807,"answer":"sewers","form":"복수형","example":"City crews repaired several old sewers that had been causing flooding downtown.","exampleTranslation":"시 작업반은 시내 침수를 일으키던 낡은 하수도 여러 곳을 수리했다.","sense":"하수도"},{"wordId":15808,"answer":"sheared","form":"과거형","example":"The farmer sheared all his sheep early last spring before the heat arrived.","exampleTranslation":"그 농부는 더위가 오기 전 지난 봄 일찍 자신의 양들을 모두 깎았다.","sense":"깎다"},{"wordId":15808,"answer":"has sheared","form":"현재완료","example":"This experienced worker has sheared over a hundred sheep since sunrise this morning.","exampleTranslation":"이 숙련된 일꾼은 오늘 아침 해가 뜬 뒤로 백 마리가 넘는 양을 깎았다.","sense":"깎다"},{"wordId":15809,"answer":"sherries","form":"복수형","example":"The restaurant offers three different sherries imported directly from southern Spain.","exampleTranslation":"그 식당은 스페인 남부에서 직접 수입한 셰리 와인 세 종류를 선보인다.","sense":"셰리"},{"wordId":15810,"answer":"Shimmering","form":"-ing형","example":"Shimmering under the streetlights, the wet pavement looked almost magical after the rain.","exampleTranslation":"비가 온 뒤 가로등 아래서 아른거리는 젖은 도로는 거의 마법 같아 보였다.","sense":"아른거리다"},{"wordId":15810,"answer":"is shimmering","form":"현재진행","example":"The lake is shimmering brightly in the afternoon sunlight right now.","exampleTranslation":"그 호수는 지금 오후 햇살 속에서 밝게 아른거리고 있다.","sense":"아른거리다"},{"wordId":15811,"answer":"shortcomings","form":"복수형","example":"Every plan has a few shortcomings, so we need a solid backup strategy.","exampleTranslation":"모든 계획에는 몇 가지 결점이 있으므로 우리는 탄탄한 대안을 마련해야 한다.","sense":"결점","alts":["drawbacks"]},{"wordId":15812,"answer":"shovels","form":"복수형","example":"The workers grabbed several shovels and started clearing snow from the lot.","exampleTranslation":"일꾼들은 삽 여러 개를 집어 들고 주차장의 눈을 치우기 시작했다.","sense":"삽"},{"wordId":15813,"answer":"shrewdest","form":"최상급","example":"Everyone agreed she was the shrewdest negotiator the company had ever hired.","exampleTranslation":"모두가 그녀를 그 회사가 고용한 사람 중 가장 빈틈없는 협상가라고 인정했다.","sense":"빈틈없는"},{"wordId":15813,"answer":"shrewdness","form":"명사형","example":"His shrewdness in reading the market helped the firm avoid a costly investment mistake.","exampleTranslation":"그가 시장을 정확히 읽어 내는 눈썰미 덕분에 회사는 값비싼 투자 실수를 피할 수 있었다.","sense":"빈틈없는"},{"wordId":15814,"answer":"Shrieking","form":"-ing형","example":"Shrieking with delight, the children raced toward the ice cream truck outside.","exampleTranslation":"아이들은 기뻐서 비명을 지르며 밖에 있는 아이스크림 트럭을 향해 달려갔다.","sense":"비명을 지르다","alts":["screaming"]},{"wordId":15814,"answer":"is shrieking","form":"현재진행","example":"The toddler is shrieking loudly because he dropped his favorite toy just now.","exampleTranslation":"그 아기는 좋아하는 장난감을 방금 떨어뜨려서 크게 비명을 지르고 있다.","sense":"비명지르다"},{"wordId":15815,"answer":"shrouds","form":"복수형","example":"Archaeologists found several preserved burial shrouds inside the ancient Egyptian tomb.","exampleTranslation":"고고학자들은 고대 이집트 무덤 안에서 잘 보존된 수의 여러 점을 발견했다.","sense":"수의"},{"wordId":15816,"answer":"shutters","form":"복수형","example":"The old house had wooden shutters on every window facing the busy street.","exampleTranslation":"그 오래된 집은 번잡한 거리 쪽 창문마다 나무 덧문이 달려 있었다.","sense":"덧문"},{"wordId":15818,"answer":"sidelines","form":"복수형","example":"Injured players had to watch the entire game from the sidelines that day.","exampleTranslation":"부상당한 선수들은 그날 경기 전체를 사이드라인에서 지켜봐야 했다.","sense":"사이드라인"},{"wordId":15819,"answer":"sifts","form":"3인칭 단수형","example":"My grandmother always sifts the flour twice before baking her famous bread.","exampleTranslation":"우리 할머니는 유명한 빵을 굽기 전 항상 밀가루를 두 번 체로 친다.","sense":"체로치다"},{"wordId":15819,"answer":"is sifting","form":"현재진행","example":"The detective is sifting through old case files right now for new clues.","exampleTranslation":"그 형사는 새로운 단서를 찾기 위해 지금 오래된 사건 파일을 면밀히 검토하고 있다.","sense":"검토하다"},{"wordId":15820,"answer":"silhouettes","form":"복수형","example":"We could see the silhouettes of several mountains against the setting sun.","exampleTranslation":"우리는 지는 해를 배경으로 여러 산의 실루엣을 볼 수 있었다.","sense":"실루엣"},{"wordId":15821,"answer":"most sinister","form":"최상급","example":"Among all the villains in the series, fans agreed this one was the most sinister.","exampleTranslation":"그 시리즈의 모든 악당 중에서 팬들은 이 캐릭터가 가장 사악하다고 입을 모았다.","sense":"불길한"},{"wordId":15821,"answer":"sinister","form":"원형","example":"A sinister silence fell over the house just before the storm hit.","exampleTranslation":"폭풍이 몰아치기 직전 그 집에는 불길한 정적이 감돌았다.","sense":"불길한"},{"wordId":15822,"answer":"sirens","form":"복수형","example":"Everyone pulled over when they heard the sirens of two approaching fire trucks.","exampleTranslation":"사람들은 다가오는 소방차 두 대의 사이렌 소리를 듣고 모두 차를 세웠다.","sense":"사이렌"},{"wordId":15823,"answer":"skims","form":"3인칭 단수형","example":"My father usually skims the newspaper headlines before leaving for work.","exampleTranslation":"우리 아버지는 출근하기 전에 대개 신문 헤드라인을 훑어본다.","sense":"대충 읽다","alts":["browses"]},{"wordId":15823,"answer":"is skimming","form":"현재진행","example":"She is skimming the report quickly because the meeting starts in five minutes.","exampleTranslation":"회의가 오 분 뒤에 시작되어서 그녀는 지금 보고서를 빠르게 훑어보고 있다.","sense":"대충 읽다","alts":["is browsing","is scanning"]},{"wordId":15824,"answer":"skinnier","form":"비교급","example":"The puppy looked skinnier than the other dogs at the shelter that week.","exampleTranslation":"그 강아지는 그 주 보호소의 다른 개들보다 더 말라 보였다.","sense":"마른"},{"wordId":15824,"answer":"skinniness","form":"명사형","example":"The vet was concerned about the kitten's skinniness after it stopped eating for days.","exampleTranslation":"그 수의사는 새끼 고양이가 며칠째 먹지 않아 살이 많이 빠진 것을 걱정했다.","sense":"몹시 마른"},{"wordId":15825,"answer":"slain","form":"과거분사","example":"Soldiers stood in silent tribute beside the slain heroes of the old battle.","exampleTranslation":"병사들은 그 오래된 전투에서 전사한 영웅들 곁에서 말없이 경의를 표하며 서 있었다.","sense":"죽이다"},{"wordId":15825,"answer":"will slay","form":"미래","example":"In the story, the young knight will slay the dragon before the sun sets tonight.","exampleTranslation":"이야기 속에서 그 젊은 기사는 오늘 밤 해가 지기 전에 용을 죽일 것이다.","sense":"죽이다"},{"wordId":15826,"answer":"sleeker","form":"비교급","example":"The updated phone case looked sleeker than the bulky model from last year.","exampleTranslation":"업데이트된 휴대폰 케이스는 작년의 투박한 모델보다 더 매끄러워 보였다.","sense":"세련된","alts":["slicker","smoother"]},{"wordId":15826,"answer":"sleekly","form":"부사형","example":"The new train was sleekly designed to reduce wind resistance at high speed.","exampleTranslation":"그 새 열차는 고속 주행 시 공기 저항을 줄이도록 유선형으로 설계되었다.","sense":"세련된","alts":["smoothly"]},{"wordId":15827,"answer":"slings","form":"복수형","example":"The clinic keeps several slings on hand for patients with shoulder injuries.","exampleTranslation":"그 병원은 어깨 부상 환자를 위해 팔걸이 붕대를 여러 개 구비해 둔다.","sense":"팔걸이 붕대","alts":["bandages"]},{"wordId":15828,"answer":"slippers","form":"복수형","example":"She put on both slippers before walking across the cold kitchen floor.","exampleTranslation":"그녀는 차가운 부엌 바닥을 걷기 전에 양쪽 슬리퍼를 모두 신었다.","sense":"슬리퍼"},{"wordId":15829,"answer":"slipperiest","form":"최상급","example":"Of all the trails on the mountain, this one was the slipperiest after the rain.","exampleTranslation":"그 산의 모든 등산로 중에서 이 길이 비가 온 뒤 가장 미끄러웠다.","sense":"미끄러운"},{"wordId":15829,"answer":"slipperiness","form":"명사형","example":"Workers spread salt on the sidewalk to reduce the slipperiness caused by the ice.","exampleTranslation":"일꾼들은 얼음 때문에 생긴 미끄러짐을 줄이려고 보도에 소금을 뿌렸다.","sense":"미끄러운"},{"wordId":15830,"answer":"slits","form":"복수형","example":"Light came through several narrow slits in the old wooden shutters.","exampleTranslation":"낡은 나무 덧문에 난 여러 좁은 틈으로 빛이 들어왔다.","sense":"가느다란 틈","alts":["gaps"]},{"wordId":15831,"answer":"slops","form":"3인칭 단수형","example":"He always slops a little coffee onto the counter when he is in a hurry.","exampleTranslation":"그는 서두를 때마다 늘 커피를 조금 조리대 위에 엎지른다.","sense":"엎지르다"},{"wordId":15831,"answer":"is slopping","form":"현재진행","example":"The toddler is slopping juice all over the kitchen floor right now.","exampleTranslation":"그 아기는 지금 부엌 바닥 여기저기에 주스를 엎지르고 있다.","sense":"엎지르다"},{"wordId":15832,"answer":"slugs","form":"복수형","example":"Gardeners often use crushed eggshells to keep hungry slugs away from young seedlings.","exampleTranslation":"정원사들은 어린 모종에서 배고픈 민달팽이를 쫓아내기 위해 흔히 부순 달걀 껍데기를 사용한다.","sense":"민달팽이"},{"wordId":15833,"answer":"slums","form":"복수형","example":"The documentary showed daily life inside several crowded urban slums last year.","exampleTranslation":"그 다큐멘터리는 작년 여러 혼잡한 도시 빈민가의 일상을 보여 주었다.","sense":"빈민가"},{"wordId":15834,"answer":"slyer","form":"비교급","example":"Of the two salesmen, he was slyer about hiding the product's flaws.","exampleTranslation":"두 영업사원 중 그가 제품의 결함을 숨기는 데 더 교활했다.","sense":"교활한"},{"wordId":15834,"answer":"slyly","form":"부사형","example":"The cat slyly slipped past the guard dog while everyone else was distracted.","exampleTranslation":"다른 사람들이 다 정신이 팔린 사이 그 고양이는 능청스럽게 경비견을 지나쳤다.","sense":"교활한"},{"wordId":15835,"answer":"snags","form":"복수형","example":"The project hit several unexpected snags after the main supplier canceled the order.","exampleTranslation":"주요 공급업체가 주문을 취소한 뒤 그 프로젝트는 예상치 못한 장애물을 여러 번 만났다.","sense":"걸림돌","alts":["hurdles","obstacles"]},{"wordId":15836,"answer":"snarled","form":"과거형","example":"The dog snarled at the mail carrier through the fence yesterday morning.","exampleTranslation":"그 개는 어제 아침 울타리 너머로 우편배달부를 향해 으르렁거렸다.","sense":"으르렁대다"},{"wordId":15836,"answer":"has snarled","form":"현재완료","example":"This traffic jam has snarled the whole highway since early this morning.","exampleTranslation":"이 교통 정체는 오늘 이른 아침부터 고속도로 전체를 뒤엉키게 했다.","sense":"뒤엉키다"},{"wordId":15837,"answer":"Sniping","form":"-ing형","example":"Sniping at coworkers behind their backs will only damage your professional reputation.","exampleTranslation":"동료들을 뒤에서 비열하게 비난하는 것은 당신의 직업적 평판만 해칠 뿐이다.","sense":"헐뜯다","alts":["Accusing"]},{"wordId":15837,"answer":"will snipe","form":"미래","example":"The rival candidates will snipe at each other during tonight's televised debate.","exampleTranslation":"그 경쟁 후보들은 오늘 밤 텔레비전 토론에서 서로를 비열하게 비난할 것이다.","sense":"비난하다"},{"wordId":15838,"answer":"Snorting","form":"-ing형","example":"Snorting with laughter, my sister could barely finish telling the joke.","exampleTranslation":"내 여동생은 웃음을 참지 못해 콧방귀를 뀌며 농담을 겨우 끝맺었다.","sense":"콧방귀뀌다"},{"wordId":15838,"answer":"is snorting","form":"현재진행","example":"The horse is snorting nervously because the thunder just started outside.","exampleTranslation":"천둥이 방금 밖에서 치기 시작해서 그 말은 초조하게 콧김을 내뿜고 있다.","sense":"콧김뿜다"},{"wordId":15839,"answer":"sodas","form":"복수형","example":"He ordered two large sodas to share with his friends at the movies.","exampleTranslation":"그는 영화관에서 친구들과 나눠 마시려고 큰 탄산음료 두 잔을 주문했다.","sense":"탄산음료"},{"wordId":15840,"answer":"solicited","form":"과거형","example":"The nonprofit solicited donations from local businesses just last week.","exampleTranslation":"그 비영리단체는 바로 지난주에 지역 사업체들로부터 기부를 요청했다.","sense":"요청하다","alts":["requested"]},{"wordId":15840,"answer":"has solicited","form":"현재완료","example":"The charity has solicited feedback from members ever since the survey launched.","exampleTranslation":"그 자선단체는 설문조사가 시작된 이후로 줄곧 회원들의 의견을 요청해 왔다.","sense":"요청하다"},{"wordId":15841,"answer":"solvents","form":"복수형","example":"Workers must handle several industrial solvents carefully to avoid skin irritation.","exampleTranslation":"작업자들은 피부 자극을 피하려고 여러 산업용 용제를 조심스럽게 다뤄야 한다.","sense":"용제"},{"wordId":15842,"answer":"sophisticated","form":"형용사형","example":"Critics praised the sophisticated writing style used throughout her debut novel.","exampleTranslation":"비평가들은 그녀의 데뷔 소설 전반에 쓰인 고급스러운 문체를 높이 평가했다.","sense":"세련됨"},{"wordId":15843,"answer":"sparsest","form":"최상급","example":"Of all the regions surveyed, the desert had the sparsest population by far.","exampleTranslation":"조사한 모든 지역 중에서 사막이 단연 가장 인구가 드물었다.","sense":"드문드문"},{"wordId":15843,"answer":"sparsity","form":"명사형","example":"Researchers noted the sparsity of trees in areas affected by the recent drought.","exampleTranslation":"연구자들은 최근 가뭄의 영향을 받은 지역에서 나무가 얼마나 듬성듬성한지 언급했다.","sense":"드문드문한"},{"wordId":15844,"answer":"spectres","form":"복수형","example":"Local legends describe several spectres said to haunt the old abandoned mansion.","exampleTranslation":"이 지역 전설은 낡고 버려진 저택에 나타난다는 유령 여럿을 이야기한다.","sense":"망령","alts":["ghosts"]},{"wordId":15845,"answer":"splinters","form":"복수형","example":"She got several splinters in her fingers while repairing the old wooden fence.","exampleTranslation":"그녀는 낡은 나무 울타리를 고치다가 손가락에 나뭇가시가 여러 개 박혔다.","sense":"나뭇가시","alts":["thorns"]},{"wordId":15846,"answer":"sponges","form":"복수형","example":"Use two damp sponges to wipe down the kitchen counters after cooking.","exampleTranslation":"요리 후에는 젖은 스펀지 두 개로 부엌 조리대를 닦아 내라.","sense":"스펀지"},{"wordId":15847,"answer":"spreadsheets","form":"복수형","example":"She created several spreadsheets to track the team's monthly expenses and budgets.","exampleTranslation":"그녀는 팀의 월별 지출과 예산을 관리하려고 스프레드시트를 여러 개 만들었다.","sense":"스프레드시트"},{"wordId":15848,"answer":"squadrons","form":"복수형","example":"Multiple squadrons of fighter jets flew overhead during the national ceremony.","exampleTranslation":"국가 기념식 동안 여러 편대의 전투기가 하늘 위로 지나갔다.","sense":"편대"},{"wordId":15849,"answer":"squeaking","form":"-ing형","example":"Squeaking loudly with every step, the old wooden floor gave away her late-night snack run.","exampleTranslation":"걸음마다 크게 삐걱거리는 낡은 나무 바닥 때문에 그녀의 한밤 야식 습격이 들통났다.","sense":"삐걱거리다","alts":["creaking"]},{"wordId":15849,"answer":"will squeak","form":"미래","example":"That brand-new pair of shoes will squeak loudly on the gym floor at first.","exampleTranslation":"그 새 신발은 처음에는 체육관 바닥에서 시끄럽게 삐걱거릴 것이다.","sense":"삐걱거리다","alts":["will creak"]},{"wordId":15850,"answer":"Squinting","form":"-ing형","example":"Squinting against the bright sun, she tried to read the tiny street sign.","exampleTranslation":"그녀는 밝은 햇빛 때문에 눈을 가늘게 뜨며 작은 거리 표지판을 읽으려 했다.","sense":"실눈뜨다"},{"wordId":15850,"answer":"is squinting","form":"현재진행","example":"He is squinting at his phone screen because the font size is too small.","exampleTranslation":"그는 글씨 크기가 너무 작아서 지금 휴대폰 화면을 실눈을 뜨고 보고 있다.","sense":"실눈뜨다"},{"wordId":15851,"answer":"squirrels","form":"복수형","example":"Several squirrels were busy burying acorns in the park before winter arrived.","exampleTranslation":"겨울이 오기 전 다람쥐 여러 마리가 공원에서 부지런히 도토리를 묻었다.","sense":"다람쥐"},{"wordId":15852,"answer":"staples","form":"복수형","example":"Rice and beans are staples in most households across this entire region.","exampleTranslation":"쌀과 콩은 이 지역 대부분 가정에서 주요 식품이다.","sense":"주요식품"},{"wordId":15853,"answer":"stature","form":"원형","example":"Her stature within the company grew steadily after she led the successful project.","exampleTranslation":"그 성공적인 프로젝트를 이끈 뒤 그녀의 회사 내 위상은 꾸준히 높아졌다.","sense":"위상"},{"wordId":15854,"answer":"steroids","form":"복수형","example":"Several athletes were disqualified after testing positive for banned steroids.","exampleTranslation":"여러 선수가 금지된 스테로이드 양성 반응을 보여 실격 처리되었다.","sense":"스테로이드"},{"wordId":15855,"answer":"stews","form":"복수형","example":"My grandmother used to make hearty stews with potatoes, carrots, and beef.","exampleTranslation":"할머니는 감자와 당근, 소고기를 넣은 든든한 스튜를 자주 만들어 주셨다.","sense":"스튜"},{"wordId":15856,"answer":"stifled","form":"과거형","example":"She stifled a yawn during the long meeting just this morning.","exampleTranslation":"그녀는 바로 오늘 아침 긴 회의 도중 하품을 억눌렀다.","sense":"억누르다"},{"wordId":15856,"answer":"has stifled","form":"현재완료","example":"Heavy regulation has stifled small business growth in this town for years.","exampleTranslation":"과도한 규제는 여러 해 동안 이 마을의 소규모 사업 성장을 억눌러 왔다.","sense":"억제하다","alts":["has repressed","has restrained","has suppressed"]},{"wordId":15857,"answer":"stipulated","form":"과거분사","example":"The stipulated deadline for the project cannot be extended under any circumstance.","exampleTranslation":"그 프로젝트에 명시된 마감일은 어떤 경우에도 연장될 수 없다.","sense":"명시하다"},{"wordId":15857,"answer":"will stipulate","form":"미래","example":"The new contract will stipulate that all repairs must be completed within a month.","exampleTranslation":"그 새 계약서는 모든 수리가 한 달 안에 완료되어야 한다고 명시할 것이다.","sense":"명시하다"},{"wordId":15858,"answer":"Stooping","form":"-ing형","example":"Stooping under the low doorway, he entered the ancient stone cottage carefully.","exampleTranslation":"그는 낮은 출입구 아래로 몸을 굽히며 그 오래된 돌집에 조심스럽게 들어갔다.","sense":"몸굽히다"},{"wordId":15858,"answer":"is stooping","form":"현재진행","example":"Grandpa is stooping over the garden bed, pulling weeds before lunch.","exampleTranslation":"할아버지는 점심 전에 잡초를 뽑으려고 화단 위로 몸을 굽히고 계신다.","sense":"몸굽히다"},{"wordId":15859,"answer":"stoutest","form":"최상급","example":"Of all the oak trees in the yard, this one had the stoutest trunk.","exampleTranslation":"마당의 모든 참나무 중에서 이 나무의 줄기가 가장 굵고 튼튼했다.","sense":"굵은","alts":["plumpest"]},{"wordId":15859,"answer":"stoutly","form":"부사형","example":"The old fortress walls were built stoutly enough to withstand centuries of storms.","exampleTranslation":"그 오래된 요새의 성벽은 수백 년의 폭풍을 견딜 만큼 튼튼하게 지어졌다.","sense":"통통한"},{"wordId":15860,"answer":"straits","form":"복수형","example":"Ships have used these narrow straits for centuries to shorten their journey.","exampleTranslation":"배들은 여정을 단축하려고 수 세기 동안 이 좁은 해협을 이용해 왔다.","sense":"해협"},{"wordId":15862,"answer":"Strangling","form":"-ing형","example":"Strangling small businesses with excessive paperwork discourages new entrepreneurs from starting up.","exampleTranslation":"지나친 서류 작업으로 소규모 사업체를 억압하는 것은 새로운 창업가들의 의욕을 꺾는다.","sense":"억압하다"},{"wordId":15862,"answer":"was strangled","form":"수동태","example":"Local innovation was strangled by years of overly strict regulation in that industry.","exampleTranslation":"그 업계에서 지역 혁신은 수년간의 지나치게 엄격한 규제로 억압되었다.","sense":"억압하다"},{"wordId":15863,"answer":"streamlines","form":"3인칭 단수형","example":"This new software usually streamlines the entire hiring process for small companies.","exampleTranslation":"이 새 소프트웨어는 대개 소규모 회사들의 전체 채용 과정을 간소화한다.","sense":"간소화하다"},{"wordId":15863,"answer":"is streamlining","form":"현재진행","example":"The team is streamlining the checkout process on the website right now.","exampleTranslation":"그 팀은 지금 웹사이트의 결제 과정을 간소화하고 있다.","sense":"간소화하다"},{"wordId":15864,"answer":"more stringent","form":"비교급","example":"The new food safety law introduced even more stringent rules for restaurant kitchens.","exampleTranslation":"새 식품 안전법은 식당 주방에 훨씬 더 엄격한 규정을 도입했다.","sense":"까다로운","alts":["more austere","more rigid"]},{"wordId":15864,"answer":"stringently","form":"부사형","example":"Inspectors enforced the new safety codes stringently after last year's factory accident.","exampleTranslation":"작년 공장 사고 이후 감독관들은 새 안전 수칙을 매우 철저하게 집행했다.","sense":"엄격한"},{"wordId":15865,"answer":"sturdiest","form":"최상급","example":"Of all the tables in the showroom, this one felt the sturdiest by far.","exampleTranslation":"전시장의 모든 탁자 중에서 이것이 단연 가장 튼튼하게 느껴졌다.","sense":"튼튼한"},{"wordId":15865,"answer":"sturdiness","form":"명사형","example":"Reviewers praised the backpack's sturdiness after months of daily hiking use.","exampleTranslation":"후기 작성자들은 몇 달간 매일 등산에 쓴 뒤에도 그 배낭이 얼마나 견고한지 칭찬했다.","sense":"튼튼한"},{"wordId":15866,"answer":"Subdividing","form":"-ing형","example":"Subdividing the large plot into smaller lots increased the total sale value significantly.","exampleTranslation":"넓은 부지를 더 작은 구획으로 세분화한 것은 총 판매 가치를 크게 높였다.","sense":"세분화하다"},{"wordId":15866,"answer":"was subdivided","form":"수동태","example":"The old farmland was subdivided into twenty separate housing plots last decade.","exampleTranslation":"그 오래된 농지는 지난 십 년 사이 스무 개의 별도 주택 부지로 세분화되었다.","sense":"세분화하다"},{"wordId":15867,"answer":"subdues","form":"3인칭 단수형","example":"A calm, low voice usually subdues an anxious dog faster than shouting does.","exampleTranslation":"차분하고 낮은 목소리는 대개 소리치는 것보다 더 빠르게 불안한 개를 진정시킨다.","sense":"진정시키다"},{"wordId":15867,"answer":"is subduing","form":"현재진행","example":"The trainer is subduing the frightened horse with slow, gentle movements.","exampleTranslation":"그 조련사는 느리고 부드러운 동작으로 겁먹은 말을 진정시키고 있다.","sense":"진정시키다"},{"wordId":15868,"answer":"submerged","form":"과거형","example":"The old car submerged completely in the flooded river just last week.","exampleTranslation":"그 낡은 차는 바로 지난주 불어난 강물 속에 완전히 잠겼다.","sense":"잠기다"},{"wordId":15868,"answer":"has submerged","form":"현재완료","example":"The rising tide has submerged the small dock since early this morning.","exampleTranslation":"밀려오는 조수는 오늘 이른 아침부터 그 작은 부두를 물에 잠기게 했다.","sense":"잠기다"},{"wordId":15869,"answer":"subsided","form":"과거분사","example":"The floodwaters, finally subsided after a long week, left mud all over the streets.","exampleTranslation":"마침내 일주일 만에 가라앉은 홍수물은 거리 곳곳에 진흙을 남겼다.","sense":"가라앉다"},{"wordId":15869,"answer":"will subside","form":"미래","example":"The doctor promised that the swelling will subside within just a few days.","exampleTranslation":"의사는 부기가 며칠 안에 가라앉을 것이라고 약속했다.","sense":"가라앉다"},{"wordId":15870,"answer":"Subsisting","form":"-ing형","example":"Subsisting on rice and beans alone, the family survived the harsh drought season.","exampleTranslation":"쌀과 콩만으로 겨우 살아가며 그 가족은 혹독한 가뭄철을 견뎌냈다.","sense":"겨우살다"},{"wordId":15870,"answer":"is subsisting","form":"현재진행","example":"The isolated village is subsisting mainly on fish right now during the winter shortage.","exampleTranslation":"그 고립된 마을은 지금 겨울철 식량 부족 동안 주로 물고기로 겨우 살아가고 있다.","sense":"겨우살다"},{"wordId":15871,"answer":"subverts","form":"3인칭 단수형","example":"This new law subverts the very rights it was designed to protect.","exampleTranslation":"이 새 법은 원래 보호하려던 바로 그 권리를 약화시킨다.","sense":"약화시키다"},{"wordId":15871,"answer":"is subverting","form":"현재진행","example":"Critics argue the policy is subverting democratic process right now, behind closed doors.","exampleTranslation":"비평가들은 그 정책이 지금 밀실에서 민주적 절차를 약화시키고 있다고 주장한다.","sense":"약화시키다"},{"wordId":15872,"answer":"succumbed","form":"과거형","example":"The old oak tree finally succumbed to the storm just last night.","exampleTranslation":"그 오래된 참나무는 바로 어젯밤 폭풍에 결국 쓰러졌다.","sense":"쓰러지다"},{"wordId":15872,"answer":"has succumbed","form":"현재완료","example":"Sadly, the patient has succumbed to the illness after fighting it for months.","exampleTranslation":"안타깝게도 그 환자는 여러 달 병과 싸운 끝에 결국 굴복하고 말았다.","sense":"굴복하다"},{"wordId":15873,"answer":"suffices","form":"3인칭 단수형","example":"A brief apology usually suffices when the mistake is small and honest.","exampleTranslation":"실수가 작고 정직하면 대개 짧은 사과만으로도 충분하다.","sense":"충분하다"},{"wordId":15873,"answer":"will suffice","form":"미래","example":"For today's demonstration, one small sample will suffice for the whole class.","exampleTranslation":"오늘 시연에는 작은 샘플 하나면 반 전체에 충분할 것이다.","sense":"충분하다"},{"wordId":15874,"answer":"Surpassing","form":"-ing형","example":"Surpassing everyone's expectations, the rookie player scored thirty points in his debut.","exampleTranslation":"모두의 예상을 뛰어넘어 그 신인 선수는 데뷔전에서 삼십 점을 기록했다.","sense":"뛰어넘다"},{"wordId":15874,"answer":"was surpassed","form":"수동태","example":"The old world record was surpassed by a young swimmer at last week's championship.","exampleTranslation":"그 오래된 세계 기록은 지난주 챔피언십에서 한 젊은 수영 선수에 의해 경신되었다.","sense":"뛰어넘다"},{"wordId":15875,"answer":"most surreal","form":"최상급","example":"Of all the dreams she remembered, last night's was by far the most surreal.","exampleTranslation":"그녀가 기억하는 모든 꿈 중에서 어젯밤 꿈이 단연 가장 비현실적이었다.","sense":"비현실적"},{"wordId":15875,"answer":"surrealism","form":"명사형","example":"The exhibit traced the history of surrealism from its origins in early European art.","exampleTranslation":"그 전시는 초기 유럽 미술에서 시작된 초현실주의의 역사를 다루었다.","sense":"비현실적인"},{"wordId":15876,"answer":"swarms","form":"복수형","example":"Several swarms of bees appeared near the picnic tables that afternoon.","exampleTranslation":"그날 오후 소풍 테이블 근처에 벌 떼 여러 무리가 나타났다.","sense":"벌떼"},{"wordId":15877,"answer":"Swooping","form":"-ing형","example":"Swooping low over the water, the pelican caught a fish in seconds.","exampleTranslation":"펠리컨은 물 위로 낮게 급강하하며 몇 초 만에 물고기를 잡았다.","sense":"급강하하다"},{"wordId":15877,"answer":"will swoop","form":"미래","example":"At dawn, the hawk will swoop down toward the open field to hunt.","exampleTranslation":"새벽에 그 매는 사냥하기 위해 트인 들판을 향해 급강하할 것이다.","sense":"급강하하다"},{"wordId":15878,"answer":"syllables","form":"복수형","example":"The teacher asked students to count the syllables in each new word.","exampleTranslation":"선생님은 학생들에게 새 단어마다 음절을 세어 보라고 했다.","sense":"음절"},{"wordId":15879,"answer":"syndicates","form":"복수형","example":"Several media syndicates bought up local newspapers across the state last year.","exampleTranslation":"여러 언론 신디케이트가 작년 그 주 전역의 지역 신문사를 사들였다.","sense":"연합체","alts":["combinations","guilds"]},{"wordId":15880,"answer":"synonyms","form":"복수형","example":"Can you give me two synonyms for the word happy in this sentence?","exampleTranslation":"이 문장에서 '행복하다'라는 단어의 동의어 두 개를 말해 줄 수 있어?","sense":"동의어"},{"wordId":15881,"answer":"syrups","form":"복수형","example":"The cafe offers several flavored syrups to add to your coffee or tea.","exampleTranslation":"그 카페는 커피나 차에 넣을 수 있는 여러 가지 향이 나는 시럽을 제공한다.","sense":"시럽"},{"wordId":15882,"answer":"tabs","form":"복수형","example":"Click one of the open tabs to switch between pages in your browser.","exampleTranslation":"브라우저에서 열려 있는 탭 중 하나를 클릭해 페이지를 전환하라.","sense":"탭"},{"wordId":15883,"answer":"taboos","form":"복수형","example":"Discussing money openly is still considered one of several taboos in some cultures.","exampleTranslation":"돈 이야기를 대놓고 하는 것은 일부 문화권에서 여전히 여러 금기 중 하나로 여겨진다.","sense":"금기"},{"wordId":15884,"answer":"tallies","form":"복수형","example":"The volunteer kept separate tallies of how many meals were served each day.","exampleTranslation":"그 자원봉사자는 매일 제공된 식사 수를 따로 집계했다.","sense":"셈","alts":["aggregates"]},{"wordId":15885,"answer":"tankers","form":"복수형","example":"Several large tankers carrying oil were delayed near the coast that week.","exampleTranslation":"그 주에 원유를 실은 대형 유조선 여러 척이 해안 근처에서 지연되었다.","sense":"유조선"},{"wordId":15886,"answer":"tarter","form":"비교급","example":"This year's apples tasted tarter than the ones we picked last autumn.","exampleTranslation":"올해 사과는 작년 가을에 딴 것보다 더 새콤했다.","sense":"새콤한","alts":["tangier"]},{"wordId":15886,"answer":"tartly","form":"부사형","example":"She replied tartly when her coworker questioned her decision in front of everyone.","exampleTranslation":"동료가 모두가 보는 앞에서 그녀의 결정에 의문을 제기하자 그녀는 톡 쏘듯 대답했다.","sense":"새콤한"},{"wordId":15887,"answer":"tattoos","form":"복수형","example":"He has several small tattoos on his arm honoring different family members.","exampleTranslation":"그는 여러 가족을 기리는 작은 문신을 팔에 여러 개 새겼다.","sense":"문신"},{"wordId":15888,"answer":"taunted","form":"과거형","example":"The older boys taunted him about his accent just last week.","exampleTranslation":"그 형들은 바로 지난주 그의 억양을 두고 그를 조롱했다.","sense":"비웃다","alts":["derided"]},{"wordId":15888,"answer":"has taunted","form":"현재완료","example":"That online troll has taunted several streamers ever since the channel launched.","exampleTranslation":"그 온라인 트롤은 그 채널이 개설된 이후로 줄곧 여러 스트리머를 조롱해 왔다.","sense":"비웃다","alts":["have derided"]},{"wordId":15889,"answer":"taverns","form":"복수형","example":"The travelers stopped at several cozy taverns during their long road trip.","exampleTranslation":"여행객들은 긴 여정 동안 아늑한 선술집 여러 곳에 들렀다.","sense":"선술집","alts":["pubs"]},{"wordId":15890,"answer":"terminological","form":"형용사형","example":"The professor's terminological choices made the lecture difficult for beginner students.","exampleTranslation":"그 교수가 사용한 어려운 용어들 때문에 초보 학생들은 강의를 따라가기 힘들었다.","sense":"전문 용어"},{"wordId":15891,"answer":"theologians","form":"복수형","example":"Several respected theologians contributed essays to the new book on faith.","exampleTranslation":"여러 존경받는 신학자가 신앙에 관한 새 책에 글을 실었다.","sense":"신학자"},{"wordId":15892,"answer":"thorns","form":"복수형","example":"She pricked her fingers on several thorns while picking roses in the garden.","exampleTranslation":"그녀는 정원에서 장미를 꺾다가 손가락이 가시 여러 개에 찔렸다.","sense":"가시","alts":["splinters"]},{"wordId":15893,"answer":"thrashed","form":"과거분사","example":"The visiting team, thoroughly thrashed in the first half, gave up completely by halftime.","exampleTranslation":"손님 팀은 전반전에 완전히 완파당해서 하프타임쯤에는 완전히 포기했다.","sense":"완파하다"},{"wordId":15893,"answer":"will thrash","form":"미래","example":"Analysts predict the champion will thrash any challenger in tonight's final match.","exampleTranslation":"분석가들은 그 챔피언이 오늘 밤 결승전에서 어떤 도전자든 완파할 것이라고 예측한다.","sense":"완파하다"},{"wordId":15894,"answer":"Throbbing","form":"-ing형","example":"Throbbing painfully after the fall, his ankle swelled up within minutes.","exampleTranslation":"넘어진 뒤 고통스럽게 욱신거리며 그의 발목은 몇 분 만에 부어올랐다.","sense":"욱신거리다"},{"wordId":15894,"answer":"is throbbing","form":"현재진행","example":"His head is throbbing right now after staring at the screen for hours.","exampleTranslation":"화면을 몇 시간 동안 쳐다본 뒤 지금 그의 머리가 욱신거리고 있다.","sense":"욱신거리다"},{"wordId":15895,"answer":"thwarts","form":"3인칭 단수형","example":"Bad weather usually thwarts our weekend hiking plans in early spring.","exampleTranslation":"나쁜 날씨는 이른 봄에 대개 우리의 주말 등산 계획을 좌절시킨다.","sense":"무산시키다","alts":["frustrates"]},{"wordId":15895,"answer":"is thwarting","form":"현재진행","example":"Heavy fog is thwarting every takeoff at the airport right now.","exampleTranslation":"짙은 안개가 지금 공항의 모든 이륙을 방해하고 있다.","sense":"좌절시키다","alts":["are disrupting","is hampering"]},{"wordId":15896,"answer":"tickled","form":"과거형","example":"My uncle tickled the baby's feet and made her giggle just yesterday.","exampleTranslation":"우리 삼촌은 바로 어제 아기의 발을 간지럽혀서 아기를 웃게 만들었다.","sense":"간지럽히다"},{"wordId":15896,"answer":"has tickled","form":"현재완료","example":"This clever comedy has tickled audiences everywhere since it first premiered.","exampleTranslation":"이 영리한 코미디는 처음 개봉한 이후로 어디서나 관객들을 즐겁게 해 왔다.","sense":"재미있게하다"},{"wordId":15897,"answer":"tiers","form":"복수형","example":"The subscription offers three different tiers: basic, standard, and premium options.","exampleTranslation":"그 구독 서비스는 기본, 표준, 프리미엄이라는 세 가지 다른 등급을 제공한다.","sense":"등급"},{"wordId":15898,"answer":"Toppling","form":"-ing형","example":"Toppling every record in the league, the young sprinter became an instant star.","exampleTranslation":"리그의 모든 기록을 무너뜨리며 그 젊은 단거리 선수는 순식간에 스타가 되었다.","sense":"무너뜨리다"},{"wordId":15898,"answer":"was toppled","form":"수동태","example":"The old dictator was toppled by a massive public uprising last spring.","exampleTranslation":"그 오래된 독재자는 지난봄 대규모 민중 봉기로 무너졌다.","sense":"무너뜨리다"},{"wordId":15899,"answer":"torque","form":"원형","example":"The mechanic increased the torque on the engine bolts to meet safety standards.","exampleTranslation":"그 정비사는 안전 기준을 맞추기 위해 엔진 볼트의 회전력을 높였다.","sense":"회전력"},{"wordId":15900,"answer":"touted","form":"과거형","example":"The salesman touted the vacuum as the best on the market just yesterday.","exampleTranslation":"그 판매원은 바로 어제 그 청소기를 시장 최고 제품이라고 열렬히 홍보했다.","sense":"홍보하다"},{"wordId":15900,"answer":"has touted","form":"현재완료","example":"The mayor has touted the new subway line as a major achievement since opening day.","exampleTranslation":"그 시장은 개통일 이후로 그 새 지하철 노선을 주요 성과라고 홍보해 왔다.","sense":"떠벌리다","alts":["has publicized"]},{"wordId":15901,"answer":"toxins","form":"복수형","example":"Drinking contaminated water can introduce several harmful toxins into your body.","exampleTranslation":"오염된 물을 마시면 몸속에 여러 해로운 독소가 들어올 수 있다.","sense":"독소"},{"wordId":15902,"answer":"trafficked","form":"원형","example":"Authorities rescued several trafficked workers from a factory operating illegally overnight.","exampleTranslation":"당국은 밤새 불법으로 운영되던 공장에서 밀매된 노동자 여럿을 구출했다.","sense":"밀매된"},{"wordId":15902,"answer":"trafficking","form":"명사형","example":"The new law targets human trafficking networks operating across several border regions.","exampleTranslation":"그 새 법은 여러 국경 지역에서 활동하는 인신매매 조직을 단속 대상으로 삼는다.","sense":"밀매된"},{"wordId":15903,"answer":"transcribes","form":"3인칭 단수형","example":"This software usually transcribes voice memos into text within seconds.","exampleTranslation":"이 소프트웨어는 대개 몇 초 안에 음성 메모를 텍스트로 옮겨 적는다.","sense":"옮겨적다"},{"wordId":15903,"answer":"is transcribing","form":"현재진행","example":"The assistant is transcribing the interview recording right now for tomorrow's article.","exampleTranslation":"그 비서는 내일 기사를 위해 지금 인터뷰 녹음을 옮겨 적고 있다.","sense":"옮겨적다"},{"wordId":15904,"answer":"more transient","form":"비교급","example":"Modern jobs have become more transient as workers switch companies every few years.","exampleTranslation":"요즘 직장은 사람들이 몇 년마다 회사를 옮기면서 더 일시적인 성격을 띠게 되었다.","sense":"일시적"},{"wordId":15904,"answer":"transience","form":"명사형","example":"The poem reflects on the transience of youth and the passing of each season.","exampleTranslation":"그 시는 청춘의 덧없음과 계절이 지나가는 모습을 되돌아본다.","sense":"일시적인"},{"wordId":15905,"answer":"trashy","form":"형용사형","example":"The magazine's trashy tabloid stories embarrassed several celebrities featured that week.","exampleTranslation":"그 잡지의 저속한 타블로이드 기사는 그 주에 실린 여러 유명인을 당혹스럽게 만들었다.","sense":"쓰레기"},{"wordId":15906,"answer":"Traversing","form":"-ing형","example":"Traversing the narrow mountain ridge took the climbers nearly three full hours.","exampleTranslation":"좁은 산등성이를 가로지르는 데 등반가들은 거의 세 시간이 꼬박 걸렸다.","sense":"가로지르다"},{"wordId":15906,"answer":"was traversed","form":"수동태","example":"The entire desert was traversed by the expedition team in just ten days.","exampleTranslation":"그 사막 전체는 탐험대에 의해 단 열흘 만에 횡단되었다.","sense":"횡단하다"},{"wordId":15907,"answer":"treacherous","form":"형용사형","example":"The mountain path became treacherous after a sudden ice storm hit overnight.","exampleTranslation":"산길은 밤사이 갑작스러운 얼음 폭풍이 몰아친 뒤 매우 위험해졌다.","sense":"배신"},{"wordId":15908,"answer":"treks","form":"복수형","example":"The group completed several challenging treks through the Himalayan foothills last year.","exampleTranslation":"그 일행은 작년에 히말라야 산기슭에서 힘든 여정을 여러 번 마쳤다.","sense":"장거리 여행","alts":["journeys"]},{"wordId":15909,"answer":"tribunes","form":"복수형","example":"Ancient Rome relied on several tribunes to protect the rights of ordinary citizens.","exampleTranslation":"고대 로마는 평범한 시민의 권리를 지키기 위해 여러 호민관에게 의지했다.","sense":"호민관"},{"wordId":15910,"answer":"trinity","form":"원형","example":"The professor explained how the concept of trinity appears in several ancient religious traditions.","exampleTranslation":"그 교수는 삼위일체라는 개념이 여러 고대 종교 전통에서 어떻게 나타나는지 설명했다.","sense":"삼위일체"},{"wordId":15911,"answer":"trolleys","form":"복수형","example":"She loaded her groceries onto two trolleys before heading toward the checkout.","exampleTranslation":"그녀는 계산대로 가기 전 장 본 물건을 손수레 두 대에 나눠 실었다.","sense":"손수레"},{"wordId":15912,"answer":"trumped","form":"과거형","example":"Her calm argument trumped his angry shouting during the whole debate.","exampleTranslation":"그녀의 차분한 주장은 토론 내내 그의 화난 고함을 이겼다.","sense":"제압하다","alts":["won"]},{"wordId":15912,"answer":"has trumped","form":"현재완료","example":"Convenience has trumped price for most shoppers since online delivery became common.","exampleTranslation":"온라인 배달이 흔해진 이후로 대부분의 쇼핑객에게는 편리함이 가격을 능가해 왔다.","sense":"이기다","alts":["have outweighed"]},{"wordId":15913,"answer":"tsars","form":"복수형","example":"Several tsars ruled over the vast Russian empire during that turbulent era.","exampleTranslation":"그 격동의 시대 동안 여러 차르가 광활한 러시아 제국을 다스렸다.","sense":"차르"},{"wordId":15914,"answer":"tuberculosis","form":"원형","example":"Public health workers launched a campaign to prevent tuberculosis from spreading in crowded areas.","exampleTranslation":"공중보건 요원들은 사람이 붐비는 지역에서 결핵이 퍼지는 것을 막기 위한 캠페인을 시작했다.","sense":"결핵"},{"wordId":15915,"answer":"tuition","form":"원형","example":"Many families struggle to pay tuition for their children's private school education each year.","exampleTranslation":"많은 가정이 매년 자녀의 사립 학교 수업료를 내느라 어려움을 겪는다.","sense":"수업료"},{"wordId":15916,"answer":"tuna","form":"원형","example":"She grilled fresh tuna with lemon and herbs for the family dinner on Sunday.","exampleTranslation":"그녀는 일요일 가족 저녁 식사를 위해 레몬과 허브를 곁들여 신선한 참치를 구웠다.","sense":"참치"},{"wordId":15917,"answer":"turbines","form":"복수형","example":"The wind farm has dozens of turbines generating electricity for nearby towns.","exampleTranslation":"그 풍력 발전 단지에는 인근 마을에 전기를 공급하는 터빈이 수십 개 있다.","sense":"터빈"},{"wordId":15918,"answer":"turmoil","form":"원형","example":"The country fell into turmoil after the president suddenly resigned during the crisis.","exampleTranslation":"대통령이 위기 중 갑자기 사임한 뒤 그 나라는 혼란에 빠졌다.","sense":"혼란"},{"wordId":15919,"answer":"twilight","form":"원형","example":"They walked along the beach and watched the sky change color during twilight.","exampleTranslation":"그들은 해변을 걸으며 황혼 동안 하늘빛이 바뀌는 것을 지켜보았다.","sense":"황혼"},{"wordId":15920,"answer":"twine","form":"원형","example":"He tied the tomato plants to wooden stakes using strong garden twine.","exampleTranslation":"그는 튼튼한 정원용 노끈을 사용해 토마토 모종을 나무 말뚝에 묶었다.","sense":"노끈"},{"wordId":15921,"answer":"twofold","form":"원형","example":"The company's profit showed a twofold increase after launching its new product line.","exampleTranslation":"그 회사의 이익은 새 제품 라인을 출시한 뒤 두 배로 늘었다.","sense":"두배의"},{"wordId":15921,"answer":"twofold","form":"원형","example":"Learning a new language brings a twofold benefit: better memory and wider job options.","exampleTranslation":"새 언어를 배우면 기억력 향상과 더 넓은 취업 기회라는 두 가지 이점이 생긴다.","sense":"두배의"},{"wordId":15922,"answer":"Typewriting","form":"-ing형","example":"Typewriting every single letter by hand took the old secretary hours each day.","exampleTranslation":"손으로 편지 한 통 한 통을 타자기로 치는 데 그 옛날 비서는 매일 몇 시간이 걸렸다.","sense":"타자기로 치다","alts":["typing"]},{"wordId":15922,"answer":"was typewritten","form":"수동태","example":"The historic speech was typewritten on a single sheet of yellowed paper.","exampleTranslation":"그 역사적인 연설문은 누렇게 바랜 종이 한 장에 타자기로 쳐져 있었다.","sense":"타자치다"},{"wordId":15923,"answer":"ultraviolet","form":"원형","example":"You should wear sunscreen to protect your skin from strong ultraviolet rays outdoors.","exampleTranslation":"야외에서는 강한 자외선으로부터 피부를 보호하려고 자외선 차단제를 발라야 한다.","sense":"자외선"},{"wordId":15923,"answer":"ultraviolet","form":"원형","example":"Scientists use ultraviolet light to detect counterfeit bills at the currency exchange.","exampleTranslation":"과학자들은 환전소에서 위조지폐를 찾아내려고 자외선을 이용한다.","sense":"자외선"},{"wordId":15924,"answer":"umpires","form":"복수형","example":"Several umpires reviewed the play before making their final decision together.","exampleTranslation":"여러 심판이 함께 최종 판정을 내리기 전 그 플레이를 다시 살폈다.","sense":"심판원","alts":["referees"]},{"wordId":15925,"answer":"underpinned","form":"과거분사","example":"The bridge, freshly underpinned with steel beams, could support much heavier trucks now.","exampleTranslation":"강철 대들보로 새롭게 뒷받침된 그 다리는 이제 훨씬 무거운 트럭도 지탱할 수 있었다.","sense":"뒷받침하다"},{"wordId":15925,"answer":"will underpin","form":"미래","example":"This new policy will underpin economic growth across the whole region for years.","exampleTranslation":"이 새 정책은 여러 해 동안 그 지역 전체의 경제 성장을 뒷받침할 것이다.","sense":"뒷받침하다"},{"wordId":15926,"answer":"Understating","form":"-ing형","example":"Understating the risks of the surgery would be unfair to the worried family.","exampleTranslation":"그 수술의 위험을 과소평가하는 것은 걱정하는 가족에게 부당한 일일 것이다.","sense":"축소해 말하다","alts":["underestimating"]},{"wordId":15926,"answer":"was understated","form":"수동태","example":"The damage from the storm was understated in the first news reports.","exampleTranslation":"그 폭풍으로 인한 피해는 첫 뉴스 보도에서 과소평가되었다.","sense":"축소해 말하다","alts":["was underestimated"]},{"wordId":15927,"answer":"underway","form":"원형","example":"Construction of the new library is already underway and expected to finish by spring.","exampleTranslation":"새 도서관 공사는 이미 진행 중이며 봄까지 끝날 예정이다.","sense":"진행중인"},{"wordId":15927,"answer":"underway","form":"원형","example":"Negotiations between the two companies are underway, though no agreement has been reached yet.","exampleTranslation":"두 회사 사이의 협상은 진행 중이지만 아직 합의에는 이르지 못했다.","sense":"진행중인"},{"wordId":15928,"answer":"underwrote","form":"과거형","example":"The bank underwrote the startup's first funding round just last year.","exampleTranslation":"그 은행은 바로 작년에 그 스타트업의 첫 자금 조달을 보증했다.","sense":"보증하다"},{"wordId":15928,"answer":"has underwritten","form":"현재완료","example":"This insurer has underwritten small farm policies across the region since 2010.","exampleTranslation":"이 보험사는 2010년 이후로 그 지역 전역의 소규모 농장 보험을 인수해 왔다.","sense":"보험을 인수하다","alts":["has guaranteed"]},{"wordId":15929,"answer":"unilateral","form":"원형","example":"The company made a unilateral decision without consulting any of its employees.","exampleTranslation":"그 회사는 직원들과 상의 없이 일방적인 결정을 내렸다.","sense":"일방적"},{"wordId":15929,"answer":"unilaterally","form":"부사형","example":"The president decided unilaterally to withdraw troops without informing the allied nations.","exampleTranslation":"대통령은 동맹국에 알리지 않고 독단적으로 군대 철수를 결정했다.","sense":"일방적인"},{"wordId":15930,"answer":"unison","form":"원형","example":"The whole audience clapped in unison as the final song came to an end.","exampleTranslation":"마지막 노래가 끝날 무렵 관객 전체가 한목소리로 박수를 쳤다.","sense":"한목소리"},{"wordId":15931,"answer":"unravels","form":"3인칭 단수형","example":"Slowly, the mystery unravels as each new witness comes forward with details.","exampleTranslation":"새 목격자가 나올 때마다 세부 사항과 함께 그 미스터리는 천천히 풀린다.","sense":"풀리다"},{"wordId":15931,"answer":"is unraveling","form":"현재진행","example":"Detectives say the whole conspiracy is unraveling faster than anyone expected this week.","exampleTranslation":"형사들은 이번 주 예상보다 훨씬 빠르게 그 음모 전체가 풀리고 있다고 말한다.","sense":"풀리다"},{"wordId":15932,"answer":"unrest","form":"원형","example":"Growing unrest among factory workers led management to reconsider the new overtime policy.","exampleTranslation":"공장 노동자들 사이에서 불안이 커지자 경영진은 새 초과 근무 방침을 재고했다.","sense":"불안"},{"wordId":15933,"answer":"unsettled","form":"과거분사","example":"The unsettled weather forced the pilots to delay every flight that morning.","exampleTranslation":"불안정한 날씨 때문에 조종사들은 그날 아침 모든 항공편을 지연시킬 수밖에 없었다.","sense":"동요시키다"},{"wordId":15933,"answer":"will unsettle","form":"미래","example":"This surprising decision will unsettle investors across the whole market tomorrow.","exampleTranslation":"이 놀라운 결정은 내일 시장 전체에 걸쳐 투자자들을 동요시킬 것이다.","sense":"동요시키다"},{"wordId":15934,"answer":"upheavals","form":"복수형","example":"The company faced several major upheavals in its operations that difficult year.","exampleTranslation":"그 회사는 그 힘든 해에 사업 운영에서 여러 큰 격변을 겪었다.","sense":"격변"},{"wordId":15935,"answer":"uprisings","form":"복수형","example":"Historians have documented several uprisings against colonial rule in that region.","exampleTranslation":"역사학자들은 그 지역에서 있었던 식민 통치에 맞선 여러 봉기를 기록해 왔다.","sense":"봉기"},{"wordId":15936,"answer":"uranium","form":"원형","example":"The plant uses uranium as fuel to generate electricity for the entire region.","exampleTranslation":"그 발전소는 지역 전체에 전기를 공급하기 위해 연료로 우라늄을 사용한다.","sense":"우라늄"},{"wordId":15937,"answer":"vaccinated","form":"과거분사","example":"Only vaccinated travelers were allowed to enter the crowded stadium that weekend.","exampleTranslation":"그 주말에는 예방접종을 받은 여행객만 붐비는 경기장에 들어갈 수 있었다.","sense":"예방접종하다"},{"wordId":15937,"answer":"will vaccinate","form":"미래","example":"The clinic will vaccinate every child in the school by next Friday.","exampleTranslation":"그 병원은 다음 금요일까지 학교의 모든 아이에게 예방접종을 할 것이다.","sense":"예방접종하다"},{"wordId":15938,"answer":"vainer","form":"비교급","example":"As he grew older, he somehow became even vainer about his appearance.","exampleTranslation":"그는 나이가 들수록 오히려 외모에 대해 더 허영심을 부렸다.","sense":"허영심"},{"wordId":15938,"answer":"vainly","form":"부사형","example":"She waited vainly by the phone, hoping for a call that never came.","exampleTranslation":"그녀는 끝내 오지 않은 전화를 기다리며 헛되이 시간을 보냈다.","sense":"허영심 있는"},{"wordId":15939,"answer":"vandals","form":"복수형","example":"Several vandals spray-painted graffiti across the park benches last night.","exampleTranslation":"지난밤 기물파손자 여럿이 공원 벤치 곳곳에 낙서를 스프레이로 칠했다.","sense":"기물파손자"},{"wordId":15940,"answer":"vanity","form":"원형","example":"His vanity made it difficult for him to admit any mistake in front of coworkers.","exampleTranslation":"그의 허영심 때문에 그는 동료들 앞에서 어떤 실수도 인정하기 어려워했다.","sense":"허영심"},{"wordId":15941,"answer":"vapour","form":"원형","example":"Thin vapour rose slowly from the hot spring on the cold mountain morning.","exampleTranslation":"추운 산속 아침, 온천에서 가느다란 수증기가 천천히 피어올랐다.","sense":"수증기"},{"wordId":15942,"answer":"vaults","form":"복수형","example":"The bank keeps large amounts of cash stored inside several secure vaults.","exampleTranslation":"그 은행은 여러 안전한 금고 안에 많은 현금을 보관한다.","sense":"금고"},{"wordId":15943,"answer":"vectors","form":"복수형","example":"In physics class, we learned that several vectors can combine into one force.","exampleTranslation":"물리 수업에서 우리는 여러 벡터가 합쳐져 하나의 힘이 될 수 있다고 배웠다.","sense":"벡터"},{"wordId":15944,"answer":"more vibrant","form":"비교급","example":"The city market felt even more vibrant after the new mural was painted downtown.","exampleTranslation":"새 벽화가 시내에 그려진 뒤 그 도시 시장은 훨씬 더 생기가 넘쳤다.","sense":"생기있는"},{"wordId":15944,"answer":"vibrantly","form":"부사형","example":"The walls of the cafe were vibrantly painted with murals depicting local folklore.","exampleTranslation":"그 카페 벽은 지역 설화를 담은 벽화로 화려하고 강렬하게 칠해져 있었다.","sense":"생기 있는"},{"wordId":15945,"answer":"vicinity","form":"원형","example":"There are several good bakeries in the vicinity of the train station downtown.","exampleTranslation":"시내 기차역 인근에는 괜찮은 빵집이 여러 곳 있다.","sense":"인근"},{"wordId":15946,"answer":"villains","form":"복수형","example":"The movie featured several villains who worked together to trick the hero.","exampleTranslation":"그 영화에는 주인공을 속이려고 함께 움직이는 악당 여럿이 나온다.","sense":"악당","alts":["rogues"]},{"wordId":15947,"answer":"vital","form":"형용사형","example":"Regular exercise and good sleep are vital for maintaining your energy as you age.","exampleTranslation":"규칙적인 운동과 충분한 수면은 나이가 들어도 에너지를 유지하는 데 꼭 필요하다.","sense":"활력"},{"wordId":15948,"answer":"vomited","form":"과거형","example":"The child vomited twice during the car ride and felt better afterward.","exampleTranslation":"그 아이는 차를 타는 동안 두 번 토했고 그 후 몸이 나아졌다.","sense":"토하다"},{"wordId":15948,"answer":"has vomited","form":"현재완료","example":"The puppy has vomited twice already since breakfast this morning.","exampleTranslation":"그 강아지는 오늘 아침 식사 이후로 벌써 두 번이나 토했다.","sense":"토하다"},{"wordId":15949,"answer":"Wading","form":"-ing형","example":"Wading carefully through the shallow creek, the boys searched for smooth stones.","exampleTranslation":"소년들은 얕은 개울을 조심스럽게 헤치고 걸으며 매끄러운 돌을 찾았다.","sense":"물속걷다"},{"wordId":15949,"answer":"will wade","form":"미래","example":"Tomorrow the rescue team will wade into the flooded street to check every house.","exampleTranslation":"내일 구조팀은 모든 집을 확인하러 물에 잠긴 거리로 걸어 들어갈 것이다.","sense":"물속걷다"},{"wordId":15950,"answer":"Waiving","form":"-ing형","example":"Waiving the late fee this once helped the store keep a loyal customer.","exampleTranslation":"이번 한 번 연체료를 면제해 준 것은 그 가게가 단골손님을 지키는 데 도움이 되었다.","sense":"면제하다"},{"wordId":15950,"answer":"was waived","form":"수동태","example":"The application fee was waived for every student who applied before June.","exampleTranslation":"6월 전에 지원한 모든 학생에게는 지원료가 면제되었다.","sense":"면제하다","alts":["were exempted"]},{"wordId":15951,"answer":"walnuts","form":"복수형","example":"She sprinkled crushed walnuts on top of the salad for extra crunch.","exampleTranslation":"그녀는 아삭한 식감을 더하려고 샐러드 위에 다진 호두를 뿌렸다.","sense":"호두"},{"wordId":15952,"answer":"waned","form":"과거형","example":"Public interest in the scandal waned quickly just a few weeks later.","exampleTranslation":"그 스캔들에 대한 대중의 관심은 불과 몇 주 뒤 빠르게 줄어들었다.","sense":"줄어들다"},{"wordId":15952,"answer":"has waned","form":"현재완료","example":"Her enthusiasm for the project has waned steadily since the budget was cut.","exampleTranslation":"예산이 삭감된 이후로 그 프로젝트에 대한 그녀의 열정은 꾸준히 약해졌다.","sense":"약해지다"},{"wordId":15953,"answer":"wardens","form":"복수형","example":"Several wardens introduced new rehabilitation programs for inmates across the state.","exampleTranslation":"여러 교도소장이 그 주 전역의 수감자를 위한 새 재활 프로그램을 도입했다.","sense":"교도소장"},{"wordId":15954,"answer":"Warping","form":"-ing형","example":"Warping slightly in the summer heat, the old vinyl records became unplayable.","exampleTranslation":"여름 더위 속에서 약간 뒤틀리면서 그 오래된 비닐 레코드판은 재생할 수 없게 되었다.","sense":"뒤틀리다"},{"wordId":15954,"answer":"was warped","form":"수동태","example":"The wooden door was warped badly after years of exposure to rain.","exampleTranslation":"그 나무 문은 수년간 비에 노출된 뒤 심하게 뒤틀렸다.","sense":"뒤틀리다"},{"wordId":15955,"answer":"warranties","form":"복수형","example":"Both laptops come with two-year warranties that cover parts and labor.","exampleTranslation":"두 노트북 모두 부품과 인건비를 보장하는 2년 품질보증이 딸려 있다.","sense":"품질보증"},{"wordId":15956,"answer":"wasps","form":"복수형","example":"Several wasps flew into the kitchen and everyone scrambled to open the windows.","exampleTranslation":"말벌 여러 마리가 부엌으로 날아들자 모두가 서둘러 창문을 열었다.","sense":"말벌"},{"wordId":15957,"answer":"Wavering","form":"-ing형","example":"Wavering between two job offers, she finally asked her mentor for advice.","exampleTranslation":"두 개의 취업 제안 사이에서 망설이다가 그녀는 마침내 멘토에게 조언을 구했다.","sense":"망설이다"},{"wordId":15957,"answer":"will waver","form":"미래","example":"If ticket prices rise again, some loyal fans will waver in their season pass commitment.","exampleTranslation":"입장권 가격이 다시 오르면 일부 충성 팬들은 시즌권 약속을 두고 망설일 것이다.","sense":"망설이다"},{"wordId":15958,"answer":"Whining","form":"-ing형","example":"Whining about the homework will not make it disappear any faster.","exampleTranslation":"숙제에 대해 칭얼거린다고 해서 그것이 더 빨리 사라지지는 않는다.","sense":"칭얼거리다"},{"wordId":15958,"answer":"is whining","form":"현재진행","example":"The puppy is whining at the door because it wants to go outside.","exampleTranslation":"그 강아지는 밖에 나가고 싶어서 지금 문 앞에서 칭얼거리고 있다.","sense":"칭얼거리다"},{"wordId":15959,"answer":"whirls","form":"3인칭 단수형","example":"Each autumn, a single golden leaf usually whirls through the air outside my window.","exampleTranslation":"매년 가을 황금빛 낙엽 하나가 대개 우리 집 창밖 공중에서 빙빙 돈다.","sense":"빙빙돌다"},{"wordId":15959,"answer":"is whirling","form":"현재진행","example":"The dancer is whirling gracefully across the stage under the bright lights.","exampleTranslation":"그 무용수는 밝은 조명 아래 무대를 가로지르며 우아하게 빙빙 돌고 있다.","sense":"빙빙돌다"},{"wordId":15960,"answer":"wielded","form":"과거형","example":"The old general wielded enormous influence over the army two decades ago.","exampleTranslation":"그 노장군은 이십 년 전 군대에 막대한 영향력을 행사했다.","sense":"행사하다","alts":["exerted"]},{"wordId":15960,"answer":"has wielded","form":"현재완료","example":"The senator has wielded considerable power in the committee since her election.","exampleTranslation":"그 상원의원은 당선된 이후로 위원회에서 상당한 권력을 행사해 왔다.","sense":"행사하다","alts":["has exerted"]},{"wordId":15961,"answer":"wigs","form":"복수형","example":"She wore several wigs during the play to look like historical characters.","exampleTranslation":"그녀는 연극에서 역사 속 인물처럼 보이려고 가발을 여러 개 썼다.","sense":"가발"},{"wordId":15962,"answer":"willows","form":"복수형","example":"Several tall willows stood by the river, their branches trailing in the water.","exampleTranslation":"키 큰 버드나무 여러 그루가 강가에 서 있었고, 가지가 물에 늘어져 있었다.","sense":"버드나무"},{"wordId":15963,"answer":"winces","form":"3인칭 단수형","example":"He always winces whenever the dentist mentions getting a new filling.","exampleTranslation":"그는 치과의사가 새 충전 치료를 언급할 때마다 늘 움찔한다.","sense":"움찔하다"},{"wordId":15963,"answer":"is wincing","form":"현재진행","example":"Look, the little boy is wincing right now as the nurse cleans his scraped knee.","exampleTranslation":"봐, 간호사가 상처 난 무릎을 소독하는 동안 저 어린 남자아이가 지금 움찔하고 있어.","sense":"움찔하다"},{"wordId":15964,"answer":"withered","form":"과거형","example":"The roses withered quickly after the sudden frost hit the garden last week.","exampleTranslation":"지난주 갑작스러운 서리가 내린 뒤 장미가 금세 시들었다.","sense":"시들다"},{"wordId":15964,"answer":"has withered","form":"현재완료","example":"The old oak tree has withered steadily since the drought began three summers ago.","exampleTranslation":"그 오래된 참나무는 삼 년 전 가뭄이 시작된 이후로 계속 시들어 왔다.","sense":"시들다"},{"wordId":15965,"answer":"withstanding","form":"-ing형","example":"Withstanding the harsh desert heat requires proper hydration and light, breathable clothing.","exampleTranslation":"혹독한 사막 더위를 견디려면 충분한 수분 섭취와 가볍고 통풍 잘되는 옷이 필요하다.","sense":"견디다"},{"wordId":15965,"answer":"will withstand","form":"미래","example":"Engineers promise the new bridge will withstand even the strongest earthquakes in the region.","exampleTranslation":"기술자들은 새 다리가 그 지역에서 가장 강한 지진도 견뎌 낼 것이라고 장담한다.","sense":"견디다"},{"wordId":15966,"answer":"wobbling","form":"-ing형","example":"The toddler kept wobbling across the living room before finally taking her first real steps.","exampleTranslation":"그 아기는 마침내 진짜 첫걸음을 떼기 전까지 거실을 가로지르며 계속 비틀거렸다.","sense":"휘청거리다","alts":["swaying"]},{"wordId":15966,"answer":"is wobbling","form":"현재진행","example":"Careful, the ladder is wobbling right now because one of its legs is uneven.","exampleTranslation":"조심해, 사다리 다리 한쪽이 고르지 않아서 지금 흔들리고 있어.","sense":"흔들거리다","alts":["are faltering"]},{"wordId":15967,"answer":"woes","form":"복수형","example":"She listened patiently as he described the many woes he faced that year.","exampleTranslation":"그녀는 그가 그해 겪은 여러 고충을 이야기하는 것을 참을성 있게 들어 주었다.","sense":"불행","alts":["sorrows"]},{"wordId":15968,"answer":"wooed","form":"과거형","example":"The young prince wooed the princess with poems and flowers throughout that whole summer.","exampleTranslation":"그 젊은 왕자는 그해 여름 내내 시와 꽃으로 공주에게 구애했다.","sense":"구애하다"},{"wordId":15968,"answer":"has wooed","form":"현재완료","example":"The startup has wooed several major investors since it launched its product last year.","exampleTranslation":"그 스타트업은 작년에 제품을 출시한 이후로 여러 주요 투자자의 호감을 얻어 왔다.","sense":"호감얻다"},{"wordId":15969,"answer":"wrenches","form":"복수형","example":"He used several wrenches of different sizes to tighten the loose bolts.","exampleTranslation":"그는 헐거운 볼트를 조이려고 크기가 다른 렌치를 여러 개 사용했다.","sense":"렌치"},{"wordId":15970,"answer":"wretches","form":"복수형","example":"The story described several poor wretches who had nowhere to go that winter.","exampleTranslation":"그 이야기는 그해 겨울 갈 곳 없던 불쌍한 사람 여럿을 그렸다.","sense":"불쌍한사람"},{"wordId":15971,"answer":"wryest","form":"최상급","example":"Of all the comedians that night, his jokes had the wryest sense of humor.","exampleTranslation":"그날 밤 모든 코미디언 중에서 그의 농담이 가장 비꼬는 유머 감각을 지녔다.","sense":"비꼬는"},{"wordId":15971,"answer":"wryly","form":"부사형","example":"She smiled wryly when her brother finally admitted that she had been right.","exampleTranslation":"동생이 마침내 그녀가 옳았다고 인정하자 그녀는 냉소적으로 웃었다.","sense":"비꼬는"},{"wordId":15972,"answer":"yanked","form":"과거형","example":"He yanked the stubborn weed out of the garden bed early this morning.","exampleTranslation":"그는 오늘 아침 일찍 정원 화단에서 고집스러운 잡초를 확 잡아 뽑았다.","sense":"잡아당기다"},{"wordId":15972,"answer":"has yanked","form":"현재완료","example":"The mechanic has yanked out the broken engine part several times already this week.","exampleTranslation":"그 정비사는 이번 주에 벌써 여러 번 고장 난 엔진 부품을 확 뽑아냈다.","sense":"잡아당기다"},{"wordId":15973,"answer":"yarn","form":"원형","example":"My aunt knitted a warm blanket using thick red yarn she bought last winter.","exampleTranslation":"이모는 지난겨울에 산 두꺼운 빨간 실로 따뜻한 담요를 짰다.","sense":"실"},{"wordId":15974,"answer":"yawning","form":"-ing형","example":"Yawning loudly during the meeting, he apologized and blamed his lack of sleep.","exampleTranslation":"회의 중 크게 하품을 하고 나서 그는 사과하며 잠을 못 잔 탓이라고 말했다.","sense":"하품하다"},{"wordId":15974,"answer":"is yawning","form":"현재진행","example":"Look at the cat, it is yawning right now after waking up from its long nap.","exampleTranslation":"저 고양이 좀 봐, 긴 낮잠에서 깨어난 뒤 지금 하품을 하고 있어.","sense":"하품하다"},{"wordId":15975,"answer":"yearns","form":"3인칭 단수형","example":"He often yearns for the quiet countryside whenever the city feels too crowded.","exampleTranslation":"그는 도시가 너무 붐빈다고 느낄 때마다 조용한 시골을 자주 그리워한다.","sense":"갈망하다"},{"wordId":15975,"answer":"is yearning","form":"현재진행","example":"She is yearning right now for her family back home after months working abroad.","exampleTranslation":"그녀는 몇 달째 해외에서 일한 뒤 지금 고향의 가족을 몹시 그리워하고 있다.","sense":"갈망하다"},{"wordId":15976,"answer":"yeast","form":"원형","example":"You must add fresh yeast to the dough so the bread rises properly.","exampleTranslation":"빵이 제대로 부풀도록 반죽에 신선한 효모를 넣어야 한다.","sense":"효모"},{"wordId":15977,"answer":"yen","form":"원형","example":"He exchanged his dollars for yen at the airport before flying to Tokyo.","exampleTranslation":"그는 도쿄로 가기 전 공항에서 달러를 엔화로 환전했다.","sense":"엔화"},{"wordId":15978,"answer":"zealous","form":"형용사형","example":"The new volunteer was remarkably zealous about helping the local community every weekend.","exampleTranslation":"그 새 자원봉사자는 주말마다 지역 사회를 돕는 데 놀라울 만큼 열심이었다.","sense":"열정"},{"wordId":15979,"answer":"zooms","form":"3인칭 단수형","example":"That delivery truck usually zooms past our house right before sunrise every morning.","exampleTranslation":"저 택배 트럭은 보통 해뜨기 직전에 우리 집 앞을 쌩 지나간다.","sense":"빠르게"},{"wordId":15979,"answer":"is zooming","form":"현재진행","example":"The little girl is zooming around the yard right now on her new bicycle.","exampleTranslation":"그 어린 소녀가 새 자전거를 타고 지금 마당을 쌩쌩 돌아다니고 있다.","sense":"빠르게"},{"wordId":16002,"answer":"accents","form":"복수형","example":"The tour guide could recognize several regional accents among the tourists.","exampleTranslation":"그 관광 가이드는 관광객들 사이에서 여러 지역 억양을 알아챌 수 있었다.","sense":"억양"},{"wordId":16003,"answer":"aces","form":"3인칭 단수형","example":"My roommate always aces every difficult exam without studying very much.","exampleTranslation":"내 룸메이트는 별로 공부하지 않고도 항상 어려운 시험을 완벽하게 해낸다.","sense":"완벽하게해내다"},{"wordId":16003,"answer":"is acing","form":"현재진행","example":"This semester, my cousin is acing every single one of her chemistry tests.","exampleTranslation":"이번 학기 내 사촌은 화학 시험 하나하나를 완벽하게 해내고 있다.","sense":"완벽하게해내다"},{"wordId":16004,"answer":"all","form":"원형","example":"All the students in the class passed the final exam this semester.","exampleTranslation":"이번 학기에는 그 반의 모든 학생이 기말고사를 통과했다.","sense":"모든"},{"wordId":16004,"answer":"all","form":"원형","example":"She cleaned all the windows in the house before her parents arrived.","exampleTranslation":"그녀는 부모님이 도착하기 전에 집 안의 모든 창문을 청소했다.","sense":"모든"},{"wordId":16005,"answer":"also","form":"원형","example":"The museum offers free entry and also sells souvenir postcards.","exampleTranslation":"그 박물관은 무료 입장을 제공하고 또한 기념 엽서도 판다.","sense":"또한"},{"wordId":16007,"answer":"another","form":"원형","example":"The waiter brought another basket of bread after we finished the first one.","exampleTranslation":"우리가 첫 번째 빵 바구니를 다 먹자 종업원이 또 다른 바구니를 가져다주었다.","sense":"또 다른"},{"wordId":16007,"answer":"another","form":"원형","example":"He decided to open another store in a different part of town next year.","exampleTranslation":"그는 내년에 시내 다른 지역에 또 다른 매장을 열기로 결정했다.","sense":"또 다른"},{"wordId":16008,"answer":"any","form":"원형","example":"If employees have any questions about the project, they should email the manager directly.","exampleTranslation":"직원들은 프로젝트에 대해 어떤 질문이라도 있으면 관리자에게 직접 이메일을 보내야 한다.","sense":"어떤"},{"wordId":16008,"answer":"any","form":"원형","example":"The store did not have any umbrellas left after the sudden rainstorm yesterday.","exampleTranslation":"어제 갑작스러운 폭우 이후 그 가게에는 우산이 조금도 남아 있지 않았다.","sense":"조금도"},{"wordId":16009,"answer":"away","form":"원형","example":"The nearest hospital is ten miles away from our village.","exampleTranslation":"가장 가까운 병원은 우리 마을에서 10마일 멀리 떨어져 있다.","sense":"멀리"},{"wordId":16010,"answer":"back","form":"원형","example":"The technician promised to call the customer back within an hour.","exampleTranslation":"기술자는 한 시간 안에 그 고객에게 다시 전화하겠다고 약속했다.","sense":"다시"},{"wordId":16013,"answer":"billions","form":"복수형","example":"Billions of people around the world now use smartphones every day.","exampleTranslation":"이제 전 세계 수십억 명의 사람들이 매일 스마트폰을 사용한다.","sense":"10억"},{"wordId":16014,"answer":"most boring","form":"최상급","example":"Everyone agreed that the safety training video was the most boring part of orientation.","exampleTranslation":"모든 사람이 그 안전 교육 영상이 오리엔테이션에서 가장 지루한 부분이라는 데 동의했다.","sense":"지루한","alts":["dullest"]},{"wordId":16014,"answer":"boredom","form":"명사형","example":"Boredom set in quickly once the long flight lost its onboard entertainment system.","exampleTranslation":"장거리 비행에서 기내 오락 시스템이 고장나자 지루함이 금세 찾아왔다.","sense":"지루한","alts":["dullness"]},{"wordId":16015,"answer":"amuses","form":"3인칭 단수형","example":"That particular clown always amuses the children with his silly balloon tricks.","exampleTranslation":"그 특정 광대는 우스꽝스러운 풍선 묘기로 항상 아이들을 즐겁게 해 준다.","sense":"재미있게 하다","alts":["entertains"]},{"wordId":16015,"answer":"is amusing","form":"현재진행","example":"During recess, the substitute teacher is amusing the whole class with funny stories.","exampleTranslation":"쉬는 시간 동안 그 대체 교사는 재미있는 이야기로 반 전체를 즐겁게 해 주고 있다.","sense":"즐겁게하다"},{"wordId":16016,"answer":"angels","form":"복수형","example":"The children dressed as angels for the school Christmas play.","exampleTranslation":"아이들은 학교 크리스마스 연극을 위해 천사 옷을 입었다.","sense":"천사"},{"wordId":16017,"answer":"both","form":"원형","example":"Both restaurants on that street serve excellent pasta at reasonable prices.","exampleTranslation":"그 거리의 두 식당 모두 합리적인 가격에 훌륭한 파스타를 제공한다.","sense":"둘 다"},{"wordId":16017,"answer":"both","form":"원형","example":"Both children finished their homework before dinner was ready tonight.","exampleTranslation":"두 아이 모두 오늘 저녁 식사가 준비되기 전에 숙제를 끝냈다.","sense":"둘 다"},{"wordId":16018,"answer":"bushes","form":"복수형","example":"Several thorny bushes grew wild along the abandoned railway track.","exampleTranslation":"버려진 철길을 따라 가시투성이 덤불 여러 그루가 제멋대로 자랐다.","sense":"덤불"},{"wordId":16019,"answer":"Christmas","form":"원형","example":"Every year, her family travels overseas to spend Christmas with relatives.","exampleTranslation":"매년 그녀의 가족은 친척들과 크리스마스를 보내려고 해외로 간다.","sense":"크리스마스"},{"wordId":16020,"answer":"darling","form":"원형","example":"Grandma always called her youngest grandchild a darling little troublemaker.","exampleTranslation":"할머니는 항상 막내 손주를 사랑스러운 말썽꾸러기라고 불렀다.","sense":"사랑스러운"},{"wordId":16020,"answer":"darling","form":"원형","example":"The audience found the darling puppy in the commercial absolutely impossible to resist.","exampleTranslation":"관객들은 그 광고 속 사랑스러운 강아지를 도저히 거부할 수 없다고 느꼈다.","sense":"사랑스러운"},{"wordId":16021,"answer":"definite","form":"원형","example":"The landlord wants a definite decision about the lease renewal before the end of the month.","exampleTranslation":"집주인은 이번 달 말 전에 임대 계약 갱신에 대한 확실한 결정을 원한다.","sense":"확실한"},{"wordId":16021,"answer":"definitely","form":"부사형","example":"The waiter definitely remembered our order despite the busy dinner rush that night.","exampleTranslation":"그 종업원은 그날 밤 바쁜 저녁 시간에도 우리 주문을 확실히 기억하고 있었다.","sense":"확실한","alts":["conclusively"]},{"wordId":16023,"answer":"eight","form":"원형","example":"The recipe calls for eight fresh eggs to make enough batter for the whole cake.","exampleTranslation":"그 조리법은 케이크 반죽을 충분히 만들기 위해 신선한 달걀 여덟 개를 필요로 한다.","sense":"여덟"},{"wordId":16023,"answer":"eight","form":"원형","example":"The bakery opens at eight every morning except on public holidays.","exampleTranslation":"그 빵집은 공휴일을 제외하고 매일 아침 여덟 시에 문을 연다.","sense":"여덟"},{"wordId":16024,"answer":"eleven","form":"원형","example":"Our flight departs at eleven tonight, so we should leave for the airport soon.","exampleTranslation":"우리 비행기는 오늘 밤 열한 시에 출발하니 곧 공항으로 출발해야 한다.","sense":"열하나"},{"wordId":16024,"answer":"eleven","form":"원형","example":"During tryouts, the coach explained why only eleven athletes would make the final roster.","exampleTranslation":"선발전 동안 코치는 왜 열한 명의 선수만 최종 명단에 들지 설명했다.","sense":"열하나"},{"wordId":16025,"answer":"every","form":"원형","example":"The nurse checks each patient's chart every single morning during rounds.","exampleTranslation":"그 간호사는 회진 동안 매일 아침마다 환자 개개인의 차트를 확인한다.","sense":"모든"},{"wordId":16025,"answer":"every","form":"원형","example":"Every store in the mall closes early on national holidays.","exampleTranslation":"그 쇼핑몰의 모든 가게는 국경일에는 일찍 문을 닫는다.","sense":"모든"},{"wordId":16026,"answer":"five","form":"원형","example":"The recipe calls for five ripe tomatoes and a handful of fresh basil.","exampleTranslation":"그 조리법은 잘 익은 토마토 다섯 개와 신선한 바질 한 줌을 필요로 한다.","sense":"다섯"},{"wordId":16026,"answer":"five","form":"원형","example":"Their apartment building has five floors and no elevator, so deliveries take time.","exampleTranslation":"그들의 아파트 건물은 다섯 개 층이며 엘리베이터가 없어서 배달에 시간이 걸린다.","sense":"다섯"},{"wordId":16027,"answer":"four","form":"원형","example":"The old sedan has four doors but only two working seat belts in the back.","exampleTranslation":"그 오래된 세단은 문이 네 개지만 뒷좌석 안전벨트는 두 개만 작동한다.","sense":"넷"},{"wordId":16027,"answer":"four","form":"원형","example":"She scheduled four separate meetings for Thursday afternoon before the deadline.","exampleTranslation":"그녀는 마감일 전 목요일 오후에 네 건의 별도 회의를 잡았다.","sense":"넷"},{"wordId":16028,"answer":"Friday","form":"원형","example":"The final rehearsal is scheduled for Friday night before the show.","exampleTranslation":"마지막 리허설은 공연 전날인 금요일 밤으로 잡혀 있다.","sense":"금요일"},{"wordId":16029,"answer":"annoyed","form":"과거분사","example":"Annoyed by the constant noise, my neighbor finally complained to the landlord.","exampleTranslation":"끊임없는 소음에 짜증이 난 이웃 사람은 결국 집주인에게 항의했다.","sense":"짜증나게하다"},{"wordId":16029,"answer":"will annoy","form":"미래","example":"That squeaky door hinge will annoy every visitor until someone finally oils it.","exampleTranslation":"그 삐걱거리는 문 경첩은 누군가 기름칠하기 전까지 모든 방문객을 짜증나게 할 것이다.","sense":"짜증나게하다"},{"wordId":16030,"answer":"apples","form":"복수형","example":"She picked three ripe apples from the tree in the backyard.","exampleTranslation":"그녀는 뒤뜰에 있는 나무에서 잘 익은 사과 세 개를 땄다.","sense":"사과","alts":["apologies"]},{"wordId":16031,"answer":"April","form":"원형","example":"Her birthday always falls during the first week of April.","exampleTranslation":"그녀의 생일은 항상 4월 첫째 주에 있다.","sense":"4월"},{"wordId":16032,"answer":"asleep","form":"원형","example":"Exhausted from the long hike, the campers were asleep within minutes of lying down.","exampleTranslation":"긴 등산으로 지친 캠핑객들은 눕자마자 몇 분 만에 잠들었다.","sense":"잠든"},{"wordId":16032,"answer":"asleep","form":"원형","example":"He was so exhausted that he stayed asleep through the entire thunderstorm last night.","exampleTranslation":"그는 너무 지쳐서 어젯밤 천둥 폭풍이 치는 내내 잠들어 있었다.","sense":"잠든"},{"wordId":16033,"answer":"August","form":"원형","example":"Most factories in this town close for repairs during August.","exampleTranslation":"이 마을의 대부분 공장은 8월 동안 수리를 위해 문을 닫는다.","sense":"8월"},{"wordId":16034,"answer":"automatic","form":"원형","example":"The new dishwasher includes an automatic setting that adjusts water temperature by itself.","exampleTranslation":"그 새 식기세척기에는 스스로 수온을 조절하는 자동 설정 기능이 있다.","sense":"자동의"},{"wordId":16034,"answer":"automatically","form":"부사형","example":"The porch light turns on automatically whenever someone walks up the driveway.","exampleTranslation":"누군가 진입로를 걸어오면 현관 등이 자동으로 켜진다.","sense":"자동의"},{"wordId":16035,"answer":"more awake","form":"비교급","example":"A short walk outside made her feel more awake than another cup of coffee.","exampleTranslation":"밖에서 잠깐 걸었더니 커피 한 잔을 더 마신 것보다 그녀는 더 정신이 맑아졌다.","sense":"깨어 있는"},{"wordId":16035,"answer":"awake","form":"원형","example":"He stayed awake reading a mystery novel long after everyone else had gone to bed.","exampleTranslation":"그는 다른 사람들이 모두 잠자리에 든 뒤에도 오랫동안 추리소설을 읽으며 깨어 있었다.","sense":"깨어 있는"},{"wordId":16036,"answer":"more awkward","form":"비교급","example":"Her hands shook nervously, making the introduction feel more awkward than she had planned.","exampleTranslation":"그녀의 손이 긴장으로 떨려서 그 소개가 계획했던 것보다 더 어색하게 느껴졌다.","sense":"어색한"},{"wordId":16036,"answer":"awkwardly","form":"부사형","example":"He awkwardly waved back after realizing the stranger was greeting someone behind him.","exampleTranslation":"그는 낯선 사람이 자기 뒤에 있는 누군가에게 인사한 것을 깨닫고 어색하게 손을 흔들었다.","sense":"어색한"},{"wordId":16037,"answer":"bacon","form":"원형","example":"He fried crispy bacon for breakfast and shared it with his roommate.","exampleTranslation":"그는 아침 식사로 바삭한 베이컨을 튀겨 룸메이트와 나눠 먹었다.","sense":"베이컨"},{"wordId":16038,"answer":"fright","form":"원형","example":"The masked stranger gave the little boy quite a fright.","exampleTranslation":"그 가면을 쓴 낯선 사람은 그 어린 소년을 몹시 놀라게 했다.","sense":"놀람"},{"wordId":16039,"answer":"grandfathers","form":"복수형","example":"Both grandfathers attended the wedding and gave heartfelt toasts.","exampleTranslation":"양쪽 할아버지 모두 결혼식에 참석해 진심 어린 축사를 했다.","sense":"할아버지"},{"wordId":16040,"answer":"here","form":"원형","example":"The tour guide asked everyone to gather here before noon.","exampleTranslation":"여행 가이드는 모두에게 정오 전에 여기에 모이라고 요청했다.","sense":"여기에"},{"wordId":16043,"answer":"how","form":"원형","example":"The manual does not explain how to reset the password.","exampleTranslation":"그 설명서는 비밀번호를 어떻게 재설정하는지 설명하지 않는다.","sense":"어떻게"},{"wordId":16044,"answer":"hundred","form":"원형","example":"More than a hundred volunteers showed up to help clean the beach on Saturday.","exampleTranslation":"토요일에 백 명이 넘는 자원봉사자가 해변 청소를 도우러 나왔다.","sense":"백"},{"wordId":16044,"answer":"hundred","form":"원형","example":"This antique clock has kept perfect time for nearly a hundred winters, the owner proudly claims.","exampleTranslation":"이 골동품 시계는 거의 백 번의 겨울을 거치며 정확한 시간을 지켜 왔다고 주인은 자랑스럽게 말한다.","sense":"백"},{"wordId":16047,"answer":"lords","form":"복수형","example":"Several lords gathered at the castle to discuss the kingdom's defense.","exampleTranslation":"여러 영주가 왕국의 방어를 논의하려고 성에 모였다.","sense":"영주"},{"wordId":16048,"answer":"aborted","form":"과거형","example":"Due to strong winds, the pilot aborted the landing at the last moment.","exampleTranslation":"강풍 때문에 그 조종사는 마지막 순간에 착륙을 중단했다.","sense":"중단하다"},{"wordId":16048,"answer":"has aborted","form":"현재완료","example":"Ground control says the rocket has aborted its launch sequence twice already.","exampleTranslation":"지상 관제소는 그 로켓이 벌써 두 번이나 발사 절차를 중단했다고 말한다.","sense":"중지하다","alts":["has ceased"]},{"wordId":16049,"answer":"absorbed","form":"과거분사","example":"Absorbed quickly by the dry soil, the rainwater left no puddles behind.","exampleTranslation":"건조한 흙에 빠르게 흡수된 빗물은 웅덩이를 전혀 남기지 않았다.","sense":"흡수하다"},{"wordId":16049,"answer":"will absorb","form":"미래","example":"Scientists explain the new fabric will absorb sweat far better than cotton.","exampleTranslation":"과학자들은 그 새 원단이 면보다 땀을 훨씬 더 잘 흡수할 것이라고 설명한다.","sense":"흡수하다"},{"wordId":16050,"answer":"bananas","form":"복수형","example":"He packed two bananas for a quick snack during the hike.","exampleTranslation":"그는 하이킹 중 간단한 간식으로 바나나 두 개를 챙겼다.","sense":"바나나"},{"wordId":16051,"answer":"bangs","form":"3인칭 단수형","example":"Whenever he leaves in a hurry, my brother always bangs the front door.","exampleTranslation":"형은 서둘러 나갈 때마다 항상 현관문을 쾅 닫는다.","sense":"쾅닫다"},{"wordId":16051,"answer":"is banging","form":"현재진행","example":"Someone is banging loudly on our apartment wall in the middle of the night.","exampleTranslation":"누군가 한밤중에 우리 아파트 벽을 시끄럽게 쾅쾅 두드리고 있다.","sense":"쾅쾅두드리다"},{"wordId":16052,"answer":"barest","form":"최상급","example":"Of all the rooms in the empty house, the attic looked the barest and coldest.","exampleTranslation":"그 빈집의 모든 방 중에서 다락방이 가장 휑하고 추워 보였다.","sense":"텅 빈"},{"wordId":16052,"answer":"bare","form":"원형","example":"The dancer's bare feet left faint prints across the polished wooden stage floor.","exampleTranslation":"그 무용수의 맨발은 광이 나는 나무 무대 바닥에 희미한 발자국을 남겼다.","sense":"맨~의"},{"wordId":16053,"answer":"barked","form":"과거분사","example":"Barked at by an aggressive dog, the mail carrier refused to approach that house again.","exampleTranslation":"사나운 개가 짖어대자 그 우편배달부는 다시는 그 집에 가까이 가지 않으려 했다.","sense":"짖다"},{"wordId":16053,"answer":"will bark","form":"미래","example":"That guard dog will bark loudly the moment a stranger steps onto the property.","exampleTranslation":"그 경비견은 낯선 사람이 부지에 발을 들이는 순간 크게 짖을 것이다.","sense":"짖다"},{"wordId":16054,"answer":"baskets","form":"복수형","example":"She wove three baskets from dried reeds to sell at the market.","exampleTranslation":"그녀는 시장에서 팔려고 마른 갈대로 바구니 세 개를 엮었다.","sense":"바구니"},{"wordId":16055,"answer":"bats","form":"3인칭 단수형","example":"In every single game, that confident rookie bats left-handed against right-handers.","exampleTranslation":"모든 경기에서 그 자신만만한 신인 선수는 우완 투수를 상대로 왼손으로 타격한다.","sense":"타격하다"},{"wordId":16055,"answer":"is batting","form":"현재진행","example":"This inning, the team's star player is batting against the opposing pitcher.","exampleTranslation":"이번 이닝에 그 팀의 스타 선수가 상대 투수를 상대로 타격하고 있다.","sense":"타격하다"},{"wordId":16056,"answer":"batteries","form":"복수형","example":"The remote control needs two fresh batteries to work properly.","exampleTranslation":"그 리모컨은 제대로 작동하려면 새 건전지 두 개가 필요하다.","sense":"건전지"},{"wordId":16057,"answer":"bays","form":"복수형","example":"Sailors mapped several quiet bays along the rugged northern coast.","exampleTranslation":"선원들은 험준한 북쪽 해안을 따라 조용한 만 여러 곳을 지도로 그렸다.","sense":"만(바다)","alts":["gulfs"]},{"wordId":16058,"answer":"beans","form":"복수형","example":"She soaked two cups of dried beans overnight before cooking.","exampleTranslation":"그녀는 요리하기 전 마른 콩 두 컵을 밤새 물에 불렸다.","sense":"콩"},{"wordId":16059,"answer":"bees","form":"복수형","example":"Several bees buzzed busily around the blooming lavender bushes.","exampleTranslation":"벌 여러 마리가 활짝 핀 라벤더 덤불 주위를 바쁘게 윙윙거렸다.","sense":"벌"},{"wordId":16060,"answer":"beef","form":"원형","example":"The chef slow-cooked the beef for six hours until it turned tender.","exampleTranslation":"그 요리사는 소고기가 부드러워질 때까지 여섯 시간 동안 천천히 익혔다.","sense":"소고기"},{"wordId":16061,"answer":"begging","form":"-ing형","example":"Begging for forgiveness, the young apprentice promised never to repeat his mistake.","exampleTranslation":"용서를 간청하며 그 젊은 견습생은 실수를 절대 반복하지 않겠다고 약속했다.","sense":"간청하다"},{"wordId":16061,"answer":"will beg","form":"미래","example":"If the puppy stays hungry, it will beg for scraps at the table.","exampleTranslation":"강아지가 계속 배고프면 식탁에서 음식 부스러기를 달라고 조를 것이다.","sense":"조르다"},{"wordId":16062,"answer":"biscuits","form":"복수형","example":"She baked a dozen biscuits and shared them with her neighbors.","exampleTranslation":"그녀는 비스킷 열두 개를 구워 이웃들과 나눠 먹었다.","sense":"비스킷"},{"wordId":16063,"answer":"blankest","form":"최상급","example":"Of everyone in the quiz, he had the blankest expression when asked the final question.","exampleTranslation":"그 퀴즈에 참가한 사람들 중 마지막 질문을 받았을 때 그는 가장 멍한 표정을 지었다.","sense":"멍한"},{"wordId":16063,"answer":"blankness","form":"명사형","example":"The blankness of the empty page made her feel both nervous and hopeful.","exampleTranslation":"빈 페이지의 백지 상태는 그녀를 불안하면서도 희망차게 만들었다.","sense":"빈"},{"wordId":16064,"answer":"millions","form":"복수형","example":"Millions of fans watched the final match live on television.","exampleTranslation":"수백만 명의 팬이 결승전을 텔레비전으로 생중계 시청했다.","sense":"백만"},{"wordId":16066,"answer":"mister","form":"원형","example":"The new kids at school always called him mister out of respect.","exampleTranslation":"학교의 새로 온 아이들은 존경의 뜻으로 항상 그를 '씨'라고 불렀다.","sense":"씨"},{"wordId":16067,"answer":"Monday","form":"원형","example":"The office usually feels quiet right after lunch on Monday.","exampleTranslation":"사무실은 보통 월요일 점심 직후에 조용한 편이다.","sense":"월요일"},{"wordId":16069,"answer":"most","form":"최상급","example":"Winning the small lottery gave her family the most money they had ever had.","exampleTranslation":"작은 복권에 당첨된 것은 그녀의 가족에게 그들이 가져 본 것 중 가장 많은 돈을 안겨 주었다.","sense":"많은"},{"wordId":16069,"answer":"much","form":"원형","example":"There was not much traffic on the highway this early on a Sunday.","exampleTranslation":"일요일 이른 시간이라 고속도로에는 차가 많지 않았다.","sense":"많은"},{"wordId":16071,"answer":"academies","form":"복수형","example":"The city has opened three new academies to train young athletes.","exampleTranslation":"그 도시는 어린 운동선수들을 훈련시키려고 새 아카데미 세 곳을 열었다.","sense":"아카데미"},{"wordId":16072,"answer":"accelerated","form":"과거형","example":"Approaching the highway ramp, the driver accelerated smoothly to match traffic speed.","exampleTranslation":"고속도로 진입로에 다가가며 그 운전자는 교통 속도에 맞춰 부드럽게 가속했다.","sense":"가속하다"},{"wordId":16072,"answer":"has accelerated","form":"현재완료","example":"Inflation has accelerated sharply since the sudden rise in oil prices.","exampleTranslation":"유가가 갑자기 오른 이후로 물가 상승이 급격히 가속화되었다.","sense":"가속화되다"},{"wordId":16073,"answer":"most accountable","form":"최상급","example":"Among all the managers, she felt the most accountable for the project's failure.","exampleTranslation":"모든 관리자 중에서 그녀는 그 프로젝트 실패에 대해 가장 책임이 있다고 느꼈다.","sense":"책임이 있는"},{"wordId":16073,"answer":"accountability","form":"명사형","example":"The new policy increases accountability by requiring monthly progress reports from every team.","exampleTranslation":"그 새 정책은 모든 팀에 월간 진행 보고서를 요구함으로써 책임성을 높인다.","sense":"책임이 있는","alts":["liability"]},{"wordId":16074,"answer":"accumulating","form":"-ing형","example":"Accumulating slowly over many years, his coin collection eventually filled three large cabinets.","exampleTranslation":"수년에 걸쳐 서서히 쌓이면서 그의 동전 수집품은 결국 큰 캐비닛 세 개를 채웠다.","sense":"쌓이다"},{"wordId":16074,"answer":"was accumulated","form":"수동태","example":"Considerable debt was accumulated during the company's difficult first three years.","exampleTranslation":"그 회사의 힘든 처음 삼 년 동안 상당한 부채가 쌓였다.","sense":"쌓이다"},{"wordId":16075,"answer":"aches","form":"3인칭 단수형","example":"After every long run, my knee aches painfully for the rest of the day.","exampleTranslation":"긴 달리기를 할 때마다 내 무릎은 남은 하루 종일 아프게 쑤신다.","sense":"쑤시다"},{"wordId":16075,"answer":"is aching","form":"현재진행","example":"Since yesterday's move, my whole back is aching from lifting heavy boxes.","exampleTranslation":"어제 이사를 한 이후로 무거운 상자를 들어서 내 등 전체가 쑤시고 있다.","sense":"쑤시다"},{"wordId":16076,"answer":"blanketed","form":"과거형","example":"Overnight, three inches of fresh snow blanketed the entire quiet town.","exampleTranslation":"밤사이 삼 인치의 새 눈이 그 조용한 마을 전체를 뒤덮었다.","sense":"뒤덮다"},{"wordId":16076,"answer":"has blanketed","form":"현재완료","example":"Thick fog has blanketed the coastal highway since early this morning.","exampleTranslation":"짙은 안개가 오늘 이른 아침부터 해안 고속도로를 뒤덮어 왔다.","sense":"뒤덮다"},{"wordId":16077,"answer":"bleeding","form":"-ing형","example":"Bleeding slightly from a small cut, the boy ran straight to his mother.","exampleTranslation":"작은 상처에서 약간 피를 흘리며 그 소년은 곧장 어머니에게 달려갔다.","sense":"피흘리다"},{"wordId":16077,"answer":"will bleed","form":"미래","example":"The nurse warned the wound will bleed again if he removes the bandage.","exampleTranslation":"간호사는 그가 붕대를 제거하면 상처에서 다시 피가 날 것이라고 경고했다.","sense":"피나다"},{"wordId":16078,"answer":"blonde","form":"원형","example":"Under the bright stage lights, the singer's newly dyed blonde hair looked almost platinum.","exampleTranslation":"밝은 무대 조명 아래에서 그 가수의 새로 염색한 금발 머리는 거의 백금색처럼 보였다.","sense":"금발의"},{"wordId":16078,"answer":"blonde","form":"원형","example":"The photographer asked the blonde model to stand near the large window for better lighting.","exampleTranslation":"그 사진작가는 더 좋은 조명을 위해 그 금발 모델에게 큰 창문 근처에 서 달라고 부탁했다.","sense":"금발의"},{"wordId":16079,"answer":"blooms","form":"3인칭 단수형","example":"Every April, the cherry tree in our yard blooms with bright pink flowers.","exampleTranslation":"매년 사월마다 우리 마당의 벚나무는 밝은 분홍 꽃을 피운다.","sense":"꽃피우다"},{"wordId":16079,"answer":"is blooming","form":"현재진행","example":"This week, the entire orchard is blooming earlier than anyone had expected.","exampleTranslation":"이번 주 과수원 전체가 누구도 예상하지 못했을 만큼 일찍 꽃을 피우고 있다.","sense":"꽃피우다"},{"wordId":16080,"answer":"bounced","form":"과거형","example":"The basketball bounced twice before rolling slowly off the outdoor court.","exampleTranslation":"그 농구공은 두 번 튀어 오른 후 실외 코트 밖으로 천천히 굴러갔다.","sense":"튀다"},{"wordId":16080,"answer":"has bounced","form":"현재완료","example":"That check has bounced three times because of insufficient account funds.","exampleTranslation":"계좌 잔액 부족으로 그 수표는 세 번이나 부도가 났다.","sense":"부도나다"},{"wordId":16081,"answer":"bowing","form":"-ing형","example":"Bowing respectfully to the elders, the young performers began their traditional dance.","exampleTranslation":"어른들께 정중히 절하며 그 어린 공연자들은 전통 춤을 시작했다.","sense":"절하다"},{"wordId":16081,"answer":"will bow","form":"미래","example":"At the end of the concert, the pianist will bow to the enthusiastic audience.","exampleTranslation":"연주회가 끝나면 그 피아니스트는 열광하는 관객에게 인사할 것이다.","sense":"인사하다"},{"wordId":16082,"answer":"braking","form":"-ing형","example":"Braking suddenly, the cyclist barely avoided the dog that ran into the street.","exampleTranslation":"갑자기 브레이크를 밟으며 그 자전거 타는 사람은 도로로 뛰어든 개를 겨우 피했다.","sense":"브레이크밟다"},{"wordId":16082,"answer":"is braking","form":"현재진행","example":"On the icy road, the truck ahead is braking much too suddenly for comfort.","exampleTranslation":"빙판길에서 앞서 가던 트럭이 너무 갑자기 브레이크를 밟고 있어 불안하다.","sense":"브레이크밟다"},{"wordId":16083,"answer":"bravest","form":"최상급","example":"Everyone agreed that the firefighter who rescued the child was the bravest person in town.","exampleTranslation":"모든 사람이 그 아이를 구한 소방관이 그 마을에서 가장 용감한 사람이라는 데 동의했다.","sense":"용감한"},{"wordId":16083,"answer":"bravery","form":"명사형","example":"The soldier received a medal for his bravery during the dangerous rescue mission.","exampleTranslation":"그 군인은 위험한 구조 임무 중 보인 용감함으로 훈장을 받았다.","sense":"용감한"},{"wordId":16084,"answer":"bricks","form":"복수형","example":"Workers carefully stacked many red bricks near the construction site entrance.","exampleTranslation":"인부들은 공사 현장 입구 근처에 붉은 벽돌 여러 개를 조심스럽게 쌓았다.","sense":"벽돌"},{"wordId":16085,"answer":"bucking","form":"-ing형","example":"Bucking wildly, the frightened horse nearly threw its young, inexperienced rider.","exampleTranslation":"거칠게 날뛰며 그 겁먹은 말은 어리고 미숙한 기수를 거의 떨어뜨릴 뻔했다.","sense":"날뛰다"},{"wordId":16085,"answer":"will buck","form":"미래","example":"Trainers warn the untamed colt will buck whenever a stranger approaches too closely.","exampleTranslation":"조련사들은 그 길들여지지 않은 망아지가 낯선 사람이 너무 가까이 다가올 때마다 날뛸 것이라고 경고한다.","sense":"날뛰다"},{"wordId":16086,"answer":"buckets","form":"복수형","example":"He filled two buckets with water to wash the muddy car.","exampleTranslation":"그는 진흙투성이 차를 닦으려고 양동이 두 개에 물을 채웠다.","sense":"양동이"},{"wordId":16087,"answer":"bumps","form":"3인칭 단수형","example":"In the crowded hallway, someone always bumps my shoulder without even apologizing.","exampleTranslation":"붐비는 복도에서 누군가는 항상 사과도 없이 내 어깨에 부딪힌다.","sense":"부딪히다"},{"wordId":16087,"answer":"is bumping","form":"현재진행","example":"This afternoon, the toddler is bumping into every piece of living room furniture.","exampleTranslation":"오늘 오후 그 아기는 거실 가구마다 계속 부딪히고 있다.","sense":"부딪히다"},{"wordId":16088,"answer":"butter","form":"원형","example":"She melted a spoonful of butter before adding the fresh garlic.","exampleTranslation":"그녀는 신선한 마늘을 넣기 전 버터 한 스푼을 녹였다.","sense":"버터"},{"wordId":16089,"answer":"cages","form":"복수형","example":"The zoo built two larger cages for the growing lion cubs.","exampleTranslation":"그 동물원은 자라나는 새끼 사자들을 위해 더 큰 우리 두 개를 지었다.","sense":"우리"},{"wordId":16091,"answer":"naughtiest","form":"최상급","example":"Out of all the puppies in the litter, the smallest one was clearly the naughtiest.","exampleTranslation":"그 강아지들 중에서 가장 작은 강아지가 확실히 가장 말썽꾸러기였다.","sense":"장난꾸러기인"},{"wordId":16091,"answer":"naughtiness","form":"명사형","example":"The teacher blamed his naughtiness on too much sugar during the birthday party.","exampleTranslation":"선생님은 생일 파티에서 설탕을 너무 많이 먹은 탓에 그가 말썽을 부린다고 여겼다.","sense":"장난꾸러기인"},{"wordId":16092,"answer":"neater","form":"비교급","example":"After the cleaning service visited, the office looked much neater than before.","exampleTranslation":"청소 업체가 다녀간 뒤 사무실은 전보다 훨씬 더 깔끔해 보였다.","sense":"깔끔한"},{"wordId":16092,"answer":"neatly","form":"부사형","example":"She folded each shirt neatly before placing it into the suitcase.","exampleTranslation":"그녀는 여행 가방에 넣기 전에 셔츠 하나하나를 깔끔하게 접었다.","sense":"깔끔한"},{"wordId":16093,"answer":"never","form":"원형","example":"The captain vowed his crew would never abandon the ship.","exampleTranslation":"선장은 자신의 선원들이 결코 배를 버리지 않을 것이라고 맹세했다.","sense":"결코"},{"wordId":16094,"answer":"nine","form":"원형","example":"The marathon route passes nine different neighborhoods before reaching the finish line.","exampleTranslation":"그 마라톤 코스는 결승선에 도착하기 전에 아홉 개의 다른 동네를 지난다.","sense":"아홉"},{"wordId":16094,"answer":"nine","form":"원형","example":"Grandma's cat is already nine years old but still chases mice around the yard.","exampleTranslation":"할머니의 고양이는 벌써 아홉 살이지만 여전히 마당에서 쥐를 쫓아다닌다.","sense":"아홉"},{"wordId":16095,"answer":"acres","form":"복수형","example":"The family owns nearly two hundred acres of farmland in the valley.","exampleTranslation":"그 가족은 계곡에 거의 200에이커의 농지를 소유하고 있다.","sense":"에이커"},{"wordId":16096,"answer":"addicts","form":"복수형","example":"The clinic helps several addicts recover through counseling and support groups.","exampleTranslation":"그 병원은 상담과 지원 모임을 통해 여러 중독자의 회복을 돕는다.","sense":"중독자"},{"wordId":16097,"answer":"administrative","form":"원형","example":"Coordinating volunteer schedules and event permits became her main administrative responsibility.","exampleTranslation":"자원봉사자 일정과 행사 허가를 조율하는 것은 그녀의 주된 행정 업무가 되었다.","sense":"행정의"},{"wordId":16097,"answer":"administration","form":"명사형","example":"The new administration promised to simplify the tax filing process for small businesses.","exampleTranslation":"새 행정부는 소상공인을 위한 세금 신고 절차를 간소화하겠다고 약속했다.","sense":"행정의"},{"wordId":16098,"answer":"administrators","form":"복수형","example":"The university hired two administrators to oversee student housing.","exampleTranslation":"그 대학교는 학생 기숙사를 관리할 행정관 두 명을 채용했다.","sense":"관리자","alts":["managers"]},{"wordId":16099,"answer":"admission","form":"원형","example":"Most local theaters offer discounted admission for students on weekdays.","exampleTranslation":"대부분의 지역 극장은 평일에 학생 할인 입장료를 제공한다.","sense":"입장"},{"wordId":16100,"answer":"adolescent","form":"원형","example":"Adolescent behavior can shift quickly, surprising even the most patient parents.","exampleTranslation":"청소년기의 행동은 빠르게 바뀔 수 있어 가장 인내심 많은 부모조차 놀라게 한다.","sense":"청소년의"},{"wordId":16100,"answer":"adolescence","form":"명사형","example":"Doctors say adolescence brings rapid changes in both the body and the brain.","exampleTranslation":"의사들은 사춘기가 신체와 뇌 모두에 급격한 변화를 가져온다고 말한다.","sense":"청소년의"},{"wordId":16101,"answer":"affection","form":"원형","example":"The puppy showed endless affection by licking everyone who walked in.","exampleTranslation":"그 강아지는 들어오는 모든 사람을 핥으며 끝없는 애정을 보였다.","sense":"애정"},{"wordId":16102,"answer":"canoeing","form":"-ing형","example":"Canoeing quietly along the river, the two friends spotted a family of deer.","exampleTranslation":"강을 따라 조용히 카누를 타며 그 두 친구는 사슴 가족을 발견했다.","sense":"카누타다"},{"wordId":16102,"answer":"is canoeing","form":"현재진행","example":"This weekend, my uncle is canoeing across the lake with his old fishing gear.","exampleTranslation":"이번 주말 삼촌은 오래된 낚시 도구를 가지고 호수를 가로질러 카누를 타고 있다.","sense":"카누타다"},{"wordId":16103,"answer":"capes","form":"복수형","example":"The costume shop sold several colorful capes for the comic convention.","exampleTranslation":"그 코스튬 가게는 코믹 컨벤션을 위해 화려한 망토 여러 벌을 팔았다.","sense":"케이프","alts":["cloaks"]},{"wordId":16104,"answer":"captained","form":"과거형","example":"In her final season, she captained the national team to an unexpected victory.","exampleTranslation":"마지막 시즌에 그녀는 국가대표팀을 이끌어 예상치 못한 승리를 거두었다.","sense":"주장을 맡다","alts":["led"]},{"wordId":16104,"answer":"has captained","form":"현재완료","example":"That veteran player has captained the club for nearly eight consecutive seasons.","exampleTranslation":"그 베테랑 선수는 거의 여덟 시즌 연속으로 그 클럽의 주장을 맡아 왔다.","sense":"주장을맡다"},{"wordId":16105,"answer":"carrots","form":"복수형","example":"She chopped three carrots for the vegetable soup simmering on the stove.","exampleTranslation":"그녀는 가스레인지에서 끓고 있는 채소 수프를 위해 당근 세 개를 썰었다.","sense":"당근"},{"wordId":16106,"answer":"carting","form":"-ing형","example":"Carting heavy equipment up the stairs, the movers finally reached the top floor.","exampleTranslation":"무거운 장비를 계단 위로 실어 나르며 그 이삿짐 인부들은 마침내 꼭대기 층에 도착했다.","sense":"실어나르다"},{"wordId":16106,"answer":"was carted","form":"수동태","example":"The broken furniture was carted away by a recycling truck yesterday.","exampleTranslation":"그 고장 난 가구는 어제 재활용 트럭에 의해 실려 나갔다.","sense":"실어나르다"},{"wordId":16107,"answer":"most casual","form":"최상급","example":"Compared to her previous jobs, this new office had by far the most casual dress code.","exampleTranslation":"이전 직장들과 비교했을 때 이 새 사무실은 단연 가장 격식 없는 복장 규정을 가지고 있었다.","sense":"격식 없는"},{"wordId":16107,"answer":"casually","form":"부사형","example":"He casually mentioned that he had already found a new apartment downtown.","exampleTranslation":"그는 이미 시내에 새 아파트를 구했다고 아무렇지 않게 말했다.","sense":"격식 없는"},{"wordId":16108,"answer":"ceilings","form":"복수형","example":"The old theater has unusually high ceilings that echo every sound.","exampleTranslation":"그 오래된 극장은 유난히 높은 천장이 있어 모든 소리가 울린다.","sense":"천장"},{"wordId":16109,"answer":"centimeters","form":"복수형","example":"The tailor measured the fabric to within two centimeters of accuracy.","exampleTranslation":"그 재단사는 오차 2센티미터 이내로 원단을 측정했다.","sense":"센티미터"},{"wordId":16110,"answer":"cheating","form":"-ing형","example":"Cheating on the final exam, the student was caught immediately by the professor.","exampleTranslation":"기말고사에서 부정행위를 하다가 그 학생은 교수에게 즉시 들켰다.","sense":"부정행위하다"},{"wordId":16110,"answer":"was cheated","form":"수동태","example":"He felt he was cheated out of his rightful prize money by the judges.","exampleTranslation":"그는 심사위원들에게 정당한 상금을 부당하게 빼앗겼다고 느꼈다.","sense":"빼앗기다"},{"wordId":16111,"answer":"cheers","form":"3인칭 단수형","example":"Whenever the home team scores, the entire stadium cheers loudly together.","exampleTranslation":"홈팀이 득점할 때마다 경기장 전체가 다 함께 큰 소리로 환호한다.","sense":"환호하다"},{"wordId":16111,"answer":"is cheering","form":"현재진행","example":"During the final lap, the crowd is cheering wildly for the exhausted runners.","exampleTranslation":"마지막 바퀴를 도는 동안 관중은 지친 주자들을 위해 열광적으로 환호하고 있다.","sense":"환호하다"},{"wordId":16112,"answer":"chewed","form":"과거형","example":"Distracted by the movie, my brother chewed his sandwich very slowly.","exampleTranslation":"영화에 정신이 팔린 형은 샌드위치를 아주 천천히 씹었다.","sense":"씹다"},{"wordId":16112,"answer":"has chewed","form":"현재완료","example":"That stubborn puppy has chewed every single shoe in the front closet.","exampleTranslation":"그 고집 센 강아지는 현관 옷장 안의 신발을 하나도 빠짐없이 씹어 놓았다.","sense":"씹다"},{"wordId":16113,"answer":"chopped","form":"과거분사","example":"Chopped finely, the fresh herbs added a bright flavor to the soup.","exampleTranslation":"곱게 다진 그 신선한 허브는 수프에 산뜻한 풍미를 더해 주었다.","sense":"다지다"},{"wordId":16113,"answer":"will chop","form":"미래","example":"The recipe says the chef will chop the vegetables into small even cubes.","exampleTranslation":"그 요리법에는 요리사가 채소를 작고 고른 정육면체로 썰 것이라고 나와 있다.","sense":"썰다"},{"wordId":16114,"answer":"cleverer","form":"비교급","example":"Her solution to the puzzle turned out to be far cleverer than anyone expected.","exampleTranslation":"그 퍼즐에 대한 그녀의 해법은 모두의 예상보다 훨씬 더 영리했다.","sense":"영리한","alts":["smarter"]},{"wordId":16114,"answer":"cleverness","form":"명사형","example":"The fox is often praised in folk tales for its cleverness and quick thinking.","exampleTranslation":"여우는 민담에서 흔히 영리함과 재빠른 판단력으로 칭찬받는다.","sense":"영리한"},{"wordId":16116,"answer":"other","form":"원형","example":"She always mixes up her left shoe with the other one before running out the door.","exampleTranslation":"그녀는 늘 집을 나서기 전에 왼쪽 신발과 다른 한 짝을 헷갈린다.","sense":"다른"},{"wordId":16116,"answer":"other","form":"원형","example":"We visited three other cities before finally settling in the small coastal town.","exampleTranslation":"우리는 마침내 그 작은 해안 마을에 정착하기 전 다른 도시 세 곳을 방문했다.","sense":"다른"},{"wordId":16117,"answer":"ought","form":"원형","example":"Every honest employee ought to report safety violations to management immediately.","exampleTranslation":"모든 정직한 직원은 안전 위반 사항을 즉시 경영진에게 보고해야 한다.","sense":"해야한다"},{"wordId":16117,"answer":"ought","form":"원형","example":"Before signing anything, you ought to read every single clause carefully.","exampleTranslation":"무언가에 서명하기 전에 모든 조항을 꼼꼼히 읽어야 한다.","sense":"해야한다"},{"wordId":16118,"answer":"pardoning","form":"-ing형","example":"Pardoning the minor offense, the judge gave the nervous teenager a second chance.","exampleTranslation":"그 사소한 위반을 용서하며 판사는 긴장한 십 대에게 두 번째 기회를 주었다.","sense":"용서하다"},{"wordId":16118,"answer":"was pardoned","form":"수동태","example":"The elderly prisoner was pardoned unexpectedly after serving only half his sentence.","exampleTranslation":"그 나이 든 수감자는 형기의 절반만 채우고 예상치 못하게 사면되었다.","sense":"사면되다"},{"wordId":16119,"answer":"pennies","form":"복수형","example":"He found three pennies scattered on the sidewalk near the bus stop.","exampleTranslation":"그는 버스 정류장 근처 보도에 흩어진 페니 세 개를 발견했다.","sense":"페니"},{"wordId":16120,"answer":"princes","form":"복수형","example":"The old tale describes two princes competing for their father's throne.","exampleTranslation":"그 옛이야기는 아버지의 왕좌를 두고 경쟁하는 왕자 두 명을 그린다.","sense":"왕자"},{"wordId":16121,"answer":"affirmed","form":"과거분사","example":"Affirmed by three separate witnesses, the timeline convinced even the skeptical jury.","exampleTranslation":"세 명의 별개 목격자에 의해 확인된 그 시간대는 회의적인 배심원단마저 설득했다.","sense":"확인하다"},{"wordId":16121,"answer":"will affirm","form":"미래","example":"The witness will affirm under oath that she saw the entire accident happen.","exampleTranslation":"그 목격자는 선서 아래 사고 전체를 목격했다고 확언할 것이다.","sense":"확언하다"},{"wordId":16122,"answer":"agriculture","form":"원형","example":"This valley's economy depends almost entirely on agriculture and tourism.","exampleTranslation":"이 계곡의 경제는 거의 전적으로 농업과 관광에 의존한다.","sense":"농업"},{"wordId":16123,"answer":"more alien","form":"비교급","example":"Every custom in the new country felt more alien to her than she had expected.","exampleTranslation":"새 나라의 모든 관습이 그녀가 예상했던 것보다 더 낯설게 느껴졌다.","sense":"낯선"},{"wordId":16123,"answer":"alienation","form":"명사형","example":"Long hours at the factory led to a deep sense of alienation among the workers.","exampleTranslation":"공장에서의 긴 근무 시간은 노동자들 사이에 깊은 소외감을 낳았다.","sense":"외계의"},{"wordId":16124,"answer":"alliances","form":"복수형","example":"The two small nations formed several alliances to resist the larger empire.","exampleTranslation":"그 두 작은 나라는 더 큰 제국에 맞서려고 여러 동맹을 맺었다.","sense":"동맹"},{"wordId":16125,"answer":"amended","form":"과거분사","example":"Amended quickly after public backlash, the confusing policy finally made much more sense.","exampleTranslation":"대중의 반발 이후 신속히 수정된 그 혼란스러운 정책은 마침내 훨씬 더 이치에 맞았다.","sense":"수정하다"},{"wordId":16125,"answer":"will amend","form":"미래","example":"Lawmakers say the committee will amend the outdated rule sometime next session.","exampleTranslation":"의원들은 위원회가 다음 회기 중 낡은 규칙을 개정할 것이라고 말한다.","sense":"개정하다"},{"wordId":16126,"answer":"approximate","form":"원형","example":"Without a proper ruler, she could only give an approximate measurement of the shelf's width.","exampleTranslation":"제대로 된 자가 없어서 그녀는 선반 너비를 대략적으로만 잴 수 있었다.","sense":"대략의"},{"wordId":16126,"answer":"approximately","form":"부사형","example":"The trip takes approximately three hours by car, depending on traffic conditions.","exampleTranslation":"그 여행은 교통 상황에 따라 차로 대략 세 시간 걸린다.","sense":"대략의"},{"wordId":16127,"answer":"cliffs","form":"복수형","example":"Seabirds nested along several steep cliffs overlooking the crashing waves.","exampleTranslation":"바닷새들은 부서지는 파도가 내려다보이는 가파른 절벽 여러 곳에 둥지를 틀었다.","sense":"절벽"},{"wordId":16128,"answer":"clipped","form":"과거형","example":"Carefully, the groomer clipped the dog's overgrown fur before the competition.","exampleTranslation":"미용사는 대회 전에 개의 웃자란 털을 조심스럽게 잘랐다.","sense":"다듬다","alts":["cut","trimmed"]},{"wordId":16128,"answer":"has clipped","form":"현재완료","example":"The gardener has clipped every hedge in the park this week.","exampleTranslation":"그 정원사는 이번 주 공원 안의 모든 산울타리를 다듬었다.","sense":"자르다","alts":["has trimmed"]},{"wordId":16129,"answer":"cloths","form":"복수형","example":"She kept several soft cloths under the sink for quick spills.","exampleTranslation":"그녀는 급히 생긴 흘림을 닦으려고 싱크대 아래 부드러운 천 여러 장을 두었다.","sense":"천"},{"wordId":16130,"answer":"cluing","form":"-ing형","example":"Cluing in the new intern, my colleague explained the entire filing system quickly.","exampleTranslation":"신입 인턴에게 알려 주며 내 동료는 전체 서류 정리 체계를 재빠르게 설명했다.","sense":"알려주다"},{"wordId":16130,"answer":"was clued","form":"수동태","example":"The rookie was clued in about the office's unwritten rules on his first day.","exampleTranslation":"그 신입 사원은 출근 첫날 사무실의 암묵적인 규칙에 대해 알게 되었다.","sense":"알게되다"},{"wordId":16131,"answer":"commerce","form":"원형","example":"The new bridge is expected to boost commerce between the two towns.","exampleTranslation":"그 새 다리는 두 마을 사이의 상업을 촉진할 것으로 기대된다.","sense":"상업"},{"wordId":16132,"answer":"more conscious","form":"비교급","example":"After the health scare, he became far more conscious of what he ate every day.","exampleTranslation":"그 건강 문제를 겪은 뒤 그는 매일 먹는 음식에 대해 훨씬 더 신경 쓰게 되었다.","sense":"의식하는"},{"wordId":16132,"answer":"consciousness","form":"명사형","example":"The patient slowly regained consciousness a few hours after the surgery ended.","exampleTranslation":"그 환자는 수술이 끝난 몇 시간 뒤 서서히 의식을 되찾았다.","sense":"의식이 있는"},{"wordId":16133,"answer":"cops","form":"복수형","example":"Two cops questioned the witnesses standing near the accident scene.","exampleTranslation":"경찰관 두 명이 사고 현장 근처에 서 있던 목격자들에게 질문했다.","sense":"경관","alts":["constables","officers"]},{"wordId":16134,"answer":"cottages","form":"복수형","example":"They rented two small cottages by the lake for the family reunion.","exampleTranslation":"그들은 가족 모임을 위해 호숫가의 작은 시골집 두 채를 빌렸다.","sense":"시골집"},{"wordId":16135,"answer":"cotton","form":"원형","example":"These sheets are woven from soft cotton grown on local farms.","exampleTranslation":"이 시트는 지역 농장에서 재배한 부드러운 면으로 짜여 있다.","sense":"면"},{"wordId":16136,"answer":"crawled","form":"과거형","example":"Under the low fence, the small dog crawled quickly to reach its owner.","exampleTranslation":"낮은 울타리 아래로 그 작은 개는 주인에게 닿기 위해 재빨리 기어갔다.","sense":"기어가다"},{"wordId":16136,"answer":"has crawled","form":"현재완료","example":"The determined toddler has crawled across the entire living room twice today.","exampleTranslation":"그 의지 넘치는 아기는 오늘 거실 전체를 두 번이나 기어서 가로질렀다.","sense":"기어가다"},{"wordId":16137,"answer":"creeping","form":"-ing형","example":"Creeping quietly past the sleeping guard, the thief reached the vault unseen.","exampleTranslation":"잠든 경비원을 조용히 지나쳐 살금살금 걸어서 그 도둑은 들키지 않고 금고에 도착했다.","sense":"살금살금걷다"},{"wordId":16137,"answer":"will creep","form":"미래","example":"Meteorologists warn cold air will creep into the region by early tomorrow.","exampleTranslation":"기상학자들은 내일 이른 시간까지 찬 공기가 그 지역으로 서서히 밀려들 것이라고 경고한다.","sense":"서서히밀려들다"},{"wordId":16138,"answer":"crowning","form":"-ing형","example":"Crowning the young princess, the archbishop declared the ceremony officially complete.","exampleTranslation":"어린 공주에게 왕관을 씌우며 대주교는 그 의식이 공식적으로 끝났다고 선언했다.","sense":"왕관씌우다"},{"wordId":16138,"answer":"was crowned","form":"수동태","example":"The tournament winner was crowned champion in front of thousands of fans.","exampleTranslation":"그 대회 우승자는 수천 명의 팬들 앞에서 챔피언으로 등극했다.","sense":"등극하다"},{"wordId":16139,"answer":"cruelest","form":"최상급","example":"Locking a pet outside in freezing weather is one of the cruelest things to do.","exampleTranslation":"반려동물을 얼어붙는 날씨에 밖에 두는 것은 가장 잔인한 행동 중 하나다.","sense":"잔인한","alts":["most savage","most vicious"]},{"wordId":16139,"answer":"cruelty","form":"명사형","example":"The new law was designed to prevent cruelty toward farm animals across the country.","exampleTranslation":"그 새 법률은 전국의 농장 동물에 대한 잔혹 행위를 막기 위해 만들어졌다.","sense":"잔인한","alts":["viciousness"]},{"wordId":16140,"answer":"queens","form":"복수형","example":"The exhibit compared how several queens ruled during the same century.","exampleTranslation":"그 전시는 같은 세기 동안 여러 여왕이 어떻게 다스렸는지 비교했다.","sense":"여왕"},{"wordId":16141,"answer":"rabbits","form":"복수형","example":"Two wild rabbits hopped across the garden early this morning.","exampleTranslation":"오늘 아침 일찍 야생 토끼 두 마리가 정원을 가로질러 뛰어다녔다.","sense":"토끼","alts":["bunnies"]},{"wordId":16142,"answer":"rubbishing","form":"-ing형","example":"Rubbishing every proposal without offering alternatives, the critic frustrated the whole committee.","exampleTranslation":"대안도 제시하지 않은 채 모든 제안을 혹평하며 그 평론가는 위원회 전체를 답답하게 만들었다.","sense":"혹평하다"},{"wordId":16142,"answer":"was rubbished","form":"수동태","example":"His entire business plan was rubbished by every single investor in the room.","exampleTranslation":"그의 사업 계획 전체는 그 자리에 있던 모든 투자자에게 혹평받았다.","sense":"혹평받다"},{"wordId":16143,"answer":"Saturday","form":"원형","example":"The farmers market only opens early on Saturday mornings.","exampleTranslation":"그 농산물 직거래 장터는 토요일 아침에만 일찍 문을 연다.","sense":"토요일"},{"wordId":16144,"answer":"seven","form":"원형","example":"The recipe says to bake the bread for seven minutes longer than usual.","exampleTranslation":"그 조리법은 빵을 평소보다 칠 분 더 오래 구우라고 되어 있다.","sense":"일곱"},{"wordId":16144,"answer":"seven","form":"원형","example":"Their new puppy already knows seven basic commands after just two weeks of training.","exampleTranslation":"그들의 새 강아지는 단 이 주간의 훈련만으로 이미 일곱 가지 기본 명령을 안다.","sense":"일곱"},{"wordId":16145,"answer":"archaeology","form":"원형","example":"She became fascinated with archaeology after visiting ancient ruins in Greece.","exampleTranslation":"그녀는 그리스의 고대 유적을 방문한 뒤 고고학에 매료되었다.","sense":"고고학"},{"wordId":16146,"answer":"architecting","form":"-ing형","example":"Our new hire is architecting a cleaner system for the payment platform this quarter.","exampleTranslation":"우리 신입 사원은 이번 분기에 결제 플랫폼을 위한 더 깔끔한 시스템을 설계하고 있다.","sense":"설계하다"},{"wordId":16146,"answer":"was architected","form":"수동태","example":"The entire security system was architected by a small team last year.","exampleTranslation":"그 보안 시스템 전체는 지난해 작은 팀에 의해 설계되었다.","sense":"설계하다"},{"wordId":16147,"answer":"aspects","form":"복수형","example":"The report examined several aspects of the company's new policy.","exampleTranslation":"그 보고서는 회사의 새 정책이 지닌 여러 측면을 살펴보았다.","sense":"측면","alts":["flanks"]},{"wordId":16148,"answer":"assaulted","form":"과거형","example":"A stranger assaulted the shop owner outside his store last Friday night.","exampleTranslation":"낯선 사람이 지난 금요일 밤 가게 밖에서 주인을 공격했다.","sense":"공격하다","alts":["assailed"]},{"wordId":16148,"answer":"has assaulted","form":"현재완료","example":"The suspect has assaulted two security guards since he arrived at the station.","exampleTranslation":"그 용의자는 경찰서에 도착한 이후로 경비원 두 명을 공격했다.","sense":"공격하다","alts":["have assailed"]},{"wordId":16149,"answer":"assemblies","form":"복수형","example":"The school held two assemblies this month to announce new rules.","exampleTranslation":"그 학교는 새 규칙을 발표하려고 이번 달에 집회 두 번을 열었다.","sense":"집회"},{"wordId":16150,"answer":"asserting","form":"-ing형","example":"The young lawyer kept asserting her client's innocence throughout the entire trial.","exampleTranslation":"그 젊은 변호사는 재판 내내 의뢰인의 결백을 계속 주장했다.","sense":"주장하다","alts":["Insisting"]},{"wordId":16150,"answer":"was asserted","form":"수동태","example":"Her right to a fair hearing was asserted clearly by the committee chairperson.","exampleTranslation":"공정한 심리를 받을 그녀의 권리는 위원회 의장에 의해 분명히 주장되었다.","sense":"주장하다"},{"wordId":16151,"answer":"atoms","form":"복수형","example":"This molecule contains several hydrogen atoms bonded to a central carbon.","exampleTranslation":"이 분자는 중심 탄소에 결합된 여러 수소 원자를 포함하고 있다.","sense":"원자"},{"wordId":16152,"answer":"audited","form":"과거형","example":"An outside firm audited our accounts twice last year without any warning.","exampleTranslation":"외부 회사가 지난해 아무 예고 없이 우리 회계를 두 번 감사했다.","sense":"감사하다"},{"wordId":16152,"answer":"has audited","form":"현재완료","example":"The tax office has audited three local restaurants since the new year began.","exampleTranslation":"국세청은 새해가 시작된 이후로 지역 식당 세 곳을 감사했다.","sense":"감사하다"},{"wordId":16153,"answer":"authority","form":"원형","example":"The manager does not have the authority to approve such a large refund.","exampleTranslation":"그 관리자는 그렇게 큰 환불을 승인할 권한이 없다.","sense":"권한"},{"wordId":16154,"answer":"authorizing","form":"-ing형","example":"The board spent the whole meeting authorizing new budgets for each department.","exampleTranslation":"이사회는 회의 내내 각 부서를 위한 새 예산을 승인하는 데 시간을 보냈다.","sense":"승인하다"},{"wordId":16154,"answer":"was authorized","form":"수동태","example":"This kind of expense was authorized only after the director reviewed every receipt.","exampleTranslation":"이런 종류의 지출은 이사가 영수증을 모두 검토한 뒤에야 승인되었다.","sense":"승인하다"},{"wordId":16155,"answer":"bacteria","form":"복수형","example":"Under the microscope, several rod-shaped bacteria multiplied within a few hours.","exampleTranslation":"현미경 아래에서 막대 모양의 세균 여러 개체가 몇 시간 만에 증식했다.","sense":"세균"},{"wordId":16156,"answer":"beamed","form":"과거형","example":"My grandmother beamed with pride the moment she saw her new grandchild.","exampleTranslation":"우리 할머니는 새로 태어난 손주를 본 순간 자랑스러워 환하게 웃으셨다.","sense":"환하게 웃다"},{"wordId":16156,"answer":"has beamed","form":"현재완료","example":"The little girl has beamed at every visitor since she got her new bicycle.","exampleTranslation":"그 어린 소녀는 새 자전거를 받은 뒤로 방문객 모두에게 환하게 웃어 보였다.","sense":"환하게 웃다"},{"wordId":16157,"answer":"benched","form":"과거분사","example":"The benched striker watched the second half from the sideline in silence.","exampleTranslation":"출전하지 못하고 벤치에 앉은 공격수는 후반전을 조용히 사이드라인에서 지켜보았다.","sense":"출전시키지 않다"},{"wordId":16157,"answer":"will bench","form":"미래","example":"The new coach will bench two starters if practice attendance keeps dropping.","exampleTranslation":"새 감독은 연습 참석률이 계속 떨어지면 주전 두 명을 출전시키지 않을 것이다.","sense":"출전시키지 않다"},{"wordId":16158,"answer":"bibles","form":"복수형","example":"Runners consider these two guidebooks the bibles of marathon training.","exampleTranslation":"주자들은 이 안내서 두 권을 마라톤 훈련의 지침서로 여긴다.","sense":"지침서"},{"wordId":16159,"answer":"cures","form":"3인칭 단수형","example":"This new treatment usually cures the infection within about ten days.","exampleTranslation":"이 새로운 치료법은 보통 열흘 정도 안에 감염을 치료한다.","sense":"치료하다"},{"wordId":16159,"answer":"is curing","form":"현재진행","example":"At the moment, this experimental drug is curing patients faster than doctors expected.","exampleTranslation":"지금 이 실험적인 약은 의사들이 예상했던 것보다 더 빨리 환자들을 치료하고 있다.","sense":"고치다","alts":["is treating"]},{"wordId":16160,"answer":"curled","form":"과거형","example":"The hairdresser curled my sister's hair for nearly an hour before the wedding.","exampleTranslation":"미용사는 결혼식 전에 거의 한 시간 동안 언니의 머리를 곱슬거리게 만들었다.","sense":"곱슬거리게 하다"},{"wordId":16160,"answer":"has curled","form":"현재완료","example":"The humid summer air has curled my niece's hair into loose waves since breakfast.","exampleTranslation":"후덥지근한 여름 공기가 아침 식사 이후로 조카의 머리카락을 느슨한 웨이브로 곱슬거리게 만들었다.","sense":"곱슬거리게 하다"},{"wordId":16161,"answer":"dawns","form":"3인칭 단수형","example":"In this region, the day usually dawns much later during the winter months.","exampleTranslation":"이 지역에서는 겨울철에 하루가 보통 훨씬 늦게 밝는다.","sense":"날이 밝다"},{"wordId":16161,"answer":"will dawn","form":"미래","example":"The sky will dawn bright and clear tomorrow, according to the latest forecast.","exampleTranslation":"최신 예보에 따르면 내일은 하늘이 밝고 맑게 동틀 것이다.","sense":"날이 밝다"},{"wordId":16162,"answer":"December","form":"원형","example":"Sales usually spike right before December due to holiday shopping.","exampleTranslation":"매출은 연말 쇼핑 때문에 보통 12월 직전에 급증한다.","sense":"12월"},{"wordId":16163,"answer":"more decent","form":"비교급","example":"The second apartment they viewed felt far more decent than the first cramped studio.","exampleTranslation":"그들이 두 번째로 본 아파트는 첫 번째 좁은 원룸보다 훨씬 더 괜찮게 느껴졌다.","sense":"괜찮은"},{"wordId":16163,"answer":"decently","form":"부사형","example":"The company treats its part-time staff decently, offering fair pay and flexible hours.","exampleTranslation":"그 회사는 시간제 직원을 정당한 임금과 유연한 근무 시간으로 제대로 대우한다.","sense":"괜찮은"},{"wordId":16164,"answer":"decks","form":"복수형","example":"The cruise ship has three outdoor decks with swimming pools.","exampleTranslation":"그 크루즈선에는 수영장이 있는 야외 갑판 세 곳이 있다.","sense":"갑판"},{"wordId":16165,"answer":"decorated","form":"과거분사","example":"The decorated hall looked stunning under the soft golden lights that evening.","exampleTranslation":"그날 저녁 장식된 홀은 부드러운 황금빛 조명 아래 근사해 보였다.","sense":"장식하다"},{"wordId":16165,"answer":"will decorate","form":"미래","example":"Volunteers will decorate the community center for the holiday party next weekend.","exampleTranslation":"자원봉사자들은 다음 주말 명절 파티를 위해 지역 문화센터를 장식할 것이다.","sense":"장식하다"},{"wordId":16166,"answer":"most desperate","form":"최상급","example":"Standing in the unemployment line that morning, he seemed the most desperate person there.","exampleTranslation":"그날 아침 실업 급여 대기줄에 서 있던 사람들 중 그가 가장 절박해 보였다.","sense":"절박한"},{"wordId":16166,"answer":"desperately","form":"부사형","example":"He desperately searched every drawer for the missing house keys before the bus arrived.","exampleTranslation":"그는 버스가 도착하기 전 잃어버린 집 열쇠를 찾으려고 필사적으로 모든 서랍을 뒤졌다.","sense":"절박한"},{"wordId":16167,"answer":"dines","form":"3인칭 단수형","example":"My uncle usually dines alone at that small diner near the train station.","exampleTranslation":"우리 삼촌은 보통 기차역 근처의 작은 식당에서 혼자 식사한다.","sense":"식사하다"},{"wordId":16167,"answer":"is dining","form":"현재진행","example":"The mayor is dining with several local business owners downtown at the moment.","exampleTranslation":"지금 시장은 시내에서 여러 지역 사업가들과 식사를 하고 있다.","sense":"식사하다"},{"wordId":16168,"answer":"disgusted","form":"과거형","example":"The dirty kitchen disgusted every inspector who walked through the restaurant that day.","exampleTranslation":"그 지저분한 주방은 그날 식당을 둘러본 조사관 모두를 역겹게 했다.","sense":"역겹게 하다"},{"wordId":16168,"answer":"has disgusted","form":"현재완료","example":"His rude behavior has disgusted almost everyone in the office since he started.","exampleTranslation":"그의 무례한 행동은 그가 입사한 이후로 사무실 사람들 거의 모두를 역겹게 했다.","sense":"역겹게 하다"},{"wordId":16169,"answer":"diving","form":"-ing형","example":"Diving into cold water without warming up first can be dangerous for beginners.","exampleTranslation":"준비 운동 없이 차가운 물에 뛰어드는 것은 초보자에게 위험할 수 있다.","sense":"뛰어들다"},{"wordId":16169,"answer":"will dive","form":"미래","example":"The rescue diver will dive into the harbor again tomorrow morning to search.","exampleTranslation":"그 구조 잠수부는 내일 아침 다시 항구로 뛰어들어 수색할 것이다.","sense":"뛰어들다"},{"wordId":16170,"answer":"dolls","form":"복수형","example":"She collects several antique dolls from different countries around the world.","exampleTranslation":"그녀는 전 세계 여러 나라에서 온 골동품 인형을 수집한다.","sense":"인형"},{"wordId":16171,"answer":"dragons","form":"복수형","example":"In the legend, two dragons guarded the treasure hidden in the cave.","exampleTranslation":"그 전설에서 용 두 마리가 동굴에 숨겨진 보물을 지켰다.","sense":"용"},{"wordId":16172,"answer":"shyer","form":"비교급","example":"The younger sister was always much shyer than her outgoing older brother.","exampleTranslation":"여동생은 항상 사교적인 오빠보다 훨씬 더 수줍음이 많았다.","sense":"수줍은"},{"wordId":16172,"answer":"shyly","form":"부사형","example":"The new student smiled shyly and quietly took a seat near the back.","exampleTranslation":"그 신입생은 수줍게 미소 지으며 조용히 뒷자리에 앉았다.","sense":"수줍은"},{"wordId":16174,"answer":"six","form":"원형","example":"The recipe suggests marinating the chicken for six hours before grilling it.","exampleTranslation":"그 조리법은 굽기 전에 닭고기를 여섯 시간 동안 재워 두라고 제안한다.","sense":"여섯"},{"wordId":16174,"answer":"six","form":"원형","example":"Their new puppy already weighs six pounds after just one month at home.","exampleTranslation":"그들의 새 강아지는 집에 온 지 한 달 만에 벌써 몸무게가 여섯 파운드나 된다.","sense":"여섯"},{"wordId":16175,"answer":"Sunday","form":"원형","example":"The bakery closes early on Sunday so the staff can rest.","exampleTranslation":"그 빵집은 직원들이 쉴 수 있도록 일요일에는 일찍 문을 닫는다.","sense":"일요일"},{"wordId":16176,"answer":"ten","form":"원형","example":"My uncle has spent ten long years slowly restoring that same old motorcycle in his garage.","exampleTranslation":"우리 삼촌은 차고에서 그 낡은 오토바이를 천천히 복원하는 데 십 년이라는 긴 세월을 보냈다.","sense":"열"},{"wordId":16176,"answer":"ten","form":"원형","example":"The workshop lasted ten days longer than the organizers had originally planned.","exampleTranslation":"그 워크숍은 주최 측이 원래 계획했던 것보다 십 일 더 길어졌다.","sense":"열"},{"wordId":16177,"answer":"bishops","form":"복수형","example":"Several bishops attended the ceremony to bless the new cathedral.","exampleTranslation":"여러 주교가 새 대성당을 축복하려고 그 의식에 참석했다.","sense":"주교"},{"wordId":16178,"answer":"blasting","form":"-ing형","example":"My neighbor keeps blasting loud music every single night until almost midnight.","exampleTranslation":"우리 이웃은 거의 자정까지 매일 밤 시끄러운 음악을 크게 틀어 놓는다.","sense":"크게 틀다"},{"wordId":16178,"answer":"was blasted","form":"수동태","example":"The old warehouse was blasted apart during a controlled demolition last weekend.","exampleTranslation":"그 낡은 창고는 지난 주말 통제된 폭파 작업 중에 폭파되었다.","sense":"폭파하다"},{"wordId":16179,"answer":"blends","form":"3인칭 단수형","example":"This particular coffee shop usually blends dark roast beans with a hint of cinnamon.","exampleTranslation":"이 특정 커피숍은 대개 다크 로스트 원두에 시나몬 향을 살짝 섞는다.","sense":"섞다"},{"wordId":16179,"answer":"is blending","form":"현재진행","example":"The chef is blending fresh basil into the sauce right now for tonight's special.","exampleTranslation":"주방장은 오늘 밤 특별 요리를 위해 지금 소스에 신선한 바질을 섞고 있다.","sense":"섞다"},{"wordId":16180,"answer":"bureaus","form":"복수형","example":"Two government bureaus were merged to reduce unnecessary paperwork.","exampleTranslation":"불필요한 서류 작업을 줄이려고 정부 사무국 두 곳이 통합되었다.","sense":"사무국"},{"wordId":16181,"answer":"cabinets","form":"복수형","example":"The kitchen has several wooden cabinets for storing dishes and pots.","exampleTranslation":"그 주방에는 그릇과 냄비를 보관하는 나무 캐비닛 여러 개가 있다.","sense":"캐비닛"},{"wordId":16182,"answer":"carving","form":"-ing형","example":"The old craftsman spent the entire afternoon carving a small wooden bird.","exampleTranslation":"그 늙은 장인은 오후 내내 작은 나무 새를 조각했다.","sense":"조각하다"},{"wordId":16182,"answer":"was carved","form":"수동태","example":"This beautiful stone statue was carved by a local artist many years ago.","exampleTranslation":"이 아름다운 석상은 여러 해 전 한 지역 예술가가 조각한 것이다.","sense":"조각하다"},{"wordId":16184,"answer":"Catholic","form":"원형","example":"Every relative on her father's side belonged to the same small Catholic parish.","exampleTranslation":"그녀의 아버지 쪽 친척들은 모두 같은 작은 가톨릭 교구에 속해 있었다.","sense":"가톨릭의"},{"wordId":16184,"answer":"Catholic","form":"원형","example":"The old Catholic church downtown still holds a candlelight service every Christmas Eve.","exampleTranslation":"시내의 오래된 가톨릭 성당은 매년 크리스마스 이브에 여전히 촛불 예배를 연다.","sense":"가톨릭의"},{"wordId":16185,"answer":"cattle","form":"원형","example":"The rancher moved his cattle to a different pasture before winter.","exampleTranslation":"그 목장주는 겨울이 오기 전에 소들을 다른 목초지로 옮겼다.","sense":"소"},{"wordId":16186,"answer":"Ceasing","form":"-ing형","example":"Ceasing production entirely was not an option for the struggling company last year.","exampleTranslation":"생산을 완전히 중단하는 것은 그 어려움을 겪던 회사에게 선택지가 아니었다.","sense":"중단하다"},{"wordId":16186,"answer":"has ceased","form":"현재완료","example":"The old bus route has ceased operating since the new subway line opened.","exampleTranslation":"그 낡은 버스 노선은 새 지하철 노선이 개통된 이후로 운행을 중단했다.","sense":"중단하다","alts":["has aborted"]},{"wordId":16187,"answer":"charters","form":"3인칭 단수형","example":"This travel agency often charters small planes for remote island tours.","exampleTranslation":"이 여행사는 외딴 섬 투어를 위해 종종 소형 비행기를 전세 낸다.","sense":"전세 내다"},{"wordId":16187,"answer":"is chartering","form":"현재진행","example":"Our department is chartering a large bus for the annual company retreat this year.","exampleTranslation":"우리 부서는 올해 연례 회사 워크숍을 위해 대형 버스를 전세 내고 있다.","sense":"전세 내다"},{"wordId":16188,"answer":"chilled","form":"과거형","example":"She chilled the soup in the refrigerator for about two hours before serving.","exampleTranslation":"그녀는 내놓기 전에 냉장고에서 두 시간 정도 수프를 차게 식혔다.","sense":"차게 식히다"},{"wordId":16188,"answer":"has chilled","form":"현재완료","example":"The sudden autumn wind has chilled the whole valley since early this morning.","exampleTranslation":"갑작스러운 가을바람이 오늘 이른 아침부터 계곡 전체를 차갑게 식혔다.","sense":"차게 식히다"},{"wordId":16189,"answer":"circuits","form":"복수형","example":"The technician tested several circuits before finding the faulty one.","exampleTranslation":"그 기술자는 고장 난 것을 찾기 전 회로 여러 개를 테스트했다.","sense":"회로"},{"wordId":16190,"answer":"circulating","form":"-ing형","example":"A strange rumor started circulating among the students right before final exams.","exampleTranslation":"이상한 소문이 기말시험 직전에 학생들 사이에서 퍼지기 시작했다.","sense":"퍼지다"},{"wordId":16190,"answer":"was circulated","form":"수동태","example":"The updated safety memo was circulated to every employee before the holiday break.","exampleTranslation":"그 업데이트된 안전 안내문은 휴가 전에 모든 직원에게 배포되었다.","sense":"퍼뜨리다","alts":["is propagated"]},{"wordId":16191,"answer":"civilizes","form":"3인칭 단수형","example":"The professor argues that art often civilizes a society more than laws do.","exampleTranslation":"그 교수는 예술이 법보다 사회를 더 문명화하는 경우가 많다고 주장한다.","sense":"문명화하다"},{"wordId":16191,"answer":"is civilizing","form":"현재진행","example":"Modern education is civilizing remote communities across the mountain region slowly these days.","exampleTranslation":"현대 교육은 요즘 산간 지역의 외딴 공동체들을 서서히 문명화하고 있다.","sense":"문명화하다"},{"wordId":16192,"answer":"clarified","form":"과거형","example":"The teacher clarified the confusing instructions right after several students raised their hands.","exampleTranslation":"선생님은 여러 학생이 손을 든 직후에 헷갈리는 지시 사항을 명확히 했다.","sense":"명확히 하다"},{"wordId":16192,"answer":"has clarified","form":"현재완료","example":"The spokesperson has clarified the company's new refund policy several times already.","exampleTranslation":"그 대변인은 회사의 새 환불 정책을 벌써 여러 번 명확히 밝혔다.","sense":"명확히 하다"},{"wordId":16193,"answer":"clinics","form":"복수형","example":"The health department opened two clinics in rural areas this year.","exampleTranslation":"보건 당국은 올해 농촌 지역에 진료소 두 곳을 열었다.","sense":"진료소"},{"wordId":16194,"answer":"drawers","form":"복수형","example":"He keeps his socks and ties in two separate drawers.","exampleTranslation":"그는 양말과 넥타이를 서랍 두 개에 나눠 보관한다.","sense":"서랍"},{"wordId":16195,"answer":"drums","form":"3인칭 단수형","example":"He nervously drums his fingers on the desk before every important meeting.","exampleTranslation":"그는 중요한 회의 전마다 초조하게 책상 위에서 손가락을 두드린다.","sense":"손가락으로 두드리다"},{"wordId":16195,"answer":"is drumming","form":"현재진행","example":"My little brother is drumming on the kitchen table while waiting for breakfast.","exampleTranslation":"내 남동생은 아침을 기다리는 동안 부엌 식탁 위에서 손가락을 두드리고 있다.","sense":"손가락으로 두드리다"},{"wordId":16196,"answer":"ducked","form":"과거형","example":"Everyone quickly ducked when the low branch swung across the narrow trail.","exampleTranslation":"좁은 오솔길 위로 낮은 나뭇가지가 휙 지나가자 모두가 재빨리 고개를 숙였다.","sense":"홱 수그리다"},{"wordId":16196,"answer":"has ducked","form":"현재완료","example":"The goalkeeper has ducked out of every difficult interview since the tough loss.","exampleTranslation":"그 골키퍼는 그 힘든 패배 이후로 어려운 인터뷰를 매번 피해 왔다.","sense":"피하다","alts":["has deflected"]},{"wordId":16197,"answer":"dumped","form":"과거분사","example":"The dumped furniture sat on the curb for nearly a week before collection.","exampleTranslation":"버려진 가구는 수거되기 전까지 거의 일주일 동안 길가에 놓여 있었다.","sense":"폐기하다","alts":["deserted"]},{"wordId":16197,"answer":"will dump","form":"미래","example":"The construction crew will dump all the old bricks at the recycling center tomorrow.","exampleTranslation":"그 공사 인부들은 내일 재활용 센터에 낡은 벽돌을 모두 버릴 것이다.","sense":"폐기하다","alts":["will desert"]},{"wordId":16198,"answer":"elder","form":"원형","example":"At every family dinner, my elder cousin insists on telling the same old stories.","exampleTranslation":"가족 저녁 식사 때마다 손위 사촌은 늘 같은 옛날이야기를 하겠다고 고집한다.","sense":"손위의"},{"wordId":16198,"answer":"elder","form":"원형","example":"The village elder council still settles most local disputes without involving the police.","exampleTranslation":"그 마을 원로 회의는 경찰을 부르지 않고도 여전히 대부분의 지역 분쟁을 해결한다.","sense":"원로의"},{"wordId":16199,"answer":"elephants","form":"복수형","example":"The safari group spotted three elephants drinking at the watering hole.","exampleTranslation":"그 사파리 일행은 물웅덩이에서 물을 마시는 코끼리 세 마리를 발견했다.","sense":"코끼리"},{"wordId":16200,"answer":"fainted","form":"과거형","example":"The young soldier fainted after standing at attention for nearly two hours.","exampleTranslation":"그 젊은 군인은 거의 두 시간 동안 부동자세로 서 있다가 기절했다.","sense":"기절하다"},{"wordId":16200,"answer":"has fainted","form":"현재완료","example":"One visitor has fainted already from the summer heat at the crowded festival.","exampleTranslation":"붐비는 축제에서 여름 더위 때문에 한 방문객이 벌써 기절했다.","sense":"기절하다"},{"wordId":16201,"answer":"fairies","form":"복수형","example":"The storybook featured several fairies who protected the enchanted forest.","exampleTranslation":"그 동화책에는 마법의 숲을 지키는 요정 여러 명이 등장했다.","sense":"요정","alts":["elves"]},{"wordId":16202,"answer":"feathers","form":"복수형","example":"Bright feathers from two parrots covered the bottom of the cage.","exampleTranslation":"앵무새 두 마리의 밝은 깃털이 새장 바닥을 덮었다.","sense":"깃털"},{"wordId":16203,"answer":"February","form":"원형","example":"The clinic sees far more flu patients in February than in summer.","exampleTranslation":"그 병원은 여름보다 2월에 독감 환자를 훨씬 더 많이 본다.","sense":"2월"},{"wordId":16204,"answer":"fetched","form":"과거형","example":"The delivery boy fetched a fresh loaf of bread from the corner bakery.","exampleTranslation":"그 배달 소년은 모퉁이 빵집에서 신선한 빵 한 덩이를 가져왔다.","sense":"가져오다"},{"wordId":16204,"answer":"has fetched","form":"현재완료","example":"The nurse has fetched extra blankets for every patient in the cold ward tonight.","exampleTranslation":"그 간호사는 오늘 밤 추운 병동의 환자 모두를 위해 여분의 담요를 가져다주었다.","sense":"가져오다"},{"wordId":16206,"answer":"thirteen","form":"원형","example":"My niece will turn thirteen next month and already wants her own phone.","exampleTranslation":"내 조카는 다음 달에 열세 살이 되는데 벌써 자기 휴대전화를 갖고 싶어 한다.","sense":"열셋"},{"wordId":16206,"answer":"thirteen","form":"원형","example":"The company has thirteen branches scattered across three different provinces.","exampleTranslation":"그 회사는 세 개의 다른 지방에 흩어진 열세 개의 지점을 가지고 있다.","sense":"열셋"},{"wordId":16207,"answer":"thirty","form":"원형","example":"My aunt has taught piano lessons out of her living room for thirty years.","exampleTranslation":"우리 이모는 삼십 년째 자기 집 거실에서 피아노 레슨을 해 왔다.","sense":"서른"},{"wordId":16207,"answer":"thirty","form":"원형","example":"The bus was thirty minutes late, so most passengers missed their connecting train.","exampleTranslation":"그 버스가 삼십 분 늦어서 대부분의 승객이 환승 기차를 놓쳤다.","sense":"서른"},{"wordId":16209,"answer":"coalitions","form":"복수형","example":"Historically, small parties have formed several coalitions to gain more influence.","exampleTranslation":"역사적으로 군소 정당들은 더 큰 영향력을 얻으려고 여러 연합을 구성해 왔다.","sense":"연합"},{"wordId":16210,"answer":"coinciding","form":"-ing형","example":"Her birthday coinciding with the national holiday made travel plans extremely difficult this year.","exampleTranslation":"그녀의 생일이 국경일과 겹치는 바람에 올해 여행 계획을 세우기가 몹시 어려워졌다.","sense":"동시에 일어나다"},{"wordId":16210,"answer":"is coinciding","form":"현재진행","example":"This year, the music festival is coinciding with the town's annual harvest celebration.","exampleTranslation":"올해는 음악 축제가 마을의 연례 수확 기념행사와 동시에 열리고 있다.","sense":"동시에 일어나다"},{"wordId":16211,"answer":"collaborates","form":"3인칭 단수형","example":"Our design team regularly collaborates with the marketing department on new packaging ideas.","exampleTranslation":"우리 디자인팀은 새 포장 아이디어를 두고 마케팅 부서와 정기적으로 협력한다.","sense":"협력하다"},{"wordId":16211,"answer":"are collaborating","form":"현재진행","example":"The two universities are collaborating on a major climate research project this semester.","exampleTranslation":"그 두 대학은 이번 학기에 대규모 기후 연구 프로젝트에서 협력하고 있다.","sense":"협력하다"},{"wordId":16212,"answer":"colonies","form":"복수형","example":"Marine biologists studied several coral colonies damaged by warmer waters.","exampleTranslation":"해양 생물학자들은 따뜻해진 바닷물로 손상된 산호 군집 여러 곳을 연구했다.","sense":"군집"},{"wordId":16213,"answer":"combating","form":"-ing형","example":"The health ministry launched several new posters aimed at combating childhood obesity.","exampleTranslation":"보건부는 소아 비만과 싸우기 위한 새 포스터 여러 개를 내놓았다.","sense":"싸우다"},{"wordId":16213,"answer":"will combat","form":"미래","example":"The city council will combat illegal dumping with stricter fines starting next month.","exampleTranslation":"시 의회는 다음 달부터 더 엄격한 벌금으로 불법 투기와 싸울 것이다.","sense":"싸우다"},{"wordId":16214,"answer":"communist","form":"원형","example":"Their documentary follows a family who secretly fled a communist regime decades ago.","exampleTranslation":"그들의 다큐멘터리는 수십 년 전 공산주의 정권을 몰래 탈출한 한 가족을 따라간다.","sense":"공산주의의"},{"wordId":16214,"answer":"communist","form":"원형","example":"Her grandfather often talked about growing up under a communist government many years ago.","exampleTranslation":"그녀의 할아버지는 오래전 공산주의 정부 아래서 자랐던 이야기를 자주 하셨다.","sense":"공산주의의"},{"wordId":16215,"answer":"companions","form":"복수형","example":"She traveled with two trusted companions through the remote mountains.","exampleTranslation":"그녀는 믿을 수 있는 동반자 두 명과 함께 외딴 산맥을 여행했다.","sense":"동반자","alts":["plus-ones"]},{"wordId":16216,"answer":"compensated","form":"과거형","example":"The airline compensated every passenger with a full refund after the long delay.","exampleTranslation":"그 항공사는 긴 지연 이후 승객 모두에게 전액 환불로 보상했다.","sense":"보상하다"},{"wordId":16216,"answer":"has compensated","form":"현재완료","example":"The company has compensated several injured workers since the factory accident last spring.","exampleTranslation":"그 회사는 지난봄 공장 사고 이후로 다친 근로자 여럿에게 보상해 왔다.","sense":"보상하다"},{"wordId":16217,"answer":"more competent","form":"비교급","example":"The new hire seemed far more competent than the previous assistant during training.","exampleTranslation":"그 신입 직원은 교육 기간 동안 이전 조수보다 훨씬 더 유능해 보였다.","sense":"유능한"},{"wordId":16217,"answer":"competence","form":"명사형","example":"Her competence in handling difficult clients impressed the entire sales team.","exampleTranslation":"까다로운 고객을 다루는 그녀의 능숙함은 영업팀 전체에게 깊은 인상을 남겼다.","sense":"유능한"},{"wordId":16218,"answer":"conceiving","form":"-ing형","example":"The young architect spent months conceiving a bold new design for the museum.","exampleTranslation":"그 젊은 건축가는 미술관을 위한 대담한 새 디자인을 몇 달 동안 구상했다.","sense":"생각해내다"},{"wordId":16218,"answer":"was conceived","form":"수동태","example":"The entire festival was conceived by two students during a late-night conversation.","exampleTranslation":"그 축제 전체는 두 학생이 밤늦게 나눈 대화에서 처음 구상되었다.","sense":"생각해내다"},{"wordId":16219,"answer":"condemns","form":"3인칭 단수형","example":"The newspaper editorial strongly condemns the recent decision to cut library funding.","exampleTranslation":"그 신문 사설은 최근 도서관 예산 삭감 결정을 강하게 비난한다.","sense":"비난하다"},{"wordId":16219,"answer":"is condemning","form":"현재진행","example":"The mayor is condemning the vandalism at the park during tonight's press conference.","exampleTranslation":"시장은 오늘 밤 기자회견에서 공원 기물 파손 행위를 비난하고 있다.","sense":"비난하다"},{"wordId":16220,"answer":"conferred","form":"과거형","example":"The lawyers conferred privately for almost an hour before the trial resumed.","exampleTranslation":"변호인단은 재판이 재개되기 전 거의 한 시간 동안 은밀히 상의했다.","sense":"상의하다"},{"wordId":16220,"answer":"have conferred","form":"현재완료","example":"The two department heads have conferred several times about the upcoming budget cuts.","exampleTranslation":"두 부서장은 다가오는 예산 삭감에 대해 여러 번 상의해 왔다.","sense":"상의하다"},{"wordId":16221,"answer":"flaming","form":"-ing형","example":"The flaming logs cast a warm orange glow across the entire living room.","exampleTranslation":"타오르는 장작은 거실 전체에 따뜻한 주황빛을 드리웠다.","sense":"타오르다"},{"wordId":16221,"answer":"will flame","form":"미래","example":"Dry brush along the hillside will flame quickly if a single spark lands there.","exampleTranslation":"언덕 옆의 마른 덤불은 불꽃 하나만 튀어도 빠르게 타오를 것이다.","sense":"타오르다"},{"wordId":16222,"answer":"flipping","form":"-ing형","example":"The short-order cook kept flipping pancakes on the griddle without ever stopping.","exampleTranslation":"그 즉석요리 요리사는 멈추지 않고 계속 그리들 위에서 팬케이크를 뒤집었다.","sense":"휙 뒤집다"},{"wordId":16222,"answer":"was flipped","form":"수동태","example":"The old car was flipped upside down by the powerful flash flood last week.","exampleTranslation":"그 낡은 자동차는 지난주 강력한 돌발 홍수에 의해 뒤집혔다.","sense":"휙 뒤집다"},{"wordId":16223,"answer":"fortnight","form":"원형","example":"The two companies agreed to meet again in a fortnight to finalize the contract.","exampleTranslation":"두 회사는 계약을 마무리하려고 2주 뒤에 다시 만나기로 합의했다.","sense":"2주"},{"wordId":16224,"answer":"foxes","form":"복수형","example":"Farmers spotted two foxes prowling near the henhouse at night.","exampleTranslation":"농부들은 밤에 닭장 근처를 어슬렁거리는 여우 두 마리를 발견했다.","sense":"여우"},{"wordId":16225,"answer":"frankly","form":"원형","example":"The critic frankly admitted that the film disappointed her greatly.","exampleTranslation":"그 평론가는 그 영화가 자신을 크게 실망시켰다고 솔직히 인정했다.","sense":"솔직히"},{"wordId":16226,"answer":"frogs","form":"복수형","example":"Children caught several frogs near the pond behind the school.","exampleTranslation":"아이들은 학교 뒤 연못 근처에서 개구리 여러 마리를 잡았다.","sense":"개구리"},{"wordId":16227,"answer":"frustrates","form":"3인칭 단수형","example":"The slow internet connection frustrates almost every remote worker in this building.","exampleTranslation":"느린 인터넷 연결은 이 건물의 거의 모든 재택근무자를 좌절시킨다.","sense":"좌절시키다","alts":["thwarts"]},{"wordId":16227,"answer":"has frustrated","form":"현재완료","example":"The endless paperwork has frustrated new employees since the policy changed last month.","exampleTranslation":"그 끝없는 서류 작업은 지난달 정책이 바뀐 이후로 신입 직원들을 좌절시켜 왔다.","sense":"좌절시키다"},{"wordId":16228,"answer":"fur","form":"원형","example":"The cat's fur turned matted after playing outside in the rain.","exampleTranslation":"그 고양이의 털은 밖에서 비를 맞으며 놀고 난 뒤 엉켰다.","sense":"털"},{"wordId":16229,"answer":"garages","form":"복수형","example":"The new apartment complex includes two garages for each unit.","exampleTranslation":"그 새 아파트 단지는 각 세대에 차고 두 곳을 포함한다.","sense":"차고"},{"wordId":16230,"answer":"ghosts","form":"복수형","example":"The old hotel is rumored to be haunted by several restless ghosts.","exampleTranslation":"그 오래된 호텔은 편히 쉬지 못하는 유령 여러 명이 출몰한다는 소문이 있다.","sense":"유령","alts":["spectres"]},{"wordId":16231,"answer":"glories","form":"복수형","example":"Tour guides love describing the glories of the ancient Roman Empire.","exampleTranslation":"관광 가이드들은 고대 로마 제국의 영광을 즐겨 설명한다.","sense":"영광"},{"wordId":16232,"answer":"most gorgeous","form":"최상급","example":"Everyone at the wedding said the bride's dress was the most gorgeous they had ever seen.","exampleTranslation":"결혼식에 온 모든 사람은 신부의 드레스가 지금까지 본 것 중 가장 화려하다고 말했다.","sense":"화려한"},{"wordId":16232,"answer":"gorgeous","form":"원형","example":"The sunset over the ocean looked gorgeous from the small balcony of their rented cabin.","exampleTranslation":"빌린 오두막의 작은 발코니에서 본 바다 위 노을은 화려하고 아름다웠다.","sense":"화려한"},{"wordId":16233,"answer":"gracing","form":"-ing형","example":"A famous soprano is gracing this small theater with a rare live performance.","exampleTranslation":"유명한 소프라노가 이 작은 극장에 흔치 않은 라이브 공연으로 품위를 더하고 있다.","sense":"품위를 더하다"},{"wordId":16233,"answer":"will grace","form":"미래","example":"Her latest sculpture will grace the entrance of the city hall next spring.","exampleTranslation":"그녀의 최신 조각 작품은 내년 봄 시청 입구에 품위를 더할 것이다.","sense":"품위를 더하다"},{"wordId":16234,"answer":"thousand","form":"원형","example":"A thousand tiny lights twinkled across the bridge during the annual winter festival.","exampleTranslation":"매년 열리는 겨울 축제 동안 다리를 가로질러 천 개의 작은 조명이 반짝였다.","sense":"천"},{"wordId":16234,"answer":"thousand","form":"원형","example":"The old manuscript is estimated to be worth several thousand dollars at auction.","exampleTranslation":"그 오래된 원고는 경매에서 수천 달러의 가치가 있을 것으로 추정된다.","sense":"천"},{"wordId":16235,"answer":"three","form":"원형","example":"The bakery sold three different flavors of pie during the weekend farmers market.","exampleTranslation":"그 빵집은 주말 농산물 시장에서 세 가지 다른 맛의 파이를 팔았다.","sense":"셋"},{"wordId":16235,"answer":"three","form":"원형","example":"The chef needs three more assistants to handle orders during the holiday rush.","exampleTranslation":"그 주방장은 명절 대목의 주문을 처리하기 위해 조수 세 명이 더 필요하다.","sense":"셋"},{"wordId":16236,"answer":"Thursday","form":"원형","example":"The delivery is expected to arrive sometime before Thursday afternoon.","exampleTranslation":"그 배송은 목요일 오후 전에 도착할 것으로 예상된다.","sense":"목요일"},{"wordId":16237,"answer":"Tuesday","form":"원형","example":"The board postponed the vote until the following Tuesday.","exampleTranslation":"이사회는 그다음 화요일까지 투표를 미뤘다.","sense":"화요일"},{"wordId":16238,"answer":"confessing","form":"-ing형","example":"He finally broke down confessing his mistake to the entire management team.","exampleTranslation":"그는 결국 경영진 전체에게 자신의 실수를 고백하며 무너져 내렸다.","sense":"고백하다"},{"wordId":16238,"answer":"has confessed","form":"현재완료","example":"The young intern has confessed his error to the supervisor twice already this week.","exampleTranslation":"그 젊은 인턴은 이번 주에만 벌써 두 번이나 상사에게 실수를 고백했다.","sense":"고백하다"},{"wordId":16239,"answer":"confines","form":"3인칭 단수형","example":"The strict editor usually confines every article to under eight hundred words.","exampleTranslation":"그 엄격한 편집자는 보통 모든 기사를 800단어 이하로 국한시킨다.","sense":"국한시키다"},{"wordId":16239,"answer":"is confining","form":"현재진행","example":"The new policy is confining junior staff to a single department this quarter.","exampleTranslation":"새 정책은 이번 분기에 신입 직원들을 한 부서로 국한시키고 있다.","sense":"국한시키다"},{"wordId":16240,"answer":"confronted","form":"과거형","example":"She confronted her fear of public speaking during last month's leadership workshop.","exampleTranslation":"그녀는 지난달 리더십 워크숍에서 대중 앞에서 말하는 두려움에 맞섰다.","sense":"맞서다"},{"wordId":16240,"answer":"has confronted","form":"현재완료","example":"The committee has confronted several difficult questions since the scandal first broke.","exampleTranslation":"그 위원회는 그 스캔들이 처음 터진 이후로 여러 어려운 질문에 맞서 왔다.","sense":"맞서다"},{"wordId":16241,"answer":"Congress","form":"원형","example":"Congress is expected to vote on the new trade agreement next week.","exampleTranslation":"의회는 다음 주 새 무역 협정에 대해 투표할 것으로 예상된다.","sense":"의회"},{"wordId":16242,"answer":"consenting","form":"-ing형","example":"Both parents ended up consenting to the trip only after a long discussion.","exampleTranslation":"양쪽 부모 모두 긴 논의 끝에야 그 여행에 동의하게 되었다.","sense":"동의하다"},{"wordId":16242,"answer":"is consenting","form":"현재진행","example":"The patient is consenting to the surgery after speaking with the doctor again.","exampleTranslation":"그 환자는 의사와 다시 이야기를 나눈 뒤 수술에 동의하고 있다.","sense":"동의하다"},{"wordId":16243,"answer":"consequent","form":"원형","example":"The factory fire and its consequent shutdown left dozens of workers without income.","exampleTranslation":"그 공장 화재와 그로 인한 폐쇄는 수십 명의 노동자를 소득 없이 남겨두었다.","sense":"결과로 일어나는"},{"wordId":16243,"answer":"consequence","form":"명사형","example":"He never seemed to consider the consequence of skipping his medication for several days.","exampleTranslation":"그는 며칠 동안 약을 거르는 것의 결과를 전혀 고려하지 않는 것 같았다.","sense":"결과로 일어나는"},{"wordId":16244,"answer":"conserved","form":"과거형","example":"Local farmers conserved rainwater carefully throughout the unusually dry summer season.","exampleTranslation":"지역 농부들은 이례적으로 건조했던 여름 내내 빗물을 신중하게 보존했다.","sense":"보존하다"},{"wordId":16244,"answer":"has conserved","form":"현재완료","example":"This small town has conserved its historic buildings since the preservation law passed.","exampleTranslation":"이 작은 마을은 보존법이 통과된 이후로 역사적인 건물들을 지켜 왔다.","sense":"보존하다"},{"wordId":16245,"answer":"constitutions","form":"복수형","example":"Legal scholars compared how several national constitutions protect free speech.","exampleTranslation":"법학자들은 여러 나라의 헌법이 언론의 자유를 어떻게 보호하는지 비교했다.","sense":"헌법"},{"wordId":16246,"answer":"constraining","form":"-ing형","example":"Limited funding keeps constraining the research team's ability to hire new staff.","exampleTranslation":"제한된 자금은 그 연구팀이 새 직원을 채용할 능력을 계속 제약하고 있다.","sense":"제약하다"},{"wordId":16246,"answer":"were constrained","form":"수동태","example":"Our travel plans were constrained by a surprisingly small vacation budget this year.","exampleTranslation":"우리 여행 계획은 올해 뜻밖에 작은 휴가 예산 때문에 제약을 받았다.","sense":"제약하다"},{"wordId":16247,"answer":"consumption","form":"원형","example":"The new tax aims to reduce consumption of sugary drinks nationwide.","exampleTranslation":"그 새 세금은 전국적으로 설탕이 든 음료 소비를 줄이는 것을 목표로 한다.","sense":"소비"},{"wordId":16248,"answer":"contended","form":"과거형","example":"The defense lawyer contended that the evidence had been mishandled from the start.","exampleTranslation":"그 변호인은 처음부터 증거가 잘못 다루어졌다고 주장했다.","sense":"주장하다","alts":["alleged"]},{"wordId":16248,"answer":"have contended","form":"현재완료","example":"Several scientists have contended that the original study contained a major flaw.","exampleTranslation":"몇몇 과학자는 원래 연구에 중대한 결함이 있었다고 주장해 왔다.","sense":"주장하다","alts":["has argued","have alleged"]},{"wordId":16249,"answer":"continents","form":"복수형","example":"Migratory birds cross several continents during their long yearly journey.","exampleTranslation":"철새들은 매년 긴 여정 동안 여러 대륙을 가로지른다.","sense":"대륙"},{"wordId":16250,"answer":"grocers","form":"복수형","example":"Several local grocers raised their prices after the sudden supply shortage.","exampleTranslation":"갑작스러운 공급 부족 이후 여러 지역 식료품상이 가격을 올렸다.","sense":"식료품상"},{"wordId":16251,"answer":"handiest","form":"최상급","example":"Of all the tools in the garage, the small flashlight turned out to be the handiest.","exampleTranslation":"차고에 있는 모든 도구 중에서 그 작은 손전등이 가장 편리한 것으로 드러났다.","sense":"편리한","alts":["most convenient"]},{"wordId":16251,"answer":"handy","form":"원형","example":"A folding knife like this comes in handy on almost every camping trip.","exampleTranslation":"이런 접이식 칼은 거의 모든 캠핑 여행에서 유용하게 쓰인다.","sense":"편리한"},{"wordId":16252,"answer":"heaped","form":"과거형","example":"She heaped extra vegetables onto her brother's plate before he could protest.","exampleTranslation":"그녀는 오빠가 항의하기도 전에 그의 접시에 채소를 잔뜩 쌓아 올렸다.","sense":"쌓다"},{"wordId":16252,"answer":"have heaped","form":"현재완료","example":"Critics have heaped praise on the young director since the film's premiere.","exampleTranslation":"평론가들은 그 영화가 개봉한 이후로 젊은 감독에게 찬사를 쏟아부어 왔다.","sense":"쏟다"},{"wordId":16253,"answer":"heaven","form":"원형","example":"Many cultures imagine heaven as a peaceful garden filled with light.","exampleTranslation":"많은 문화권은 천국을 빛으로 가득한 평화로운 정원으로 상상한다.","sense":"천국"},{"wordId":16254,"answer":"hedging","form":"-ing형","example":"During the debate, the candidate kept hedging on every question about tax reform.","exampleTranslation":"토론 중에 그 후보는 세제 개편에 관한 모든 질문에서 계속 얼버무렸다.","sense":"회피하다"},{"wordId":16254,"answer":"is hedging","form":"현재진행","example":"The manager is hedging about the merger instead of announcing a clear decision.","exampleTranslation":"그 관리자는 명확한 결정을 발표하는 대신 합병에 대해 얼버무리고 있다.","sense":"회피하다"},{"wordId":16255,"answer":"hobbies","form":"복수형","example":"She enjoys several hobbies, including painting and mountain biking.","exampleTranslation":"그녀는 그림 그리기와 산악자전거를 포함해 여러 취미를 즐긴다.","sense":"취미","alts":["pastimes"]},{"wordId":16256,"answer":"honey","form":"원형","example":"The bakery uses local honey to sweeten its famous bread.","exampleTranslation":"그 빵집은 유명한 빵을 달게 하려고 지역산 꿀을 사용한다.","sense":"꿀"},{"wordId":16257,"answer":"idiots","form":"복수형","example":"The comedian jokingly called his two friends idiots during the show.","exampleTranslation":"그 코미디언은 공연 중 농담 삼아 두 친구를 바보라고 불렀다.","sense":"바보"},{"wordId":16258,"answer":"most incredible","form":"최상급","example":"Standing beneath the waterfall at sunrise was the most incredible experience of her entire trip.","exampleTranslation":"해돋이에 폭포 아래 서 있던 것은 그녀의 여행 전체에서 가장 놀라운 경험이었다.","sense":"놀라운"},{"wordId":16258,"answer":"incredibly","form":"부사형","example":"The chef cooked incredibly fast, finishing every dish before the timer even rang.","exampleTranslation":"그 요리사는 놀라울 정도로 빠르게 요리해서 타이머가 울리기도 전에 모든 요리를 끝냈다.","sense":"믿을 수 없는"},{"wordId":16259,"answer":"inspects","form":"3인칭 단수형","example":"The officer usually inspects every vehicle carefully before it leaves the factory gate.","exampleTranslation":"그 감독관은 보통 공장 출입문을 나서기 전에 모든 차량을 꼼꼼히 검사한다.","sense":"검사하다"},{"wordId":16259,"answer":"is inspecting","form":"현재진행","example":"A health inspector is inspecting the new restaurant kitchen for the very first time.","exampleTranslation":"보건 감독관이 처음으로 새 식당 주방을 검사하고 있다.","sense":"검사하다"},{"wordId":16260,"answer":"instant","form":"원형","example":"This mobile banking app offers instant transfers between accounts at any hour.","exampleTranslation":"이 모바일 뱅킹 앱은 언제든 계좌 간 즉각적인 이체를 제공한다.","sense":"즉각적인"},{"wordId":16260,"answer":"instantly","form":"부사형","example":"The dog instantly recognized its owner's voice through the closed front door.","exampleTranslation":"그 개는 닫힌 현관문 너머로 주인의 목소리를 즉시 알아챘다.","sense":"순간의","alts":["immediately","promptly"]},{"wordId":16261,"answer":"instructed","form":"과거분사","example":"The clearly instructed team followed every safety step without a single mistake.","exampleTranslation":"명확하게 지시받은 팀은 실수 하나 없이 모든 안전 절차를 따랐다.","sense":"지시하다"},{"wordId":16261,"answer":"will instruct","form":"미래","example":"The manager will instruct new employees on safety procedures during tomorrow's orientation.","exampleTranslation":"관리자는 내일 오리엔테이션에서 신입 직원들에게 안전 절차를 지시할 것이다.","sense":"지시하다"},{"wordId":16262,"answer":"twelve","form":"원형","example":"Only twelve seats remained for the concert by the time she checked online.","exampleTranslation":"그녀가 온라인으로 확인했을 때는 그 콘서트 좌석이 열두 자리밖에 남아 있지 않았다.","sense":"열둘"},{"wordId":16262,"answer":"twelve","form":"원형","example":"Twelve students signed up for the pottery class before registration closed.","exampleTranslation":"등록이 마감되기 전에 열두 명의 학생이 도예 수업에 신청했다.","sense":"열둘"},{"wordId":16263,"answer":"twenty","form":"원형","example":"The tailor promised the wedding dress would be finished within twenty days.","exampleTranslation":"그 재단사는 웨딩드레스가 이십 일 안에 완성될 것이라고 약속했다.","sense":"스물"},{"wordId":16263,"answer":"twenty","form":"원형","example":"The bakery sells about twenty loaves of sourdough bread every single morning.","exampleTranslation":"그 빵집은 매일 아침 약 이십 개의 사워도우 빵을 판매한다.","sense":"스물"},{"wordId":16264,"answer":"two","form":"원형","example":"The recipe only needs two ripe bananas and a splash of honey.","exampleTranslation":"그 조리법은 잘 익은 바나나 두 개와 꿀 약간만 있으면 된다.","sense":"둘"},{"wordId":16264,"answer":"two","form":"원형","example":"The apartment has two bedrooms but only one small bathroom upstairs.","exampleTranslation":"그 아파트는 침실이 두 개지만 위층에 작은 욕실이 하나뿐이다.","sense":"둘"},{"wordId":16265,"answer":"controversies","form":"복수형","example":"The senator faced several controversies during his short time in office.","exampleTranslation":"그 상원의원은 짧은 재임 기간 동안 여러 논란에 휩싸였다.","sense":"논란"},{"wordId":16266,"answer":"conveying","form":"-ing형","example":"The short speech succeeded in conveying genuine warmth to everyone in the audience.","exampleTranslation":"그 짧은 연설은 청중 모두에게 진심 어린 따뜻함을 전달하는 데 성공했다.","sense":"전달하다","alts":["relaying"]},{"wordId":16266,"answer":"was conveyed","form":"수동태","example":"The urgent message was conveyed to headquarters within only a few minutes.","exampleTranslation":"그 긴급한 메시지는 불과 몇 분 만에 본사로 전달되었다.","sense":"전달하다"},{"wordId":16267,"answer":"convicts","form":"3인칭 단수형","example":"This particular judge rarely convicts a defendant without very strong physical evidence.","exampleTranslation":"이 특정 판사는 매우 강력한 물적 증거 없이는 좀처럼 피고에게 유죄를 선고하지 않는다.","sense":"유죄를 선고하다"},{"wordId":16267,"answer":"is convicting","form":"현재진행","example":"The jury is convicting the defendant after only two hours of deliberation today.","exampleTranslation":"배심원단은 오늘 단 두 시간의 심의 끝에 피고에게 유죄를 선고하고 있다.","sense":"유죄를 선고하다"},{"wordId":16268,"answer":"cooperated","form":"과거형","example":"The two rival departments finally cooperated on last year's holiday charity drive.","exampleTranslation":"두 경쟁 부서는 작년 연말 자선 행사에서 마침내 협력했다.","sense":"협력하다"},{"wordId":16268,"answer":"has cooperated","form":"현재완료","example":"The witness has cooperated fully with investigators ever since the case began.","exampleTranslation":"그 목격자는 사건이 시작된 이후로 줄곧 수사관들과 전적으로 협력해 왔다.","sense":"협력하다"},{"wordId":16269,"answer":"coordinated","form":"과거분사","example":"The carefully coordinated rescue effort saved every hiker trapped on the mountain.","exampleTranslation":"세심하게 조정된 구조 작업 덕분에 산에 갇힌 등산객 모두를 구했다.","sense":"조정하다"},{"wordId":16269,"answer":"will coordinate","form":"미래","example":"She will coordinate the volunteers for next month's community cleanup event.","exampleTranslation":"그녀는 다음 달 지역사회 대청소 행사에서 자원봉사자들을 조정할 것이다.","sense":"조정하다"},{"wordId":16270,"answer":"correlating","form":"-ing형","example":"Researchers spent years correlating sleep habits with long-term memory performance in adults.","exampleTranslation":"연구자들은 수면 습관과 장기 기억력 사이의 관계를 밝히는 데 수년을 보냈다.","sense":"연관시키다"},{"wordId":16270,"answer":"were correlated","form":"수동태","example":"Higher exercise levels were correlated with better sleep in the recent study.","exampleTranslation":"최근 연구에서 더 많은 운동량은 더 좋은 수면과 연관성이 있는 것으로 나타났다.","sense":"상관관계가 있다"},{"wordId":16271,"answer":"correspondents","form":"복수형","example":"The network sent two correspondents to cover the disaster overseas.","exampleTranslation":"그 방송사는 해외 재난을 취재하려고 특파원 두 명을 보냈다.","sense":"특파원"},{"wordId":16272,"answer":"corridors","form":"복수형","example":"Students are not allowed to run in the school's narrow corridors.","exampleTranslation":"학생들은 학교의 좁은 복도에서 뛰면 안 된다.","sense":"복도","alts":["halls"]},{"wordId":16273,"answer":"more corrupt","form":"비교급","example":"The journalist proved that the mayor's office was far more corrupt than anyone suspected.","exampleTranslation":"그 기자는 시장 사무실이 사람들이 의심했던 것보다 훨씬 더 부패했다는 것을 증명했다.","sense":"부패한"},{"wordId":16273,"answer":"corruption","form":"명사형","example":"Widespread corruption within the agency finally came to light after the audit.","exampleTranslation":"감사 이후 그 기관 내부의 광범위한 부패가 마침내 드러났다.","sense":"부패한"},{"wordId":16274,"answer":"courage","form":"원형","example":"It took real courage for him to admit his mistake publicly.","exampleTranslation":"그가 공개적으로 실수를 인정하는 데는 진짜 용기가 필요했다.","sense":"용기"},{"wordId":16275,"answer":"cruises","form":"3인칭 단수형","example":"This large ferry usually cruises along the coast at a steady, gentle speed.","exampleTranslation":"이 큰 여객선은 보통 해안을 따라 안정적이고 잔잔한 속도로 순항한다.","sense":"순항하다"},{"wordId":16275,"answer":"is cruising","form":"현재진행","example":"The retired couple is cruising through the Mediterranean for their thirtieth anniversary.","exampleTranslation":"그 은퇴한 부부는 서른 번째 결혼기념일을 맞아 지중해를 순항하고 있다.","sense":"순항하다"},{"wordId":16276,"answer":"crushed","form":"과거형","example":"The heavy machine accidentally crushed several boxes stacked near the warehouse entrance.","exampleTranslation":"그 무거운 기계는 창고 입구 근처에 쌓여 있던 상자 여러 개를 실수로 으스러뜨렸다.","sense":"으스러뜨리다"},{"wordId":16276,"answer":"has crushed","form":"현재완료","example":"The home team has crushed every opponent it has faced so far this season.","exampleTranslation":"그 홈팀은 이번 시즌 지금까지 맞붙은 상대 모두를 압도적으로 눌러 왔다.","sense":"압도하다"},{"wordId":16277,"answer":"crystals","form":"복수형","example":"Scientists grew several crystals in the lab to study their structure.","exampleTranslation":"과학자들은 구조를 연구하려고 실험실에서 결정체 여러 개를 길렀다.","sense":"결정체"},{"wordId":16278,"answer":"curricula","form":"복수형","example":"The two schools compared their curricula to find common gaps.","exampleTranslation":"그 두 학교는 공통된 공백을 찾으려고 각자의 교육과정을 비교했다.","sense":"교육과정"},{"wordId":16279,"answer":"defendants","form":"복수형","example":"The judge asked both defendants to remain standing during the verdict.","exampleTranslation":"판사는 평결이 내려지는 동안 두 피고 모두 서 있으라고 했다.","sense":"피고"},{"wordId":16280,"answer":"delegated","form":"과거형","example":"The busy director delegated most of the daily tasks to her assistant last month.","exampleTranslation":"바쁜 이사는 지난달 일상 업무 대부분을 비서에게 위임했다.","sense":"위임하다"},{"wordId":16280,"answer":"has delegated","form":"현재완료","example":"The new supervisor has delegated several key projects to junior staff already.","exampleTranslation":"새 관리자는 벌써 핵심 프로젝트 여러 개를 신입 직원들에게 위임했다.","sense":"위임하다"},{"wordId":16281,"answer":"most deliberate","form":"최상급","example":"Investigators concluded that the fire was started in the most deliberate way possible.","exampleTranslation":"수사관들은 그 화재가 가능한 가장 의도적인 방식으로 시작되었다고 결론지었다.","sense":"의도적인"},{"wordId":16281,"answer":"deliberately","form":"부사형","example":"He deliberately arrived late to avoid the awkward small talk before the meeting.","exampleTranslation":"그는 회의 전 어색한 잡담을 피하려고 일부러 늦게 도착했다.","sense":"의도적인"},{"wordId":16282,"answer":"democrats","form":"복수형","example":"Several democrats and republicans agreed on the new infrastructure bill.","exampleTranslation":"여러 민주당원과 공화당원이 새 기반 시설 법안에 동의했다.","sense":"민주당원"},{"wordId":16283,"answer":"more intent","form":"비교급","example":"After losing the first game, the chess player grew more intent on studying every opening move.","exampleTranslation":"첫 경기에서 진 뒤 그 체스 선수는 모든 오프닝 수를 연구하는 데 훨씬 더 몰두하게 되었다.","sense":"몰두하는"},{"wordId":16283,"answer":"intently","form":"부사형","example":"She listened intently as her mentor explained the complicated tax rules.","exampleTranslation":"그녀는 멘토가 복잡한 세금 규정을 설명하는 동안 골똘히 귀 기울였다.","sense":"몰두하는"},{"wordId":16284,"answer":"interrupted","form":"과거형","example":"A sudden power outage interrupted the concert right in the middle of the performance.","exampleTranslation":"갑작스러운 정전이 공연 한가운데에서 콘서트를 방해했다.","sense":"중단시키다","alts":["impeded"]},{"wordId":16284,"answer":"has interrupted","form":"현재완료","example":"The noisy construction next door has interrupted our meetings several times this week.","exampleTranslation":"옆 건물의 시끄러운 공사가 이번 주에만 여러 번 우리 회의를 방해했다.","sense":"중단시키다","alts":["has hindered","have impeded"]},{"wordId":16285,"answer":"jammed","form":"과거분사","example":"The jammed printer caused a long delay for everyone in the office that morning.","exampleTranslation":"그날 아침 종이가 걸린 프린터 때문에 사무실 모두가 오래 지연을 겪었다.","sense":"막히게 하다"},{"wordId":16285,"answer":"will jam","form":"미래","example":"Too many shoppers will jam the small parking lot during the holiday sale.","exampleTranslation":"명절 세일 동안 너무 많은 쇼핑객이 그 작은 주차장을 꽉 막히게 할 것이다.","sense":"막히게 하다"},{"wordId":16286,"answer":"January","form":"원형","example":"Gym memberships always increase right after January begins.","exampleTranslation":"헬스장 회원 가입은 1월이 시작되자마자 항상 늘어난다.","sense":"1월"},{"wordId":16287,"answer":"jaws","form":"복수형","example":"The dentist examined both jaws carefully before recommending braces.","exampleTranslation":"치과의사는 교정기를 권하기 전에 양쪽 턱을 꼼꼼히 살폈다.","sense":"턱뼈","alts":["chins"]},{"wordId":16288,"answer":"jeans","form":"원형","example":"He wore his favorite jeans to the casual weekend barbecue.","exampleTranslation":"그는 편안한 주말 바비큐 모임에 가장 좋아하는 청바지를 입고 갔다.","sense":"청바지"},{"wordId":16289,"answer":"juice","form":"원형","example":"She drank a glass of orange juice before heading to work.","exampleTranslation":"그녀는 출근하기 전 오렌지 주스 한 잔을 마셨다.","sense":"주스"},{"wordId":16290,"answer":"July","form":"원형","example":"The company usually announces bonuses sometime in July.","exampleTranslation":"그 회사는 보통 7월 중에 보너스를 발표한다.","sense":"7월"},{"wordId":16291,"answer":"June","form":"원형","example":"Their wedding is planned for the second weekend of June.","exampleTranslation":"그들의 결혼식은 6월 둘째 주말로 계획되어 있다.","sense":"6월"},{"wordId":16292,"answer":"junior","form":"원형","example":"After finishing her internship, she accepted a junior role at a growing tech startup.","exampleTranslation":"인턴십을 마친 뒤 그녀는 성장하는 기술 스타트업에서 하급 직책을 받아들였다.","sense":"하급의"},{"wordId":16292,"answer":"junior","form":"원형","example":"The junior staff members were invited to shadow the senior engineers during the project.","exampleTranslation":"그 프로젝트 동안 하급 직원들은 선임 엔지니어들을 따라다니며 배울 기회를 얻었다.","sense":"하급의"},{"wordId":16296,"answer":"denser","form":"비교급","example":"The forest near the border grew much denser after decades without any logging.","exampleTranslation":"수십 년간 벌목이 없었던 국경 근처 숲은 훨씬 더 빽빽해졌다.","sense":"빽빽한"},{"wordId":16296,"answer":"densely","form":"부사형","example":"The apartments downtown are packed densely together with barely any space between them.","exampleTranslation":"시내의 아파트들은 사이 공간이 거의 없이 빽빽하게 밀집해 있다.","sense":"밀집한"},{"wordId":16297,"answer":"depicted","form":"과거분사","example":"The vividly depicted battle scene impressed every visitor at the new exhibit.","exampleTranslation":"생생하게 묘사된 전투 장면은 새 전시회의 모든 관람객에게 깊은 인상을 남겼다.","sense":"묘사하다"},{"wordId":16297,"answer":"will depict","form":"미래","example":"The upcoming documentary will depict daily life in a remote fishing village.","exampleTranslation":"다가오는 다큐멘터리는 외딴 어촌 마을의 일상생활을 묘사할 것이다.","sense":"그려내다"},{"wordId":16298,"answer":"deputies","form":"복수형","example":"The sheriff assigned two deputies to patrol the quiet neighborhood.","exampleTranslation":"보안관은 조용한 동네를 순찰하도록 대리 두 명을 배정했다.","sense":"대리"},{"wordId":16299,"answer":"descends","form":"3인칭 단수형","example":"This narrow trail descends steeply into the valley for almost two miles.","exampleTranslation":"이 좁은 산길은 거의 2마일 동안 가파르게 계곡으로 내려간다.","sense":"내려가다"},{"wordId":16299,"answer":"is descending","form":"현재진행","example":"The plane is descending rapidly as it approaches the small mountain airport.","exampleTranslation":"그 비행기는 작은 산악 공항에 접근하면서 빠르게 하강하고 있다.","sense":"내려가다"},{"wordId":16300,"answer":"designated","form":"과거형","example":"The mayor designated a quiet corner lot for the new community garden last spring.","exampleTranslation":"시장은 지난봄 조용한 모퉁이 땅을 새 공동체 정원 부지로 지정했다.","sense":"지정하다"},{"wordId":16300,"answer":"has designated","form":"현재완료","example":"The school has designated a separate classroom for students who need extra support.","exampleTranslation":"그 학교는 추가 지원이 필요한 학생들을 위해 별도의 교실을 지정해 왔다.","sense":"지정하다"},{"wordId":16301,"answer":"devastated","form":"과거분사","example":"The devastated coastline took years to recover after the massive storm surge.","exampleTranslation":"황폐화된 해안 지역은 대규모 폭풍 해일 이후 회복하는 데 여러 해가 걸렸다.","sense":"황폐화시키다"},{"wordId":16301,"answer":"will devastate","form":"미래","example":"The approaching wildfire will devastate several small farms if the wind shifts.","exampleTranslation":"다가오는 산불은 바람의 방향이 바뀌면 작은 농장 여러 곳을 황폐화시킬 것이다.","sense":"황폐화시키다"},{"wordId":16303,"answer":"dictates","form":"3인칭 단수형","example":"The senior manager usually dictates important memos to his assistant every Friday afternoon.","exampleTranslation":"그 선임 관리자는 보통 금요일 오후마다 비서에게 중요한 메모를 받아쓰게 한다.","sense":"받아쓰게 하다"},{"wordId":16303,"answer":"is dictating","form":"현재진행","example":"The novelist is dictating her next chapter to a recording device this week.","exampleTranslation":"그 소설가는 이번 주에 녹음기에 대고 다음 장을 받아쓰게 하고 있다.","sense":"받아쓰게 하다"},{"wordId":16304,"answer":"diplomats","form":"복수형","example":"Several diplomats met privately to resolve the border dispute quietly.","exampleTranslation":"여러 외교관이 국경 분쟁을 조용히 해결하려고 비공개로 만났다.","sense":"외교관"},{"wordId":16305,"answer":"disabled","form":"원형","example":"The city library installed new elevators so disabled patrons could reach every floor easily.","exampleTranslation":"시립 도서관은 장애가 있는 이용객들이 모든 층에 쉽게 갈 수 있도록 새 엘리베이터를 설치했다.","sense":"장애가 있는"},{"wordId":16305,"answer":"disabled","form":"원형","example":"The city redesigned the park entrance to better accommodate disabled children and their families.","exampleTranslation":"그 도시는 장애가 있는 아이들과 그 가족들을 더 잘 배려하기 위해 공원 입구를 재설계했다.","sense":"장애가 있는"},{"wordId":16306,"answer":"discs","form":"복수형","example":"The archive stores old records on many discs kept in the basement.","exampleTranslation":"그 기록보관소는 오래된 자료를 지하실에 있는 여러 디스크에 저장한다.","sense":"디스크","alts":["disks"]},{"wordId":16307,"answer":"discourse","form":"원형","example":"The panel encouraged open discourse about mental health in schools.","exampleTranslation":"그 패널은 학교 내 정신 건강에 관한 열린 담론을 장려했다.","sense":"담론"},{"wordId":16308,"answer":"more discreet","form":"비교급","example":"The hotel staff were trained to be far more discreet about celebrity guests.","exampleTranslation":"그 호텔 직원들은 유명인 손님에 대해 훨씬 더 신중하게 행동하도록 교육받았다.","sense":"조심스러운","alts":["more careful","more prudent"]},{"wordId":16308,"answer":"discreetly","form":"부사형","example":"The waiter discreetly slipped the note under the plate without anyone noticing.","exampleTranslation":"그 종업원은 아무도 눈치채지 못하게 조심스럽게 접시 밑에 쪽지를 끼워 넣었다.","sense":"은밀한","alts":["prudently"]},{"wordId":16309,"answer":"discriminated","form":"과거분사","example":"Historically discriminated communities still face major barriers to fair housing today.","exampleTranslation":"역사적으로 차별받아 온 공동체들은 오늘날에도 공정한 주거에 큰 장벽을 마주하고 있다.","sense":"차별하다"},{"wordId":16309,"answer":"will discriminate","form":"미래","example":"This company will discriminate against no applicant based on age or gender.","exampleTranslation":"이 회사는 나이나 성별을 이유로 어떤 지원자도 차별하지 않을 것이다.","sense":"차별하다"},{"wordId":16310,"answer":"disposing","form":"-ing형","example":"The factory follows strict rules when disposing of chemical waste every quarter.","exampleTranslation":"그 공장은 분기마다 화학 폐기물을 처리할 때 엄격한 규칙을 따른다.","sense":"처리하다"},{"wordId":16310,"answer":"is disposing","form":"현재진행","example":"The cleaning crew is disposing of broken furniture from the old office today.","exampleTranslation":"청소팀은 오늘 낡은 사무실에서 나온 부서진 가구를 처리하고 있다.","sense":"처리하다"},{"wordId":16311,"answer":"disrupts","form":"3인칭 단수형","example":"A single broken cable often disrupts internet service for the whole neighborhood.","exampleTranslation":"끊어진 케이블 하나가 종종 동네 전체의 인터넷 서비스를 방해한다.","sense":"지장을 주다","alts":["hampers","hinders"]},{"wordId":16311,"answer":"are disrupting","form":"현재진행","example":"The ongoing road repairs are disrupting traffic near downtown this entire week.","exampleTranslation":"진행 중인 도로 보수 공사가 이번 주 내내 시내 근처 교통을 방해하고 있다.","sense":"지장을 주다","alts":["is hampering","is thwarting"]},{"wordId":16312,"answer":"most diverse","form":"최상급","example":"This university attracts one of the most diverse student populations in the country.","exampleTranslation":"이 대학교는 그 나라에서 가장 다양한 학생 집단 중 하나를 끌어모은다.","sense":"다양한"},{"wordId":16312,"answer":"diversity","form":"명사형","example":"The company launched a program to improve diversity across every department.","exampleTranslation":"그 회사는 모든 부서의 다양성을 높이기 위한 프로그램을 시작했다.","sense":"다양한"},{"wordId":16313,"answer":"DNA","form":"원형","example":"The lab extracted DNA from a single hair found at the campsite.","exampleTranslation":"그 연구실은 야영지에서 발견된 머리카락 한 올에서 유전자를 추출했다.","sense":"유전자"},{"wordId":16314,"answer":"doctrines","form":"복수형","example":"Scholars compared the doctrines of two ancient philosophical schools.","exampleTranslation":"학자들은 고대 철학 학파 두 곳의 교리를 비교했다.","sense":"교리"},{"wordId":16315,"answer":"most dominant","form":"최상급","example":"Among the wolves in the pack, the largest female was clearly the most dominant.","exampleTranslation":"그 늑대 무리 중에서 가장 큰 암컷이 분명히 가장 지배적이었다.","sense":"지배적인"},{"wordId":16315,"answer":"dominance","form":"명사형","example":"The company's market dominance has made it difficult for smaller competitors to survive.","exampleTranslation":"그 회사의 시장 지배력은 작은 경쟁사들이 살아남기 어렵게 만들었다.","sense":"지배적인"},{"wordId":16316,"answer":"kilometers","form":"복수형","example":"The marathon route covers just over forty-two kilometers total.","exampleTranslation":"그 마라톤 코스는 총 42킬로미터를 조금 넘게 이어진다.","sense":"킬로미터"},{"wordId":16317,"answer":"knitted","form":"과거분사","example":"The carefully knitted sweater kept the child warm all through the winter.","exampleTranslation":"정성스레 뜨개질한 스웨터는 겨울 내내 아이를 따뜻하게 지켜 주었다.","sense":"뜨개질하다"},{"wordId":16317,"answer":"will knit","form":"미래","example":"My grandmother will knit a matching scarf for each of her grandchildren next winter.","exampleTranslation":"할머니는 다음 겨울에 손주들 모두를 위해 어울리는 목도리를 떠 주실 것이다.","sense":"뜨개질하다"},{"wordId":16318,"answer":"lambs","form":"복수형","example":"In spring, several lambs were born on the small hillside farm.","exampleTranslation":"봄이 되자 그 작은 언덕 농장에서 새끼 양 여러 마리가 태어났다.","sense":"새끼양"},{"wordId":16319,"answer":"lamps","form":"복수형","example":"She placed two matching lamps on either side of the bed.","exampleTranslation":"그녀는 침대 양쪽에 짝을 이루는 램프 두 개를 놓았다.","sense":"램프"},{"wordId":16320,"answer":"lanes","form":"복수형","example":"The highway added two extra lanes to ease the rush-hour traffic.","exampleTranslation":"그 고속도로는 출퇴근 시간 교통 체증을 줄이려고 차선 두 개를 추가했다.","sense":"차선"},{"wordId":16321,"answer":"lawns","form":"복수형","example":"Several neighbors hired the same company to mow their lawns weekly.","exampleTranslation":"여러 이웃이 매주 잔디밭을 깎으려고 같은 업체를 고용했다.","sense":"잔디밭"},{"wordId":16322,"answer":"lids","form":"복수형","example":"She lost two lids from her favorite set of storage containers.","exampleTranslation":"그녀는 가장 좋아하는 보관 용기 세트에서 뚜껑 두 개를 잃어버렸다.","sense":"뚜껑"},{"wordId":16323,"answer":"lightly","form":"원형","example":"The waiter lightly dusted the plate with fresh herbs before serving.","exampleTranslation":"웨이터는 서빙하기 전에 접시에 신선한 허브를 가볍게 뿌렸다.","sense":"가볍게"},{"wordId":16324,"answer":"lions","form":"복수형","example":"Two lions rested lazily beneath the shade of an old tree.","exampleTranslation":"사자 두 마리가 오래된 나무 그늘 아래에서 나른하게 쉬고 있었다.","sense":"사자"},{"wordId":16325,"answer":"lone","form":"원형","example":"A lone fisherman cast his line quietly from the edge of the wooden pier.","exampleTranslation":"외로운 어부 한 명이 나무 부두 끝에서 조용히 낚싯줄을 던졌다.","sense":"혼자인"},{"wordId":16325,"answer":"lone","form":"원형","example":"The lone streetlight flickered above the quiet corner where the two roads met.","exampleTranslation":"두 길이 만나는 조용한 모퉁이 위에서 외딴 가로등 하나가 깜박거렸다.","sense":"외딴"},{"wordId":16326,"answer":"lowering","form":"-ing형","example":"The nurse spent several minutes lowering the patient's bed before the visit ended.","exampleTranslation":"간호사는 면회가 끝나기 전 몇 분 동안 환자의 침대를 낮추었다.","sense":"낮추다"},{"wordId":16326,"answer":"was lowered","form":"수동태","example":"The old flag was lowered slowly during the solemn ceremony this morning.","exampleTranslation":"그 낡은 깃발은 오늘 아침 엄숙한 의식 동안 천천히 내려졌다.","sense":"낮추다"},{"wordId":16327,"answer":"Wednesday","form":"원형","example":"The results will not be released until sometime next Wednesday.","exampleTranslation":"결과는 다음 주 수요일이 되어서야 발표될 것이다.","sense":"수요일"},{"wordId":16330,"answer":"donating","form":"-ing형","example":"Every winter, our neighbors spend an afternoon donating old clothes to the shelter.","exampleTranslation":"매년 겨울, 우리 이웃들은 오후 시간을 들여 낡은 옷을 보호소에 기부한다.","sense":"기부하다"},{"wordId":16330,"answer":"was donated","form":"수동태","example":"A large sum of money was donated to the hospital after the fundraiser ended.","exampleTranslation":"그 모금 행사가 끝난 뒤 큰돈이 병원에 기부되었다.","sense":"기부하다"},{"wordId":16331,"answer":"doses","form":"복수형","example":"The vet prescribed two doses of medicine daily for the sick puppy.","exampleTranslation":"수의사는 아픈 강아지에게 매일 약 두 회분을 처방했다.","sense":"복용량","alts":["dosages"]},{"wordId":16332,"answer":"drained","form":"과거형","example":"He drained the old fish tank completely before adding the new gravel.","exampleTranslation":"그는 새 자갈을 넣기 전에 낡은 어항의 물을 완전히 뺐다.","sense":"배수시키다"},{"wordId":16332,"answer":"has drained","form":"현재완료","example":"The long meeting has drained everyone's energy since it began three hours ago.","exampleTranslation":"그 긴 회의는 세 시간 전에 시작된 이후로 모두의 기운을 소모시켜 왔다.","sense":"소모시키다"},{"wordId":16333,"answer":"drifting","form":"-ing형","example":"The empty rowboat kept drifting farther from shore as the tide slowly rose.","exampleTranslation":"빈 노 젓는 배는 물이 서서히 차오르면서 해안에서 점점 더 멀리 표류했다.","sense":"표류하다"},{"wordId":16333,"answer":"will drift","form":"미래","example":"Without a strong anchor, the small boat will drift toward the rocky shore.","exampleTranslation":"튼튼한 닻이 없으면 그 작은 배는 바위투성이 해안 쪽으로 표류할 것이다.","sense":"표류하다"},{"wordId":16334,"answer":"drilling","form":"-ing형","example":"The coach spent every practice drilling the players on basic passing skills.","exampleTranslation":"그 감독은 매 연습마다 선수들에게 기본 패스 기술을 훈련시켰다.","sense":"훈련시키다"},{"wordId":16334,"answer":"were drilled","form":"수동태","example":"The new recruits were drilled on emergency procedures throughout their first week.","exampleTranslation":"신입 대원들은 첫 주 내내 비상 절차에 관해 훈련받았다.","sense":"훈련시키다"},{"wordId":16335,"answer":"dukes","form":"복수형","example":"Several dukes attended the royal wedding held at the palace.","exampleTranslation":"여러 공작이 궁전에서 열린 왕실 결혼식에 참석했다.","sense":"공작"},{"wordId":16336,"answer":"more eager","form":"비교급","example":"After finally landing her dream internship, she became even more eager to prove herself.","exampleTranslation":"마침내 꿈꾸던 인턴십을 얻은 뒤 그녀는 자신을 증명하려는 열의가 훨씬 더 커졌다.","sense":"열망하는"},{"wordId":16336,"answer":"eagerly","form":"부사형","example":"The children waited eagerly by the window for the first snowfall of winter.","exampleTranslation":"아이들은 겨울의 첫눈을 창가에서 간절히 기다렸다.","sense":"열망하는"},{"wordId":16337,"answer":"echoing","form":"-ing형","example":"Her laughter kept echoing through the empty stone hallway long after she left.","exampleTranslation":"그녀가 떠난 뒤에도 그녀의 웃음소리는 텅 빈 석조 복도에 오랫동안 울려 퍼졌다.","sense":"울려 퍼지다"},{"wordId":16337,"answer":"will echo","form":"미래","example":"His powerful speech will echo in the minds of voters for years to come.","exampleTranslation":"그의 강렬한 연설은 앞으로 몇 년 동안 유권자들의 마음속에 울려 퍼질 것이다.","sense":"울려 퍼지다"},{"wordId":16338,"answer":"elaborating","form":"-ing형","example":"The consultant spent the entire meeting elaborating on the new marketing strategy.","exampleTranslation":"그 컨설턴트는 회의 내내 새 마케팅 전략에 대해 자세히 설명했다.","sense":"자세히 설명하다"},{"wordId":16338,"answer":"is elaborating","form":"현재진행","example":"The professor is elaborating on the theory for the students who seemed confused.","exampleTranslation":"그 교수는 헷갈려 하는 학생들을 위해 그 이론을 자세히 설명하고 있다.","sense":"자세히 설명하다"},{"wordId":16339,"answer":"elevates","form":"3인칭 단수형","example":"Regular exercise usually elevates a person's energy levels throughout the entire day.","exampleTranslation":"규칙적인 운동은 보통 하루 종일 사람의 에너지 수준을 높인다.","sense":"끌어올리다","alts":["heightens"]},{"wordId":16339,"answer":"is elevating","form":"현재진행","example":"The new promotion is elevating her confidence at work these days.","exampleTranslation":"새로운 승진은 요즘 직장에서 그녀의 자신감을 높이고 있다.","sense":"높이다"},{"wordId":16340,"answer":"most elite","form":"최상급","example":"Only the most elite climbers ever attempt that dangerous route up the north face.","exampleTranslation":"가장 엘리트인 등반가들만 그 북벽의 위험한 루트에 도전한다.","sense":"엘리트인"},{"wordId":16340,"answer":"elite","form":"원형","example":"Only elite soldiers were chosen for the dangerous nighttime rescue mission.","exampleTranslation":"위험한 야간 구조 임무에는 오직 엘리트 군인들만 선발되었다.","sense":"엘리트인"},{"wordId":16341,"answer":"emitted","form":"과거분사","example":"The dimly emitted glow from the old lamp barely lit the small room.","exampleTranslation":"낡은 램프에서 희미하게 방출된 불빛은 작은 방을 겨우 밝혔다.","sense":"방출하다"},{"wordId":16341,"answer":"will emit","form":"미래","example":"This new engine will emit far less carbon than the previous model.","exampleTranslation":"이 새 엔진은 이전 모델보다 탄소를 훨씬 적게 방출할 것이다.","sense":"방출하다"},{"wordId":16342,"answer":"endorsing","form":"-ing형","example":"Two former mayors spent the afternoon endorsing the young candidate for city council.","exampleTranslation":"전직 시장 두 명은 오후 내내 젊은 시의원 후보를 지지했다.","sense":"지지하다","alts":["upholding"]},{"wordId":16342,"answer":"was endorsed","form":"수동태","example":"The new safety policy was endorsed unanimously by the entire staff yesterday.","exampleTranslation":"그 새 안전 정책은 어제 전 직원에 의해 만장일치로 지지되었다.","sense":"지지하다"},{"wordId":16343,"answer":"endures","form":"3인칭 단수형","example":"This old bridge still endures heavy traffic every single day without any damage.","exampleTranslation":"이 오래된 다리는 매일 아무 손상 없이 여전히 무거운 교통량을 견딘다.","sense":"버티다","alts":["bears"]},{"wordId":16343,"answer":"is enduring","form":"현재진행","example":"The small village is enduring its harshest winter in nearly two decades.","exampleTranslation":"그 작은 마을은 거의 20년 만에 가장 혹독한 겨울을 견디고 있다.","sense":"견디다"},{"wordId":16344,"answer":"enforced","form":"과거형","example":"The new principal enforced the dress code strictly from the very first day.","exampleTranslation":"새 교장은 첫날부터 엄격하게 복장 규정을 집행했다.","sense":"집행하다"},{"wordId":16344,"answer":"has enforced","form":"현재완료","example":"The city has enforced the new noise ordinance since early last spring.","exampleTranslation":"그 시는 지난봄 초부터 새 소음 조례를 집행해 왔다.","sense":"집행하다"},{"wordId":16345,"answer":"enthusiasm","form":"원형","example":"The new intern approached every task with remarkable enthusiasm.","exampleTranslation":"그 신입 인턴은 모든 업무에 놀라운 열정으로 임했다.","sense":"열정"},{"wordId":16346,"answer":"more enthusiastic","form":"비교급","example":"The coach became far more enthusiastic once the team started winning every match.","exampleTranslation":"그 코치는 팀이 모든 경기에서 이기기 시작하자 훨씬 더 열정적으로 변했다.","sense":"열정적인"},{"wordId":16346,"answer":"enthusiasm","form":"명사형","example":"Her enthusiasm for painting spread quickly to the rest of the art class.","exampleTranslation":"그림에 대한 그녀의 열정은 미술 수업의 다른 학생들에게도 빠르게 퍼졌다.","sense":"열정적인"},{"wordId":16347,"answer":"most evident","form":"최상급","example":"The damage from the flood became most evident once the water finally receded.","exampleTranslation":"홍수로 인한 피해는 물이 마침내 빠지고 나서야 가장 분명해졌다.","sense":"확연한","alts":["most apparent"]},{"wordId":16347,"answer":"evidently","form":"부사형","example":"Evidently, the store had closed early, since the lights were already off by six.","exampleTranslation":"여섯 시가 되기 전에 이미 불이 꺼져 있는 것을 보니 그 가게는 분명히 일찍 문을 닫은 것 같았다.","sense":"확연한","alts":["apparently","clearly","obviously"]},{"wordId":16348,"answer":"more exclusive","form":"비교급","example":"The renovated club became far more exclusive after membership fees tripled last year.","exampleTranslation":"회원비가 작년에 세 배로 오른 뒤 그 개조된 클럽은 훨씬 더 배타적으로 변했다.","sense":"배타적인"},{"wordId":16348,"answer":"exclusivity","form":"명사형","example":"The brand relies on exclusivity to keep its products feeling special and rare.","exampleTranslation":"그 브랜드는 제품이 특별하고 희귀하게 느껴지도록 독점성에 의존한다.","sense":"독점적인"},{"wordId":16349,"answer":"executed","form":"과거분사","example":"Executed flawlessly, the surprise proposal left her speechless in front of everyone.","exampleTranslation":"완벽하게 실행된 깜짝 프러포즈는 모두가 보는 앞에서 그녀를 말문 막히게 했다.","sense":"실행하다"},{"wordId":16349,"answer":"will execute","form":"미래","example":"The stunt team will execute the dangerous jump during tomorrow's live broadcast.","exampleTranslation":"스턴트 팀은 내일 생방송 도중 위험한 점프를 실행할 것이다.","sense":"실행하다"},{"wordId":16350,"answer":"more explicit","form":"비교급","example":"The revised safety manual gives far more explicit instructions than the old version.","exampleTranslation":"그 개정된 안전 지침서는 예전 버전보다 훨씬 더 명확한 지시 사항을 제공한다.","sense":"명확한"},{"wordId":16350,"answer":"explicitly","form":"부사형","example":"The contract explicitly states that late payments will incur an extra fee.","exampleTranslation":"그 계약서는 연체 시 추가 수수료가 부과된다고 명확하게 명시한다.","sense":"명확한"},{"wordId":16351,"answer":"exploits","form":"3인칭 단수형","example":"The clever salesman often exploits every small weakness in a customer's argument.","exampleTranslation":"그 영리한 영업사원은 종종 고객의 주장에 있는 작은 약점을 이용한다.","sense":"이용하다"},{"wordId":16351,"answer":"is exploiting","form":"현재진행","example":"The struggling factory is exploiting a legal loophole to avoid the new tax.","exampleTranslation":"그 어려움을 겪는 공장은 새 세금을 피하려고 법의 허점을 이용하고 있다.","sense":"이용하다"},{"wordId":16352,"answer":"explosions","form":"복수형","example":"Witnesses reported two loud explosions near the old factory last night.","exampleTranslation":"목격자들은 어젯밤 오래된 공장 근처에서 시끄러운 폭발 두 번을 신고했다.","sense":"폭발"},{"wordId":16353,"answer":"fabric","form":"원형","example":"The designer chose a lightweight fabric for the summer collection.","exampleTranslation":"그 디자이너는 여름 컬렉션을 위해 가벼운 직물을 골랐다.","sense":"직물"},{"wordId":16354,"answer":"facilitating","form":"-ing형","example":"The consultant led the workshop, facilitating open discussion among the nervous new hires.","exampleTranslation":"그 컨설턴트는 워크숍을 진행하며 긴장한 신입 사원들 사이의 자유로운 토론을 촉진했다.","sense":"촉진하다"},{"wordId":16354,"answer":"was facilitated","form":"수동태","example":"The tense negotiation was facilitated by a calm, experienced mediator last week.","exampleTranslation":"그 긴장된 협상은 지난주 침착하고 노련한 중재자에 의해 촉진되었다.","sense":"촉진하다"},{"wordId":16355,"answer":"lumps","form":"복수형","example":"The doctor found two small lumps and ordered further tests.","exampleTranslation":"의사는 작은 덩어리 두 개를 발견하고 추가 검사를 지시했다.","sense":"혹","alts":["chunks","clumps","loaves","masses"]},{"wordId":16356,"answer":"mama","form":"원형","example":"Every evening, the toddler waits eagerly by the door for mama.","exampleTranslation":"매일 저녁 그 아기는 문 옆에서 엄마를 애타게 기다린다.","sense":"엄마"},{"wordId":16357,"answer":"marveling","form":"-ing형","example":"The young children stood marveling at the size of the enormous dinosaur skeleton.","exampleTranslation":"어린아이들은 거대한 공룡 뼈대 크기에 경탄하며 서 있었다.","sense":"경탄하다"},{"wordId":16357,"answer":"will marvel","form":"미래","example":"Future visitors will marvel at this ancient temple for centuries to come.","exampleTranslation":"앞으로 이 고대 사원을 찾는 방문객들은 수백 년 동안 경탄할 것이다.","sense":"경탄하다"},{"wordId":16358,"answer":"masking","form":"-ing형","example":"She kept masking her nervousness by smiling brightly at every guest.","exampleTranslation":"그녀는 손님들 모두에게 밝게 웃으며 자신의 긴장감을 계속 가렸다.","sense":"가리다"},{"wordId":16358,"answer":"was masked","form":"수동태","example":"His true disappointment was masked completely behind a calm, polite expression.","exampleTranslation":"그의 진짜 실망감은 차분하고 예의 바른 표정 뒤에 완전히 가려졌다.","sense":"가리다"},{"wordId":16359,"answer":"melts","form":"3인칭 단수형","example":"This chocolate usually melts within seconds in a person's warm hand.","exampleTranslation":"이 초콜릿은 보통 사람의 따뜻한 손 안에서 몇 초 만에 녹는다.","sense":"녹다"},{"wordId":16359,"answer":"is melting","form":"현재진행","example":"The last patch of snow on the roof is melting slowly under the bright sun.","exampleTranslation":"지붕 위 마지막 눈 조각이 밝은 햇살 아래 서서히 녹고 있다.","sense":"녹다"},{"wordId":16360,"answer":"merriest","form":"최상급","example":"Of all the holiday parties that year, hers was by far the merriest.","exampleTranslation":"그 해의 모든 명절 파티 중에서 그녀의 파티가 단연 가장 즐거웠다.","sense":"즐거운"},{"wordId":16360,"answer":"merriment","form":"명사형","example":"Laughter and merriment filled the small cabin every evening during the family trip.","exampleTranslation":"그 가족 여행 동안 매일 저녁 그 작은 오두막은 웃음과 즐거움으로 가득했다.","sense":"즐거운","alts":["jollity"]},{"wordId":16361,"answer":"microwaved","form":"과거분사","example":"The microwaved leftovers tasted surprisingly good for a quick weekday lunch.","exampleTranslation":"전자레인지에 데운 남은 음식은 평일 간단한 점심으로 뜻밖에 맛이 좋았다.","sense":"전자레인지에 데우다"},{"wordId":16361,"answer":"will microwave","form":"미래","example":"My roommate will microwave the soup while I set the table for dinner.","exampleTranslation":"내 룸메이트는 내가 저녁 식탁을 차리는 동안 수프를 전자레인지에 데울 것이다.","sense":"전자레인지에 데우다"},{"wordId":16362,"answer":"milling","form":"-ing형","example":"The old workers spent all morning milling wheat into fine white flour.","exampleTranslation":"나이 든 일꾼들은 아침 내내 밀을 곱게 빻아 하얀 밀가루로 만들었다.","sense":"제분하다"},{"wordId":16362,"answer":"was milled","form":"수동태","example":"The local grain was milled at this small family-run flour house for generations.","exampleTranslation":"이 지역 곡물은 여러 세대에 걸쳐 이 작은 가족 경영 제분소에서 빻아졌다.","sense":"제분하다"},{"wordId":16365,"answer":"faculties","form":"복수형","example":"The university merged two faculties to cut administrative costs.","exampleTranslation":"그 대학교는 행정 비용을 줄이려고 교수진 두 곳을 통합했다.","sense":"교수진"},{"wordId":16366,"answer":"fantasies","form":"복수형","example":"The author is famous for writing elaborate fantasies filled with dragons.","exampleTranslation":"그 작가는 용으로 가득한 정교한 환상 이야기를 쓰는 것으로 유명하다.","sense":"환상"},{"wordId":16367,"answer":"fate","form":"원형","example":"No one could predict what fate had in store for the young sailor.","exampleTranslation":"그 젊은 선원에게 어떤 운명이 기다리고 있는지 아무도 예측할 수 없었다.","sense":"운명"},{"wordId":16368,"answer":"more feminist","form":"비교급","example":"Her latest novel takes a far more feminist approach than her earlier published work.","exampleTranslation":"그녀의 최신 소설은 이전에 발표한 작품보다 훨씬 더 여성주의적인 접근을 취한다.","sense":"여성주의의"},{"wordId":16368,"answer":"feminism","form":"명사형","example":"She has studied feminism extensively since her first year at university.","exampleTranslation":"그녀는 대학교 첫 해부터 여성주의를 폭넓게 공부해 왔다.","sense":"여성주의의"},{"wordId":16369,"answer":"most fertile","form":"최상급","example":"The river delta remains the most fertile farmland found anywhere in the region.","exampleTranslation":"그 강 삼각주는 그 지역 어디에서도 찾을 수 없는 가장 비옥한 농지로 남아 있다.","sense":"비옥한"},{"wordId":16369,"answer":"fertility","form":"명사형","example":"Doctors studied how diet might affect fertility in women over forty.","exampleTranslation":"의사들은 식습관이 마흔 넘은 여성의 생식 능력에 어떤 영향을 미치는지 연구했다.","sense":"비옥한"},{"wordId":16370,"answer":"fiber","form":"원형","example":"Nutritionists recommend eating more fiber to support healthy digestion.","exampleTranslation":"영양학자들은 건강한 소화를 돕기 위해 식이섬유를 더 섭취하라고 권한다.","sense":"섬유"},{"wordId":16371,"answer":"fiercest","form":"최상급","example":"Of all the storms that hit the coast, this one was by far the fiercest.","exampleTranslation":"그 해안을 강타한 모든 폭풍 중에서 이번 것이 단연 가장 사나웠다.","sense":"사나운"},{"wordId":16371,"answer":"fierce","form":"원형","example":"Two food trucks parked side by side began a fierce rivalry over the same lunch crowd.","exampleTranslation":"나란히 주차한 두 푸드트럭은 같은 점심 손님을 두고 치열한 경쟁을 벌이기 시작했다.","sense":"치열한"},{"wordId":16372,"answer":"fled","form":"과거형","example":"Thousands of frightened residents fled the coastal town before the massive storm arrived.","exampleTranslation":"겁에 질린 주민 수천 명이 거대한 폭풍이 오기 전에 그 해안 마을을 떠나 도망쳤다.","sense":"도망치다"},{"wordId":16372,"answer":"has fled","form":"현재완료","example":"The entire family has fled their burning apartment safely without any injuries.","exampleTranslation":"그 가족 전체는 다친 사람 없이 안전하게 불타는 아파트에서 도망쳤다.","sense":"도망치다"},{"wordId":16373,"answer":"flesh","form":"원형","example":"The old scar had healed, but the flesh around it still felt tender.","exampleTranslation":"오래된 흉터는 나았지만 그 주변 살은 여전히 여릿여릿했다.","sense":"살"},{"wordId":16374,"answer":"fostering","form":"-ing형","example":"Good coaches spend years fostering both confidence and teamwork among young athletes.","exampleTranslation":"좋은 코치들은 여러 해 동안 어린 선수들 사이에 자신감과 팀워크를 함께 육성한다.","sense":"육성하다"},{"wordId":16374,"answer":"was fostered","form":"수동태","example":"A strong sense of community was fostered slowly among the new neighbors.","exampleTranslation":"새로 이사 온 이웃들 사이에 강한 공동체 의식이 서서히 육성되었다.","sense":"육성하다"},{"wordId":16375,"answer":"funerals","form":"복수형","example":"The small town held two funerals within the same sad week.","exampleTranslation":"그 작은 마을은 같은 슬픈 한 주 안에 장례식 두 번을 치렀다.","sense":"장례식"},{"wordId":16376,"answer":"ganged","form":"과거형","example":"The bigger boys ganged up on him constantly during that difficult school year.","exampleTranslation":"덩치 큰 남자아이들은 그 힘든 학년 내내 그에게 계속 떼로 덤벼들었다.","sense":"떼로 덤비다"},{"wordId":16376,"answer":"has ganged","form":"현재완료","example":"The whole sales team has ganged up on the new intern's proposal already.","exampleTranslation":"영업팀 전체는 벌써 그 신입 인턴의 제안에 떼로 반대하고 나섰다.","sense":"떼로 덤비다"},{"wordId":16377,"answer":"most generous","form":"최상급","example":"Among all the sponsors, the local bakery turned out to be the most generous.","exampleTranslation":"모든 후원자 중에서 그 지역 빵집이 가장 후한 것으로 드러났다.","sense":"후한"},{"wordId":16377,"answer":"generosity","form":"명사형","example":"The charity thanked the donor for his generosity toward the children's hospital.","exampleTranslation":"그 자선 단체는 어린이 병원에 대한 그의 관대함에 감사를 표했다.","sense":"관대한"},{"wordId":16378,"answer":"geography","form":"원형","example":"Students studied the geography of Southeast Asia this semester.","exampleTranslation":"학생들은 이번 학기에 동남아시아의 지리를 공부했다.","sense":"지리"},{"wordId":16379,"answer":"glows","form":"3인칭 단수형","example":"This particular paint glows faintly in the dark after the lights go off.","exampleTranslation":"이 특정 페인트는 불이 꺼진 뒤 어둠 속에서 희미하게 빛난다.","sense":"빛나다"},{"wordId":16379,"answer":"is glowing","form":"현재진행","example":"The campfire is glowing softly against the dark trees behind the tents.","exampleTranslation":"모닥불이 텐트 뒤편의 어두운 나무들을 배경으로 부드럽게 빛나고 있다.","sense":"빛나다"},{"wordId":16380,"answer":"more gradual","form":"비교급","example":"Doctors recommended a much more gradual return to exercise after her knee surgery.","exampleTranslation":"의사들은 그녀의 무릎 수술 이후 훨씬 더 점진적인 운동 복귀를 권했다.","sense":"점진적인"},{"wordId":16380,"answer":"gradually","form":"부사형","example":"The town gradually recovered after the factory reopened and jobs returned.","exampleTranslation":"그 공장이 다시 문을 열고 일자리가 돌아오면서 마을은 점차 회복되었다.","sense":"점진적인"},{"wordId":16381,"answer":"most graphic","form":"최상급","example":"The documentary included some of the most graphic footage ever shown on television.","exampleTranslation":"그 다큐멘터리는 텔레비전에서 방영된 것 중 가장 생생한 장면 일부를 포함했다.","sense":"노골적인","alts":["most vivid"]},{"wordId":16381,"answer":"graphically","form":"부사형","example":"The witness described the accident graphically, making several jurors visibly uncomfortable.","exampleTranslation":"그 목격자는 사고를 생생하게 묘사해서 배심원 여러 명을 눈에 띄게 불편하게 만들었다.","sense":"생생한"},{"wordId":16382,"answer":"grasping","form":"-ing형","example":"The new students spent the whole lesson grasping the basic rules of grammar.","exampleTranslation":"신입 학생들은 수업 내내 기본 문법 규칙을 이해하는 데 시간을 보냈다.","sense":"이해하다"},{"wordId":16382,"answer":"was grasped","form":"수동태","example":"The complicated tax law was grasped quickly by only a few accountants.","exampleTranslation":"그 복잡한 세법은 극소수의 회계사들에게만 빠르게 이해되었다.","sense":"이해하다"},{"wordId":16383,"answer":"gravest","form":"최상급","example":"Doctors warned that ignoring the symptoms could lead to the gravest possible outcome.","exampleTranslation":"의사들은 증상을 무시하면 가장 심각한 결과로 이어질 수 있다고 경고했다.","sense":"중대한","alts":["most acute","most serious"]},{"wordId":16383,"answer":"grave","form":"원형","example":"News of the factory closing left a grave silence hanging over the entire town meeting.","exampleTranslation":"공장 폐쇄 소식은 마을 전체 회의에 심각한 침묵을 드리웠다.","sense":"심각한"},{"wordId":16384,"answer":"monkeyed","form":"과거형","example":"My little cousin monkeyed around with the television remote until it broke.","exampleTranslation":"내 어린 사촌은 텔레비전 리모컨을 만지작거리며 장난치다가 결국 고장 냈다.","sense":"장난치다"},{"wordId":16384,"answer":"has monkeyed","form":"현재완료","example":"The technician has monkeyed with these old settings twice this week already.","exampleTranslation":"그 기술자는 이번 주에만 벌써 두 번이나 이 오래된 설정을 만지작거렸다.","sense":"만지작거리다"},{"wordId":16385,"answer":"mowed","form":"과거분사","example":"The freshly mowed lawn smelled wonderful after the gardener finished that afternoon.","exampleTranslation":"정원사가 그날 오후 일을 마친 뒤, 갓 깎은 잔디에서 좋은 냄새가 났다.","sense":"잔디를 깎다"},{"wordId":16385,"answer":"will mow","form":"미래","example":"Our neighbor will mow both yards this weekend while we are traveling.","exampleTranslation":"우리 이웃은 우리가 여행하는 동안 이번 주말에 두 마당의 잔디를 깎아 줄 것이다.","sense":"잔디를 깎다"},{"wordId":16386,"answer":"mud","form":"원형","example":"The dog tracked mud all over the freshly cleaned kitchen floor.","exampleTranslation":"그 개는 갓 청소한 부엌 바닥 곳곳에 진흙 발자국을 남겼다.","sense":"진흙"},{"wordId":16387,"answer":"nails","form":"3인칭 단수형","example":"The carpenter always nails the corner boards first before starting the frame.","exampleTranslation":"그 목수는 틀을 시작하기 전에 항상 모서리 판자를 먼저 못으로 박는다.","sense":"못으로 박다"},{"wordId":16387,"answer":"is nailing","form":"현재진행","example":"My father is nailing new shingles onto the roof before winter arrives.","exampleTranslation":"우리 아버지는 겨울이 오기 전에 지붕에 새 지붕널을 못으로 박고 계신다.","sense":"못으로 박다"},{"wordId":16388,"answer":"nannies","form":"복수형","example":"The agency placed two experienced nannies with families this month.","exampleTranslation":"그 소개소는 이번 달에 경험 많은 보모 두 명을 가정에 배치했다.","sense":"보모"},{"wordId":16389,"answer":"nastiest","form":"최상급","example":"That was by far the nastiest cold he had caught in the past five years.","exampleTranslation":"그것은 지난 오 년 동안 그가 걸린 것 중 단연 가장 고약한 감기였다.","sense":"고약한"},{"wordId":16389,"answer":"nastiness","form":"명사형","example":"The comment section revealed a surprising amount of nastiness toward the young singer.","exampleTranslation":"그 댓글란은 그 젊은 가수를 향한 놀랄 만큼 많은 고약함을 드러냈다.","sense":"고약한"},{"wordId":16390,"answer":"navy","form":"원형","example":"For the formal dinner, he chose a plain navy suit instead of his usual black one.","exampleTranslation":"그 격식 있는 저녁 자리를 위해 그는 평소의 검은 정장 대신 수수한 짙은 남색 정장을 골랐다.","sense":"짙은 남색의"},{"wordId":16390,"answer":"navy","form":"원형","example":"The company changed its logo color from bright red to a simple navy tone.","exampleTranslation":"그 회사는 로고 색상을 밝은 빨강에서 단순한 짙은 남색 톤으로 바꿨다.","sense":"짙은 남색의"},{"wordId":16391,"answer":"nests","form":"3인칭 단수형","example":"This particular species usually nests high up in the tallest pine trees.","exampleTranslation":"이 특정 종은 보통 가장 높은 소나무 위쪽에 둥지를 튼다.","sense":"둥지를 틀다"},{"wordId":16391,"answer":"is nesting","form":"현재진행","example":"A pair of sparrows is nesting quietly under the porch roof this spring.","exampleTranslation":"참새 한 쌍이 이번 봄 처마 지붕 아래 조용히 둥지를 틀고 있다.","sense":"둥지를 틀다"},{"wordId":16392,"answer":"November","form":"원형","example":"The election results will not be finalized until sometime in November.","exampleTranslation":"선거 결과는 11월 중이 되어서야 최종 확정될 것이다.","sense":"11월"},{"wordId":16393,"answer":"nuts","form":"복수형","example":"The trail mix contains three kinds of nuts and dried fruit.","exampleTranslation":"그 트레일 믹스에는 견과 세 종류와 말린 과일이 들어 있다.","sense":"견과"},{"wordId":16394,"answer":"oaks","form":"복수형","example":"Two towering oaks shaded the entire front yard of the farmhouse.","exampleTranslation":"우뚝 솟은 참나무 두 그루가 그 농가 앞뜰 전체를 그늘지게 했다.","sense":"참나무"},{"wordId":16395,"answer":"October","form":"원형","example":"Tourists flock to New England to see the colors in October.","exampleTranslation":"관광객들은 10월에 단풍을 보려고 뉴잉글랜드로 몰려든다.","sense":"10월"},{"wordId":16396,"answer":"where","form":"원형","example":"Nobody could remember where the spare key had been hidden.","exampleTranslation":"아무도 여분의 열쇠가 어디에 숨겨져 있었는지 기억하지 못했다.","sense":"어디에"},{"wordId":16398,"answer":"gravity","form":"원형","example":"Astronauts train for months to adapt to reduced gravity in space.","exampleTranslation":"우주비행사들은 우주에서 약해진 중력에 적응하려고 몇 달간 훈련한다.","sense":"중력"},{"wordId":16399,"answer":"grips","form":"3인칭 단수형","example":"He always grips the steering wheel tightly whenever traffic gets heavy.","exampleTranslation":"그는 교통이 혼잡해질 때마다 항상 운전대를 꽉 잡는다.","sense":"꽉 잡다"},{"wordId":16399,"answer":"is gripping","form":"현재진행","example":"The climber is gripping the narrow ledge firmly while she waits for rescue.","exampleTranslation":"그 등반가는 구조를 기다리는 동안 좁은 바위 턱을 단단히 꽉 잡고 있다.","sense":"꽉 잡다"},{"wordId":16400,"answer":"grossest","form":"최상급","example":"Of all the school lunches served that week, Tuesday's fish stew was the grossest.","exampleTranslation":"그 주에 제공된 모든 학교 급식 중에서 화요일의 생선 스튜가 가장 역겨웠다.","sense":"역겨운"},{"wordId":16400,"answer":"grossly","form":"부사형","example":"The report claimed that the workers were grossly underpaid compared to similar jobs nearby.","exampleTranslation":"그 보고서는 근로자들이 인근의 비슷한 일자리에 비해 터무니없이 적은 임금을 받는다고 주장했다.","sense":"역겨운"},{"wordId":16401,"answer":"halted","form":"과거분사","example":"The halted train sat quietly on the tracks for nearly two hours.","exampleTranslation":"멈춰 선 기차는 거의 두 시간 동안 철로 위에서 조용히 서 있었다.","sense":"정지시키다","alts":["stopped"]},{"wordId":16401,"answer":"will halt","form":"미래","example":"Production will halt completely next Monday for the annual factory inspection.","exampleTranslation":"생산은 연례 공장 점검을 위해 다음 주 월요일에 완전히 멈출 것이다.","sense":"정지하다","alts":["will stop"]},{"wordId":16402,"answer":"harsher","form":"비교급","example":"The judge gave a much harsher sentence than the defense attorney had expected.","exampleTranslation":"그 판사는 변호인이 예상했던 것보다 훨씬 더 가혹한 형을 선고했다.","sense":"가혹한"},{"wordId":16402,"answer":"harshly","form":"부사형","example":"The critic wrote harshly about the film, calling it a complete waste of talent.","exampleTranslation":"그 평론가는 그 영화를 완전한 재능 낭비라고 부르며 가혹하게 혹평했다.","sense":"가혹한"},{"wordId":16403,"answer":"hazards","form":"3인칭 단수형","example":"The old fisherman rarely hazards a guess about tomorrow's unpredictable weather.","exampleTranslation":"그 늙은 어부는 내일의 예측할 수 없는 날씨에 대해 좀처럼 짐작해 말하지 않는다.","sense":"짐작하다"},{"wordId":16403,"answer":"is hazarding","form":"현재진행","example":"The intern is hazarding a guess about the final sales numbers already.","exampleTranslation":"그 인턴은 벌써 최종 매출 수치에 대해 짐작해서 말하고 있다.","sense":"짐작하다"},{"wordId":16404,"answer":"healed","form":"과거형","example":"The deep cut on his hand healed completely within about ten days.","exampleTranslation":"그의 손에 난 깊은 상처는 열흘 정도 안에 완전히 치유되었다.","sense":"치유하다"},{"wordId":16404,"answer":"has healed","form":"현재완료","example":"Her broken wrist has healed nicely since the accident last autumn.","exampleTranslation":"지난가을 사고 이후로 그녀의 부러진 손목은 잘 치유되었다.","sense":"치유하다"},{"wordId":16405,"answer":"heels","form":"복수형","example":"She twisted both heels while running down the rocky trail.","exampleTranslation":"그녀는 바위투성이 오솔길을 뛰어 내려가다가 양쪽 발뒤꿈치를 삐었다.","sense":"발뒤꿈치"},{"wordId":16406,"answer":"heritage","form":"원형","example":"The festival celebrates the region's rich cultural heritage every autumn.","exampleTranslation":"그 축제는 매년 가을 그 지역의 풍부한 문화유산을 기념한다.","sense":"유산"},{"wordId":16407,"answer":"highways","form":"복수형","example":"Two major highways connect the capital to the northern port cities.","exampleTranslation":"주요 고속도로 두 개가 수도와 북쪽 항구 도시들을 연결한다.","sense":"고속도로","alts":["expressways"]},{"wordId":16408,"answer":"hips","form":"복수형","example":"The physical therapist stretched both hips gently after the surgery.","exampleTranslation":"물리치료사는 수술 후 양쪽 골반을 부드럽게 스트레칭했다.","sense":"골반"},{"wordId":16409,"answer":"holiest","form":"최상급","example":"Pilgrims consider this ancient shrine the holiest site in the entire region.","exampleTranslation":"순례자들은 이 오래된 사당을 그 지역 전체에서 가장 신성한 장소로 여긴다.","sense":"성스러운","alts":["most sacred"]},{"wordId":16409,"answer":"holiness","form":"명사형","example":"The monk spoke about holiness as something built through daily small acts.","exampleTranslation":"그 수도승은 신성함이 매일의 작은 행동을 통해 쌓이는 것이라고 이야기했다.","sense":"신성한"},{"wordId":16410,"answer":"horror","form":"원형","example":"The witnesses stared in horror as the building collapsed suddenly.","exampleTranslation":"목격자들은 건물이 갑자기 무너지자 공포에 질려 바라보았다.","sense":"공포"},{"wordId":16411,"answer":"most hostile","form":"최상급","example":"Of all the negotiations that year, this one turned out to be the most hostile.","exampleTranslation":"그 해의 모든 협상 중에서 이번 협상이 가장 적대적인 것으로 드러났다.","sense":"적대적인"},{"wordId":16411,"answer":"hostility","form":"명사형","example":"Years of hostility between the two families finally ended with a quiet apology.","exampleTranslation":"두 가문 사이의 오랜 적대감은 마침내 조용한 사과로 끝이 났다.","sense":"적대적인"},{"wordId":16412,"answer":"ideologies","form":"복수형","example":"The debate compared two competing ideologies shaping modern politics.","exampleTranslation":"그 토론은 현대 정치를 형성하는 경쟁하는 이념 두 가지를 비교했다.","sense":"이념"},{"wordId":16413,"answer":"more immune","form":"비교급","example":"Regular exercise seemed to make him more immune to the stress of his new job.","exampleTranslation":"규칙적인 운동은 그가 새 직장의 스트레스에 더 잘 견디게 해 주는 것 같았다.","sense":"견디는"},{"wordId":16413,"answer":"immunity","form":"명사형","example":"The vaccine gives children strong immunity against several dangerous childhood diseases.","exampleTranslation":"그 백신은 아이들에게 여러 위험한 소아 질병에 대한 강한 면역력을 준다.","sense":"면역이 있는"},{"wordId":16414,"answer":"impacting","form":"-ing형","example":"The prolonged drought is impacting local farmers across the entire region.","exampleTranslation":"장기화된 가뭄이 그 지역 전체의 농부들에게 영향을 미치고 있다.","sense":"영향을 미치다"},{"wordId":16414,"answer":"were impacted","form":"수동태","example":"Small businesses downtown were impacted heavily by the sudden road closure.","exampleTranslation":"시내 소규모 상점들은 갑작스러운 도로 폐쇄로 큰 영향을 받았다.","sense":"충격을 주다","alts":["was swayed"]},{"wordId":16415,"answer":"imperial","form":"원형","example":"Archaeologists uncovered coins bearing the face of a long-forgotten imperial ruler.","exampleTranslation":"고고학자들은 오래전 잊힌 제국 통치자의 얼굴이 새겨진 동전을 발견했다.","sense":"제국의"},{"wordId":16415,"answer":"imperial","form":"원형","example":"The museum displays several imperial robes once worn by rulers of the ancient dynasty.","exampleTranslation":"그 박물관은 그 고대 왕조의 통치자들이 한때 입었던 여러 제국 예복을 전시한다.","sense":"제국의"},{"wordId":16416,"answer":"implicated","form":"과거형","example":"New financial records implicated the treasurer in the missing funds case.","exampleTranslation":"새 재무 기록은 그 회계 담당자를 실종된 자금 사건에 연루시켰다.","sense":"연루시키다"},{"wordId":16416,"answer":"has implicated","form":"현재완료","example":"The leaked email has implicated two senior managers in the scandal already.","exampleTranslation":"그 유출된 이메일은 벌써 고위 관리자 두 명을 그 스캔들에 연루시켰다.","sense":"연루시키다"},{"wordId":16417,"answer":"more inevitable","form":"비교급","example":"After three straight quarters of losses, shutting down the branch felt more inevitable than ever.","exampleTranslation":"세 분기 연속 손실을 낸 뒤 그 지점을 닫는 일은 그 어느 때보다 더 불가피해 보였다.","sense":"불가피한"},{"wordId":16417,"answer":"inevitability","form":"명사형","example":"She finally accepted the inevitability of moving away from her childhood home.","exampleTranslation":"그녀는 어린 시절 살던 집을 떠나야 하는 불가피함을 마침내 받아들였다.","sense":"불가피한"},{"wordId":16418,"answer":"infecting","form":"-ing형","example":"A single careless cough kept infecting more coworkers throughout the crowded office.","exampleTranslation":"부주의한 기침 한 번이 붐비는 사무실 곳곳에서 더 많은 동료를 계속 감염시켰다.","sense":"감염시키다"},{"wordId":16418,"answer":"was infected","form":"수동태","example":"The old computer was infected badly by a virus from an unknown email.","exampleTranslation":"그 낡은 컴퓨터는 출처를 알 수 없는 이메일의 바이러스로 심하게 감염되었다.","sense":"감염시키다"},{"wordId":16419,"answer":"inflates","form":"3인칭 단수형","example":"Warm air usually inflates this balloon faster than cold air does.","exampleTranslation":"따뜻한 공기는 보통 차가운 공기보다 이 풍선을 더 빨리 부풀린다.","sense":"부풀리다"},{"wordId":16419,"answer":"is inflating","form":"현재진행","example":"He is inflating the pool toys quickly before the children arrive.","exampleTranslation":"그는 아이들이 도착하기 전에 서둘러 수영장 놀이 기구에 바람을 넣고 있다.","sense":"부풀리다"},{"wordId":16420,"answer":"inhabited","form":"과거형","example":"A small tribe once inhabited this remote valley many centuries ago.","exampleTranslation":"작은 부족이 여러 세기 전 이 외딴 계곡에 거주했었다.","sense":"거주하다"},{"wordId":16420,"answer":"has inhabited","form":"현재완료","example":"This ancient species has inhabited these caves for thousands of years already.","exampleTranslation":"이 고대 종은 벌써 수천 년 동안 이 동굴들에 거주해 왔다.","sense":"거주하다"},{"wordId":16421,"answer":"inherited","form":"과거분사","example":"The inherited house needed major repairs before anyone could live there.","exampleTranslation":"그 상속받은 집은 누군가 살기 전에 큰 수리가 필요했다.","sense":"상속받다"},{"wordId":16421,"answer":"will inherit","form":"미래","example":"Her younger brother will inherit the family farm after their father retires.","exampleTranslation":"그녀의 남동생은 아버지가 은퇴하신 뒤 가족 농장을 상속받을 것이다.","sense":"상속받다"},{"wordId":16422,"answer":"initiating","form":"-ing형","example":"The board spent the entire session initiating several major reforms at once.","exampleTranslation":"이사회는 회기 내내 여러 주요 개혁을 한꺼번에 시작했다.","sense":"시작하다"},{"wordId":16422,"answer":"was initiated","form":"수동태","example":"A full investigation was initiated immediately after the complaint arrived.","exampleTranslation":"그 항의가 접수된 직후 전면적인 조사가 즉시 시작되었다.","sense":"시작하다"},{"wordId":16423,"answer":"onions","form":"복수형","example":"She diced two onions before adding them to the simmering stew.","exampleTranslation":"그녀는 끓고 있는 스튜에 넣기 전 양파 두 개를 잘게 썰었다.","sense":"양파"},{"wordId":16426,"answer":"ovens","form":"복수형","example":"The bakery installed two industrial ovens to keep up with demand.","exampleTranslation":"그 빵집은 수요를 맞추려고 산업용 오븐 두 대를 설치했다.","sense":"오븐"},{"wordId":16427,"answer":"pans","form":"복수형","example":"She washed three pans after cooking a big family dinner.","exampleTranslation":"그녀는 가족을 위한 큰 저녁을 요리한 뒤 냄비 세 개를 씻었다.","sense":"프라이팬","alts":["pots"]},{"wordId":16428,"answer":"patted","form":"과거형","example":"He gently patted the nervous dog before leading it into the vet's office.","exampleTranslation":"그는 긴장한 강아지를 수의사 진료실로 데려가기 전에 부드럽게 쓰다듬었다.","sense":"쓰다듬다"},{"wordId":16428,"answer":"has patted","form":"현재완료","example":"The coach has patted every player on the back after tonight's win.","exampleTranslation":"그 감독은 오늘 밤 승리 후 선수 모두의 등을 두드려 쓰다듬어 주었다.","sense":"쓰다듬다"},{"wordId":16429,"answer":"petting","form":"-ing형","example":"The toddler kept petting the calm old cat throughout the entire visit.","exampleTranslation":"그 어린아이는 방문 내내 계속 차분한 늙은 고양이를 쓰다듬었다.","sense":"쓰다듬다","alts":["caressing"]},{"wordId":16429,"answer":"will pet","form":"미래","example":"My niece will pet every animal at the farm during tomorrow's field trip.","exampleTranslation":"내 조카는 내일 현장 학습에서 농장의 동물을 모두 쓰다듬을 것이다.","sense":"쓰다듬다","alts":["will caress"]},{"wordId":16430,"answer":"pies","form":"복수형","example":"Grandma baked three pies for the neighborhood potluck dinner.","exampleTranslation":"할머니는 동네 포틀럭 저녁 모임을 위해 파이 세 개를 구웠다.","sense":"파이"},{"wordId":16431,"answer":"pins","form":"3인칭 단수형","example":"The tailor usually pins the fabric first before making any final cuts.","exampleTranslation":"재단사는 보통 마지막으로 자르기 전에 먼저 천을 핀으로 고정한다.","sense":"핀으로 고정하다"},{"wordId":16431,"answer":"is pinning","form":"현재진행","example":"She is pinning the paper decorations onto the bulletin board right now.","exampleTranslation":"그녀는 지금 종이 장식을 게시판에 핀으로 고정하고 있다.","sense":"핀으로 고정하다"},{"wordId":16432,"answer":"pined","form":"과거형","example":"The old sailor pined for the sea for many years after he retired.","exampleTranslation":"그 늙은 선원은 은퇴한 뒤 여러 해 동안 바다를 그리워했다.","sense":"그리워하다"},{"wordId":16432,"answer":"has pined","form":"현재완료","example":"My grandfather has pined for his old hometown since he moved to the city.","exampleTranslation":"우리 할아버지는 도시로 이사 온 이후로 옛 고향을 그리워해 오셨다.","sense":"그리워하다"},{"wordId":16433,"answer":"pitying","form":"-ing형","example":"She spent the whole conversation pitying her friend instead of offering real advice.","exampleTranslation":"그녀는 진짜 조언을 해 주는 대신 대화 내내 친구를 불쌍히 여기기만 했다.","sense":"불쌍히 여기다"},{"wordId":16433,"answer":"will pity","form":"미래","example":"Nobody will pity the greedy landlord after tenants learn the whole story.","exampleTranslation":"세입자들이 자초지종을 알게 되면 아무도 그 탐욕스러운 집주인을 불쌍히 여기지 않을 것이다.","sense":"불쌍히 여기다"},{"wordId":16434,"answer":"plugging","form":"-ing형","example":"The electrician spent an hour plugging in each new appliance carefully.","exampleTranslation":"전기 기사는 한 시간 동안 새 가전제품을 하나하나 조심스럽게 연결했다.","sense":"연결하다"},{"wordId":16434,"answer":"was plugged","form":"수동태","example":"The old refrigerator was plugged directly into the kitchen outlet last week.","exampleTranslation":"그 낡은 냉장고는 지난주 주방 콘센트에 바로 연결되었다.","sense":"꽂다","alts":["was connected"]},{"wordId":16436,"answer":"injected","form":"과거형","example":"The nurse injected the vaccine carefully into the patient's upper arm.","exampleTranslation":"간호사는 환자의 위팔에 조심스럽게 백신을 주입했다.","sense":"주입하다"},{"wordId":16436,"answer":"has injected","form":"현재완료","example":"The clinic has injected nearly two hundred patients since the campaign began.","exampleTranslation":"그 병원은 캠페인이 시작된 이후로 거의 이백 명의 환자에게 주사를 놓았다.","sense":"주입하다"},{"wordId":16437,"answer":"innovating","form":"-ing형","example":"This small startup keeps innovating faster than any of its larger rivals.","exampleTranslation":"이 작은 신생 기업은 어떤 큰 경쟁사보다도 더 빠르게 계속 혁신하고 있다.","sense":"혁신하다"},{"wordId":16437,"answer":"will innovate","form":"미래","example":"Our engineering team will innovate constantly to keep the product competitive.","exampleTranslation":"우리 엔지니어링 팀은 제품의 경쟁력을 지키기 위해 끊임없이 혁신할 것이다.","sense":"혁신하다"},{"wordId":16438,"answer":"inserting","form":"-ing형","example":"The clerk spent a moment inserting the customer's card into the payment machine.","exampleTranslation":"직원은 잠시 결제기에 고객의 카드를 삽입했다.","sense":"삽입하다"},{"wordId":16438,"answer":"was inserted","form":"수동태","example":"A small metal chip was inserted quietly beneath the museum's oldest painting.","exampleTranslation":"박물관의 가장 오래된 그림 아래에 작은 금속 칩이 조용히 삽입되었다.","sense":"삽입하다"},{"wordId":16439,"answer":"instincts","form":"복수형","example":"Wild animals rely on sharp instincts to avoid nearby predators.","exampleTranslation":"야생 동물은 근처의 포식자를 피하려고 예리한 본능에 의존한다.","sense":"본능"},{"wordId":16440,"answer":"instituted","form":"과거형","example":"The new principal instituted a stricter attendance policy right away.","exampleTranslation":"새 교장은 곧바로 더 엄격한 출석 정책을 도입했다.","sense":"도입하다"},{"wordId":16440,"answer":"has instituted","form":"현재완료","example":"The hospital has instituted several new safety checks since last year's incident.","exampleTranslation":"그 병원은 작년 사고 이후로 여러 새로운 안전 점검을 도입했다.","sense":"도입하다"},{"wordId":16441,"answer":"interacting","form":"-ing형","example":"The manager watched employees interacting naturally with customers during the busy lunch rush.","exampleTranslation":"그 매니저는 바쁜 점심시간 동안 직원들이 고객과 자연스럽게 소통하는 모습을 지켜보았다.","sense":"상호작용하다"},{"wordId":16441,"answer":"will interact","form":"미래","example":"New employees will interact with several departments during their first training week.","exampleTranslation":"신입 직원들은 첫 교육 주간 동안 여러 부서와 소통할 것이다.","sense":"상호작용하다"},{"wordId":16442,"answer":"interfering","form":"-ing형","example":"Her mother kept interfering with every small decision about the wedding plans.","exampleTranslation":"그녀의 어머니는 결혼식 계획의 사소한 결정 하나하나에 계속 간섭했다.","sense":"간섭하다"},{"wordId":16442,"answer":"is interfering","form":"현재진행","example":"The loud construction noise is interfering with our afternoon phone calls again.","exampleTranslation":"시끄러운 공사 소음이 오늘도 우리 오후 통화에 다시 간섭하고 있다.","sense":"간섭하다"},{"wordId":16443,"answer":"intervenes","form":"3인칭 단수형","example":"The teacher usually intervenes quickly whenever a small argument starts in class.","exampleTranslation":"그 선생님은 교실에서 작은 다툼이 시작될 때마다 보통 재빨리 개입한다.","sense":"개입하다"},{"wordId":16443,"answer":"is intervening","form":"현재진행","example":"The government is intervening directly in the ongoing labor dispute this week.","exampleTranslation":"정부는 이번 주 진행 중인 노동 분쟁에 직접 개입하고 있다.","sense":"개입하다"},{"wordId":16444,"answer":"most intimate","form":"최상급","example":"Of all her friendships, the one with her college roommate remained the most intimate.","exampleTranslation":"그녀의 모든 우정 중에서 대학 룸메이트와의 관계가 가장 친밀하게 남았다.","sense":"친밀한"},{"wordId":16444,"answer":"intimacy","form":"명사형","example":"Working night shifts together for years created an unexpected intimacy between two coworkers.","exampleTranslation":"몇 년간 함께 야간 근무를 하면서 두 동료 사이에는 예상치 못한 친밀감이 생겼다.","sense":"친밀한"},{"wordId":16445,"answer":"invasions","form":"복수형","example":"Historians studied two invasions that reshaped the ancient kingdom's borders.","exampleTranslation":"역사학자들은 그 고대 왕국의 국경을 바꾼 침략 두 번을 연구했다.","sense":"침략"},{"wordId":16446,"answer":"irony","form":"원형","example":"Nobody seemed to notice the irony in his complaint about being late.","exampleTranslation":"아무도 그가 지각에 대해 불평하는 것의 아이러니를 알아채지 못한 듯했다.","sense":"아이러니"},{"wordId":16447,"answer":"jets","form":"3인칭 단수형","example":"The busy executive often jets off to another country almost every week.","exampleTranslation":"그 바쁜 임원은 거의 매주 다른 나라로 훌쩍 떠난다.","sense":"훌쩍 떠나다"},{"wordId":16447,"answer":"are jetting","form":"현재진행","example":"The newlyweds are jetting off to a tiny island for their honeymoon right now.","exampleTranslation":"신혼부부는 지금 신혼여행을 위해 작은 섬으로 훌쩍 떠나고 있다.","sense":"훌쩍 떠나다"},{"wordId":16448,"answer":"legends","form":"복수형","example":"The old fisherman knew several legends about ghost ships in the bay.","exampleTranslation":"그 늙은 어부는 만에 나타나는 유령선에 관한 전설 여러 편을 알고 있었다.","sense":"전설"},{"wordId":16449,"answer":"legislating","form":"-ing형","example":"Lawmakers spent the entire session legislating against unsafe workplace conditions.","exampleTranslation":"국회의원들은 회기 내내 안전하지 못한 근무 환경에 맞서 입법했다.","sense":"입법하다"},{"wordId":16449,"answer":"will legislate","form":"미래","example":"The new parliament will legislate on climate policy sometime next year.","exampleTranslation":"새 의회는 내년 언젠가 기후 정책에 관해 입법할 것이다.","sense":"입법하다"},{"wordId":16450,"answer":"more legitimate","form":"비교급","example":"The second proposal seemed far more legitimate once the missing paperwork was found.","exampleTranslation":"빠졌던 서류가 발견되자 두 번째 제안서가 훨씬 더 정당해 보였다.","sense":"정당한"},{"wordId":16450,"answer":"legitimacy","form":"명사형","example":"Critics questioned the legitimacy of the election after several irregularities emerged.","exampleTranslation":"비평가들은 여러 부정 사례가 드러난 뒤 그 선거의 정당성에 의문을 제기했다.","sense":"정당한","alts":["legality"]},{"wordId":16451,"answer":"liable","form":"원형","example":"A landlord can be held liable when an unrepaired stairway causes a tenant injury.","exampleTranslation":"고쳐지지 않은 계단이 세입자 부상을 일으키면 집주인이 책임을 질 수 있다.","sense":"책임이 있는"},{"wordId":16451,"answer":"liability","form":"명사형","example":"The company's lawyer explained the liability the store faced after the customer's fall.","exampleTranslation":"그 회사 변호사는 고객이 넘어진 뒤 그 가게가 지게 된 법적 책임을 설명했다.","sense":"책임이 있는","alts":["accountability"]},{"wordId":16452,"answer":"liberated","form":"과거형","example":"Allied soldiers liberated the small town after weeks of fierce fighting.","exampleTranslation":"연합군 병사들은 몇 주간의 치열한 전투 끝에 그 작은 마을을 해방시켰다.","sense":"해방시키다"},{"wordId":16452,"answer":"has liberated","form":"현재완료","example":"This new software has liberated our team from hours of repetitive paperwork.","exampleTranslation":"이 새 소프트웨어는 우리 팀을 반복적인 서류 작업에서 해방시켜 주었다.","sense":"해방시키다"},{"wordId":16453,"answer":"liberty","form":"원형","example":"The new law was seen as a threat to personal liberty.","exampleTranslation":"그 새 법은 개인의 자유에 대한 위협으로 여겨졌다.","sense":"자유"},{"wordId":16454,"answer":"literal","form":"원형","example":"My grandmother's warning about the icy front steps was completely literal, not an exaggeration.","exampleTranslation":"할머니가 얼어붙은 현관 계단에 대해 하신 경고는 과장이 아니라 완전히 문자 그대로였다.","sense":"문자 그대로의"},{"wordId":16454,"answer":"literally","form":"부사형","example":"She literally ran the entire distance without stopping once for water.","exampleTranslation":"그녀는 물 한 번 마시려고도 멈추지 않고 말 그대로 그 거리를 내내 뛰었다.","sense":"문자 그대로의"},{"wordId":16455,"answer":"lobbies","form":"3인칭 단수형","example":"This industry group regularly lobbies lawmakers for looser environmental rules.","exampleTranslation":"이 업계 단체는 정기적으로 더 느슨한 환경 규정을 위해 의원들에게 로비한다.","sense":"로비하다"},{"wordId":16455,"answer":"is lobbying","form":"현재진행","example":"The tenant association is lobbying the city council for stronger rent protections.","exampleTranslation":"세입자 협회는 더 강력한 임대료 보호를 위해 시의회에 로비하고 있다.","sense":"로비하다"},{"wordId":16456,"answer":"lodged","form":"과거형","example":"The angry customer lodged a formal complaint with the store manager.","exampleTranslation":"화가 난 고객은 매장 관리자에게 정식으로 항의를 제기했다.","sense":"제기하다"},{"wordId":16456,"answer":"have lodged","form":"현재완료","example":"Several neighbors have lodged noise complaints against the new bar downtown.","exampleTranslation":"여러 이웃이 시내에 새로 생긴 술집에 소음 항의를 제기해 왔다.","sense":"제기하다"},{"wordId":16457,"answer":"most loyal","form":"최상급","example":"Among all the employees, he has always been considered the most loyal to the founder.","exampleTranslation":"모든 직원 중에서 그는 항상 창업자에게 가장 충실한 사람으로 여겨져 왔다.","sense":"충실한"},{"wordId":16457,"answer":"loyalty","form":"명사형","example":"The store rewards loyalty with discounts for customers who shop there every month.","exampleTranslation":"그 가게는 매달 방문하는 고객에게 할인으로 충성도를 보상한다.","sense":"충실한"},{"wordId":16458,"answer":"magnets","form":"복수형","example":"The teacher used two strong magnets to demonstrate basic physics.","exampleTranslation":"선생님은 기초 물리를 보여 주려고 강한 자석 두 개를 사용했다.","sense":"자석"},{"wordId":16459,"answer":"manifests","form":"3인칭 단수형","example":"Stress often manifests itself as headaches or trouble sleeping at night.","exampleTranslation":"스트레스는 종종 두통이나 밤에 잠을 못 이루는 것으로 나타난다.","sense":"드러나다","alts":["appears"]},{"wordId":16459,"answer":"is manifesting","form":"현재진행","example":"Her anxiety is manifesting itself as constant worry about small daily tasks.","exampleTranslation":"그녀의 불안감은 사소한 일상 업무에 대한 끊임없는 걱정으로 나타나고 있다.","sense":"드러나다","alts":["is appearing"]},{"wordId":16460,"answer":"manipulated","form":"과거형","example":"He manipulated the data slightly to make his final results look stronger.","exampleTranslation":"그는 최종 결과가 더 좋아 보이도록 데이터를 살짝 조작했다.","sense":"조작하다","alts":["fabricated"]},{"wordId":16460,"answer":"has manipulated","form":"현재완료","example":"The lobbyist has manipulated public opinion through several misleading advertisements.","exampleTranslation":"그 로비스트는 여러 오해의 소지가 있는 광고를 통해 여론을 조종해 왔다.","sense":"조작하다","alts":["has fabricated","has steered"]},{"wordId":16461,"answer":"manual","form":"원형","example":"The old washing machine required manual adjustment of the water level for every load.","exampleTranslation":"그 낡은 세탁기는 매번 물 높이를 수동으로 조절해야 했다.","sense":"수동의"},{"wordId":16461,"answer":"manually","form":"부사형","example":"The technician had to manually restart the printer after the power outage.","exampleTranslation":"그 기술자는 정전 이후 수동으로 프린터를 다시 시작해야 했다.","sense":"수동의"},{"wordId":16462,"answer":"marine","form":"원형","example":"The young researcher spent her summer cataloging marine species found along the rocky shoreline.","exampleTranslation":"그 젊은 연구자는 여름 내내 바위투성이 해안선을 따라 발견된 해양 생물종을 목록화했다.","sense":"해양의"},{"wordId":16462,"answer":"marine","form":"원형","example":"The aquarium opened a new marine exhibit featuring rescued sea turtles and rays.","exampleTranslation":"그 수족관은 구조된 바다거북과 가오리를 특징으로 한 새로운 해양 전시관을 열었다.","sense":"해양의"},{"wordId":16463,"answer":"poisons","form":"3인칭 단수형","example":"Untreated waste from the factory often poisons the small river nearby.","exampleTranslation":"공장에서 나오는 미처리 폐수는 종종 근처의 작은 강을 오염시킨다.","sense":"오염시키다","alts":["pollutes"]},{"wordId":16463,"answer":"is poisoning","form":"현재진행","example":"This chemical leak is poisoning the local water supply right now.","exampleTranslation":"이 화학 물질 누출은 지금 지역 상수도를 오염시키고 있다.","sense":"오염시키다","alts":["is polluting"]},{"wordId":16464,"answer":"poles","form":"복수형","example":"Workers installed several tall poles to support the new power lines.","exampleTranslation":"인부들은 새 전력선을 지지하려고 높은 막대 여러 개를 설치했다.","sense":"막대"},{"wordId":16465,"answer":"polished","form":"과거분사","example":"The polished silver tray reflected every light in the dining room.","exampleTranslation":"잘 닦아 놓은 은쟁반은 식당의 모든 불빛을 비추었다.","sense":"닦다"},{"wordId":16465,"answer":"will polish","form":"미래","example":"The staff will polish every window before tomorrow's grand opening.","exampleTranslation":"직원들은 내일 있을 개장 전에 창문을 모두 닦을 것이다.","sense":"닦다"},{"wordId":16466,"answer":"most polite","form":"최상급","example":"Of all the customers that day, the elderly gentleman was by far the most polite.","exampleTranslation":"그날의 모든 고객 중에서 그 노신사가 단연 가장 예의 발랐다.","sense":"예의 바른"},{"wordId":16466,"answer":"politely","form":"부사형","example":"She politely declined the extra dessert, saying she was already quite full.","exampleTranslation":"그녀는 이미 배가 많이 부르다며 추가 디저트를 정중하게 사양했다.","sense":"예의 바른"},{"wordId":16467,"answer":"pollutes","form":"3인칭 단수형","example":"Heavy traffic downtown pollutes the air noticeably during the morning commute.","exampleTranslation":"시내의 극심한 교통 체증은 아침 출근 시간에 눈에 띄게 공기를 오염시킨다.","sense":"오염시키다","alts":["poisons"]},{"wordId":16467,"answer":"is polluting","form":"현재진행","example":"The nearby chemical plant is polluting the groundwater beneath several homes.","exampleTranslation":"인근 화학 공장은 여러 가정 지하의 지하수를 오염시키고 있다.","sense":"오염시키다","alts":["is poisoning"]},{"wordId":16468,"answer":"presumed","form":"과거형","example":"The rescue team presumed the missing hiker had taken shelter from the storm.","exampleTranslation":"구조팀은 실종된 등산객이 폭풍을 피해 대피했을 것이라고 추정했다.","sense":"추정하다"},{"wordId":16468,"answer":"has presumed","form":"현재완료","example":"The court has presumed his innocence throughout the entire lengthy trial.","exampleTranslation":"법원은 길었던 재판 내내 그의 무죄를 추정해 왔다.","sense":"추정하다","alts":["has reckoned"]},{"wordId":16469,"answer":"privacy","form":"원형","example":"Many users worry about their privacy when using social media apps.","exampleTranslation":"많은 사용자는 소셜 미디어 앱을 사용할 때 자신의 사생활을 걱정한다.","sense":"사생활"},{"wordId":16470,"answer":"pronouncing","form":"-ing형","example":"The teacher spent extra time pronouncing each difficult word slowly for the class.","exampleTranslation":"선생님은 학급을 위해 어려운 단어마다 천천히 발음하는 데 추가 시간을 들였다.","sense":"발음하다"},{"wordId":16470,"answer":"was pronounced","form":"수동태","example":"The foreign name was pronounced correctly only after several gentle corrections.","exampleTranslation":"그 외국 이름은 여러 번의 부드러운 교정 끝에야 제대로 발음되었다.","sense":"발음하다"},{"wordId":16471,"answer":"pudding","form":"원형","example":"For dessert, the children happily ate warm chocolate pudding.","exampleTranslation":"아이들은 디저트로 따뜻한 초콜릿 푸딩을 신나게 먹었다.","sense":"푸딩"},{"wordId":16474,"answer":"mechanics","form":"복수형","example":"The garage employs three skilled mechanics who specialize in electric cars.","exampleTranslation":"그 정비소는 전기차를 전문으로 하는 숙련된 정비공 세 명을 고용하고 있다.","sense":"정비공"},{"wordId":16475,"answer":"migrates","form":"3인칭 단수형","example":"This species usually migrates south long before the first snow falls.","exampleTranslation":"이 종은 보통 첫눈이 내리기 훨씬 전에 남쪽으로 이주한다.","sense":"이주하다"},{"wordId":16475,"answer":"is migrating","form":"현재진행","example":"A large group of workers is migrating toward the growing coastal cities.","exampleTranslation":"많은 노동자 집단이 성장하는 해안 도시들을 향해 이주하고 있다.","sense":"이주하다"},{"wordId":16476,"answer":"miners","form":"복수형","example":"Two miners were trapped underground after the sudden collapse.","exampleTranslation":"광부 두 명이 갑작스러운 붕괴 이후 지하에 갇혔다.","sense":"광부"},{"wordId":16477,"answer":"ministries","form":"복수형","example":"The government merged two ministries to streamline its operations.","exampleTranslation":"정부는 운영을 간소화하려고 부처 두 곳을 통합했다.","sense":"부처"},{"wordId":16478,"answer":"missiles","form":"복수형","example":"The military tested three missiles in the remote desert range.","exampleTranslation":"군은 외딴 사막 시험장에서 미사일 세 발을 시험 발사했다.","sense":"미사일"},{"wordId":16479,"answer":"most modest","form":"최상급","example":"Compared to his flashy coworkers, he lived the most modest lifestyle in the entire office.","exampleTranslation":"화려한 동료들과 비교했을 때 그는 사무실 전체에서 가장 검소한 생활 방식으로 살았다.","sense":"검소한"},{"wordId":16479,"answer":"modesty","form":"명사형","example":"Her modesty made it hard for her to accept praise for the award.","exampleTranslation":"그녀의 겸손함 때문에 그 상에 대한 칭찬을 받아들이기 어려웠다.","sense":"겸손한"},{"wordId":16480,"answer":"molecules","form":"복수형","example":"This compound contains several oxygen molecules bonded to carbon atoms.","exampleTranslation":"이 화합물은 탄소 원자에 결합된 산소 분자 여러 개를 포함한다.","sense":"분자"},{"wordId":16481,"answer":"monsters","form":"복수형","example":"The animated film featured two friendly monsters living in a cave.","exampleTranslation":"그 애니메이션 영화에는 동굴에 사는 다정한 괴물 두 마리가 등장했다.","sense":"괴물"},{"wordId":16482,"answer":"mortal","form":"원형","example":"No matter how powerful they seemed, the ancient kings in these legends were still mortal.","exampleTranslation":"아무리 강력해 보여도 이 전설 속 고대 왕들은 여전히 죽을 운명이었다.","sense":"죽을 운명의"},{"wordId":16482,"answer":"mortal","form":"원형","example":"The knight suffered a mortal wound during the final battle near the castle gate.","exampleTranslation":"그 기사는 성문 근처에서 벌어진 마지막 전투에서 치명적인 상처를 입었다.","sense":"치명적인"},{"wordId":16483,"answer":"motives","form":"복수형","example":"Detectives considered several possible motives for the strange robbery.","exampleTranslation":"형사들은 그 이상한 강도 사건의 여러 가능한 동기를 고려했다.","sense":"동기","alts":["incentives"]},{"wordId":16484,"answer":"myths","form":"복수형","example":"The lecture debunked several common myths about nutrition and weight loss.","exampleTranslation":"그 강연은 영양과 체중 감량에 관한 흔한 통념 여러 가지를 반박했다.","sense":"통념"},{"wordId":16485,"answer":"naked","form":"원형","example":"That comet was bright enough for skywatchers to notice using nothing more than naked eyes.","exampleTranslation":"그 혜성은 망원경 없이 그저 육안만으로도 하늘을 보는 사람들이 알아챌 만큼 밝았다.","sense":"있는 그대로의"},{"wordId":16485,"answer":"naked","form":"원형","example":"The scientist examined the sample under a microscope since it was invisible to the naked eye.","exampleTranslation":"그 과학자는 그것이 육안으로는 보이지 않아 현미경으로 표본을 살펴보았다.","sense":"있는 그대로의"},{"wordId":16486,"answer":"narrating","form":"-ing형","example":"The grandmother spent the evening narrating stories about her childhood in the countryside.","exampleTranslation":"할머니는 저녁 시간 동안 시골에서 보낸 어린 시절 이야기를 들려주셨다.","sense":"이야기하다"},{"wordId":16486,"answer":"was narrated","form":"수동태","example":"The nature series was narrated beautifully by a well-known actor.","exampleTranslation":"그 자연 다큐멘터리 시리즈는 유명한 배우가 아름답게 내레이션을 맡았다.","sense":"이야기하다"},{"wordId":16487,"answer":"more neutral","form":"비교급","example":"The judge worked hard to stay more neutral than either divorcing parent expected.","exampleTranslation":"그 판사는 이혼하는 부모 양쪽이 예상했던 것보다 더 중립적인 태도를 유지하려 애썼다.","sense":"중립적인"},{"wordId":16487,"answer":"neutrality","form":"명사형","example":"The referee's neutrality was questioned after several controversial calls during the final match.","exampleTranslation":"그 심판의 중립성은 결승전 동안 여러 논란이 된 판정 이후 의문시되었다.","sense":"중립적인"}]`);export{e as default};